def has_safe_repr(value: t.Any) -> bool:
    """Does the node have a safe representation?"""
    if value is None or value is NotImplemented or value is Ellipsis:
        return True

    if type(value) in {bool, int, float, complex, range, str, Markup}:
        return True

    if type(value) in {tuple, list, set, frozenset}:
        return all(has_safe_repr(v) for v in value)

    if type(value) is dict:  # noqa E721
        return all(has_safe_repr(k) and has_safe_repr(v) for k, v in value.items())

    return False

def find_undeclared(
    nodes: t.Iterable[nodes.Node], names: t.Iterable[str]
) -> t.Set[str]:
    """Check if the names passed are accessed undeclared.  The return value
    is a set of all the undeclared names from the sequence of names found.
    """
    visitor = UndeclaredNameVisitor(names)
    try:
        for node in nodes:
            visitor.visit(node)
    except VisitorExit:
        pass
    return visitor.undeclared

def inner(self, isolated: bool = False) -> "Frame":
    """Return an inner frame."""
    if isolated:
        return Frame(self.eval_ctx, level=self.symbols.level + 1)
    return Frame(self.eval_ctx, self)

def __init__(self) -> None:
    self.filters: t.Set[str] = set()
    self.tests: t.Set[str] = set()

def visit_Filter(self, node: nodes.Filter) -> None:
    self.generic_visit(node)
    self.filters.add(node.name)

def visit_Test(self, node: nodes.Test) -> None:
    self.generic_visit(node)
    self.tests.add(node.name)

def __init__(self, names: t.Iterable[str]) -> None:
    self.names = set(names)
    self.undeclared: t.Set[str] = set()

def visit_Name(self, node: nodes.Name) -> None:
    if node.ctx == "load" and node.name in self.names:
        self.undeclared.add(node.name)
        if self.undeclared == self.names:
            raise VisitorExit()
    else:
        self.names.discard(node.name)

@property
def optimized(self) -> bool:
    return self.optimizer is not None

def fail(self, msg: str, lineno: int) -> "te.NoReturn":
    """Fail with a :exc:`TemplateAssertionError`."""
    raise TemplateAssertionError(msg, lineno, self.name, self.filename)

def indent(self) -> None:
    """Indent by one."""
    self._indentation += 1

def outdent(self, step: int = 1) -> None:
    """Outdent by step."""
    self._indentation -= step

def start_write(self, frame: Frame, node: t.Optional[nodes.Node] = None) -> None:
    """Yield or write into the frame buffer."""
    if frame.buffer is None:
        self.writeline("yield ", node)
    else:
        self.writeline(f"{frame.buffer}.append(", node)

def end_write(self, frame: Frame) -> None:
    """End the writing process started by `start_write`."""
    if frame.buffer is not None:
        self.write(")")

def blockvisit(self, nodes: t.Iterable[nodes.Node], frame: Frame) -> None:
    """Visit a list of nodes as block in a frame.  If the current frame
    is no buffer a dummy ``if 0: yield None`` is written automatically.
    """
    try:
        self.writeline("pass")
        for node in nodes:
            self.visit(node, frame)
    except CompilerExit:
        pass

def write(self, x: str) -> None:
    """Write a string into the output stream."""
    if self._new_lines:
        if not self._first_write:
            self.stream.write("\n" * self._new_lines)
            self.code_lineno += self._new_lines
            if self._write_debug_info is not None:
                self.debug_info.append((self._write_debug_info, self.code_lineno))
                self._write_debug_info = None
        self._first_write = False
        self.stream.write("    " * self._indentation)
        self._new_lines = 0
    self.stream.write(x)

def writeline(
    self, x: str, node: t.Optional[nodes.Node] = None, extra: int = 0
) -> None:
    """Combination of newline and write."""
    self.newline(node, extra)
    self.write(x)

def newline(self, node: t.Optional[nodes.Node] = None, extra: int = 0) -> None:
    """Add one or more newlines before the next write."""
    self._new_lines = max(self._new_lines, 1 + extra)
    if node is not None and node.lineno != self._last_line:
        self._write_debug_info = node.lineno
        self._last_line = node.lineno

def signature(
    self,
    node: t.Union[nodes.Call, nodes.Filter, nodes.Test],
    frame: Frame,
    extra_kwargs: t.Optional[t.Mapping[str, t.Any]] = None,
) -> None:
    """Writes a function call to the stream for the current node.
    A leading comma is added automatically.  The extra keyword
    arguments may not include python keywords otherwise a syntax
    error could occur.  The extra keyword arguments should be given
    as python dict.
    """
    # if any of the given keyword arguments is a python keyword
    # we have to make sure that no invalid call is created.
    kwarg_workaround = any(
        is_python_keyword(t.cast(str, k))
        for k in chain((x.key for x in node.kwargs), extra_kwargs or ())
    )

    for arg in node.args:
        self.write(", ")
        self.visit(arg, frame)

    if not kwarg_workaround:
        for kwarg in node.kwargs:
            self.write(", ")
            self.visit(kwarg, frame)
        if extra_kwargs is not None:
            for key, value in extra_kwargs.items():
                self.write(f", {key}={value}")
    if node.dyn_args:
        self.write(", *")
        self.visit(node.dyn_args, frame)

    if kwarg_workaround:
        if node.dyn_kwargs is not None:
            self.write(", **dict({")
        else:
            self.write(", **{")
        for kwarg in node.kwargs:
            self.write(f"{kwarg.key!r}: ")
            self.visit(kwarg.value, frame)
            self.write(", ")
        if extra_kwargs is not None:
            for key, value in extra_kwargs.items():
                self.write(f"{key!r}: {value}, ")
        if node.dyn_kwargs is not None:
            self.write("}, **")
            self.visit(node.dyn_kwargs, frame)
            self.write(")")
        else:
            self.write("}")

    elif node.dyn_kwargs is not None:
        self.write(", **")
        self.visit(node.dyn_kwargs, frame)

def enter_frame(self, frame: Frame) -> None:
    undefs = []
    for target, (action, param) in frame.symbols.loads.items():
        if action == VAR_LOAD_PARAMETER:
            pass
        elif action == VAR_LOAD_RESOLVE:
            self.writeline(f"{target} = {self.get_resolve_func()}({param!r})")
        elif action == VAR_LOAD_ALIAS:
            self.writeline(f"{target} = {param}")
        elif action == VAR_LOAD_UNDEFINED:
            undefs.append(target)
        else:
            raise NotImplementedError("unknown load instruction")
    if undefs:
        self.writeline(f"{' = '.join(undefs)} = missing")

def leave_frame(self, frame: Frame, with_python_scope: bool = False) -> None:
    if not with_python_scope:
        undefs = []
        for target in frame.symbols.loads:
            undefs.append(target)
        if undefs:
            self.writeline(f"{' = '.join(undefs)} = missing")

def position(self, node: nodes.Node) -> str:
    """Return a human readable position for the node."""
    rv = f"line {node.lineno}"
    if self.name is not None:
        rv = f"{rv} in {self.name!r}"
    return rv

def dump_local_context(self, frame: Frame) -> str:
    items_kv = ", ".join(
        f"{name!r}: {target}"
        for name, target in frame.symbols.dump_stores().items()
    )
    return f"{{{items_kv}}}"

def pop_parameter_definitions(self) -> None:
    """Pops the current parameter definitions set."""
    self._param_def_block.pop()

def mark_parameter_stored(self, target: str) -> None:
    """Marks a parameter in the current parameter definitions as stored.
    This will skip the enforced undefined checks.
    """
    if self._param_def_block:
        self._param_def_block[-1].discard(target)

def get_resolve_func(self) -> str:
    target = self._context_reference_stack[-1]
    if target == "context":
        return "resolve"
    return f"{target}.resolve"

def parameter_is_undeclared(self, target: str) -> bool:
    """Checks if a given target is an undeclared parameter."""
    if not self._param_def_block:
        return False
    return target in self._param_def_block[-1]

def push_assign_tracking(self) -> None:
    """Pushes a new layer for assignment tracking."""
    self._assign_stack.append(set())

def pop_assign_tracking(self, frame: Frame) -> None:
    """Pops the topmost level for assignment tracking and updates the
    context variables if necessary.
    """
    vars = self._assign_stack.pop()
    if (
        not frame.block_frame
        and not frame.loop_frame
        and not frame.toplevel
        or not vars
    ):
        return
    public_names = [x for x in vars if x[:1] != "_"]
    if len(vars) == 1:
        name = next(iter(vars))
        ref = frame.symbols.ref(name)
        if frame.loop_frame:
            self.writeline(f"_loop_vars[{name!r}] = {ref}")
            return
        if frame.block_frame:
            self.writeline(f"_block_vars[{name!r}] = {ref}")
            return
        self.writeline(f"context.vars[{name!r}] = {ref}")
    else:
        if frame.loop_frame:
            self.writeline("_loop_vars.update({")
        elif frame.block_frame:
            self.writeline("_block_vars.update({")
        else:
            self.writeline("context.vars.update({")
        for idx, name in enumerate(sorted(vars)):
            if idx:
                self.write(", ")
            ref = frame.symbols.ref(name)
            self.write(f"{name!r}: {ref}")
        self.write("})")
    if not frame.block_frame and not frame.loop_frame and public_names:
        if len(public_names) == 1:
            self.writeline(f"context.exported_vars.add({public_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, sorted(public_names)))
            self.writeline(f"context.exported_vars.update(({names_str}))")

def _import_common(
    self, node: t.Union[nodes.Import, nodes.FromImport], frame: Frame
) -> None:
    self.write(f"{self.choose_async('await ')}environment.get_template(")
    self.visit(node.template, frame)
    self.write(f", {self.name!r}).")

    if node.with_context:
        f_name = f"make_module{self.choose_async('_async')}"
        self.write(
            f"{f_name}(context.get_all(), True, {self.dump_local_context(frame)})"
        )
    else:
        self.write(f"_get_default_module{self.choose_async('_async')}(context)")

def visit_Import(self, node: nodes.Import, frame: Frame) -> None:
    """Visit regular imports."""
    self.writeline(f"{frame.symbols.ref(node.target)} = ", node)
    if frame.toplevel:
        self.write(f"context.vars[{node.target!r}] = ")

    self._import_common(node, frame)

    if frame.toplevel and not node.target.startswith("_"):
        self.writeline(f"context.exported_vars.discard({node.target!r})")

def visit_FromImport(self, node: nodes.FromImport, frame: Frame) -> None:
    """Visit named imports."""
    self.newline(node)
    self.write("included_template = ")
    self._import_common(node, frame)
    var_names = []
    discarded_names = []
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        self.writeline(
            f"{frame.symbols.ref(alias)} ="
            f" getattr(included_template, {name!r}, missing)"
        )
        self.writeline(f"if {frame.symbols.ref(alias)} is missing:")
        self.indent()
        # The position will contain the template name, and will be formatted
        # into a string that will be compiled into an f-string. Curly braces
        # in the name must be replaced with escapes so that they will not be
        # executed as part of the f-string.
        position = self.position(node).replace("{", "{{").replace("}", "}}")
        message = (
            "the template {included_template.__name__!r}"
            f" (imported on {position})"
            f" does not export the requested name {name!r}"
        )
        self.writeline(
            f"{frame.symbols.ref(alias)} = undefined(f{message!r}, name={name!r})"
        )
        self.outdent()
        if frame.toplevel:
            var_names.append(alias)
            if not alias.startswith("_"):
                discarded_names.append(alias)

    if var_names:
        if len(var_names) == 1:
            name = var_names[0]
            self.writeline(f"context.vars[{name!r}] = {frame.symbols.ref(name)}")
        else:
            names_kv = ", ".join(
                f"{name!r}: {frame.symbols.ref(name)}" for name in var_names
            )
            self.writeline(f"context.vars.update({{{names_kv}}})")
    if discarded_names:
        if len(discarded_names) == 1:
            self.writeline(f"context.exported_vars.discard({discarded_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, discarded_names))
            self.writeline(
                f"context.exported_vars.difference_update(({names_str}))"
            )

def visit_Macro(self, node: nodes.Macro, frame: Frame) -> None:
    macro_frame, macro_ref = self.macro_body(node, frame)
    self.newline()
    if frame.toplevel:
        if not node.name.startswith("_"):
            self.write(f"context.exported_vars.add({node.name!r})")
        self.writeline(f"context.vars[{node.name!r}] = ")
    self.write(f"{frame.symbols.ref(node.name)} = ")
    self.macro_def(macro_ref, macro_frame)

def visit_ExprStmt(self, node: nodes.ExprStmt, frame: Frame) -> None:
    self.newline(node)
    self.visit(node.node, frame)

@staticmethod
def _default_finalize(value: t.Any) -> t.Any:
    """The default finalize function if the environment isn't
    configured with one. Or, if the environment has one, this is
    called on that function's output for constants.
    """
    return str(value)

def _make_finalize(self) -> _FinalizeInfo:
    """Build the finalize function to be used on constants and at
    runtime. Cached so it's only created once for all output nodes.

    Returns a ``namedtuple`` with the following attributes:

    ``const``
        A function to finalize constant data at compile time.

    ``src``
        Source code to output around nodes to be evaluated at
        runtime.
    """
    if self._finalize is not None:
        return self._finalize

    finalize: t.Optional[t.Callable[..., t.Any]]
    finalize = default = self._default_finalize
    src = None

    if self.environment.finalize:
        src = "environment.finalize("
        env_finalize = self.environment.finalize
        pass_arg = {
            _PassArg.context: "context",
            _PassArg.eval_context: "context.eval_ctx",
            _PassArg.environment: "environment",
        }.get(
            _PassArg.from_obj(env_finalize)  # type: ignore
        )
        finalize = None

        if pass_arg is None:

            def finalize(value: t.Any) -> t.Any:  # noqa: F811
                return default(env_finalize(value))

        else:
            src = f"{src}{pass_arg}, "

            if pass_arg == "environment":

                def finalize(value: t.Any) -> t.Any:  # noqa: F811
                    return default(env_finalize(self.environment, value))

    self._finalize = self._FinalizeInfo(finalize, src)
    return self._finalize

def _output_const_repr(self, group: t.Iterable[t.Any]) -> str:
    """Given a group of constant values converted from ``Output``
    child nodes, produce a string to write to the template module
    source.
    """
    return repr(concat(group))

def _output_child_to_const(
    self, node: nodes.Expr, frame: Frame, finalize: _FinalizeInfo
) -> str:
    """Try to optimize a child of an ``Output`` node by trying to
    convert it to constant, finalized data at compile time.

    If :exc:`Impossible` is raised, the node is not constant and
    will be evaluated at runtime. Any other exception will also be
    evaluated at runtime for easier debugging.
    """
    const = node.as_const(frame.eval_ctx)

    if frame.eval_ctx.autoescape:
        const = escape(const)

    # Template data doesn't go through finalize.
    if isinstance(node, nodes.TemplateData):
        return str(const)

    return finalize.const(const)  # type: ignore

def _output_child_pre(
    self, node: nodes.Expr, frame: Frame, finalize: _FinalizeInfo
) -> None:
    """Output extra source code before visiting a child of an
    ``Output`` node.
    """
    if frame.eval_ctx.volatile:
        self.write("(escape if context.eval_ctx.autoescape else str)(")
    elif frame.eval_ctx.autoescape:
        self.write("escape(")
    else:
        self.write("str(")

    if finalize.src is not None:
        self.write(finalize.src)

def _output_child_post(
    self, node: nodes.Expr, frame: Frame, finalize: _FinalizeInfo
) -> None:
    """Output extra source code after visiting a child of an
    ``Output`` node.
    """
    self.write(")")

    if finalize.src is not None:
        self.write(")")

def visit_Output(self, node: nodes.Output, frame: Frame) -> None:
    # If an extends is active, don't render outside a block.
    if frame.require_output_check:
        # A top-level extends is known to exist at compile time.
        if self.has_known_extends:
            return

        self.writeline("if parent_template is None:")
        self.indent()

    finalize = self._make_finalize()
    body: t.List[t.Union[t.List[t.Any], nodes.Expr]] = []

    # Evaluate constants at compile time if possible. Each item in
    # body will be either a list of static data or a node to be
    # evaluated at runtime.
    for child in node.nodes:
        try:
            if not (
                # If the finalize function requires runtime context,
                # constants can't be evaluated at compile time.
                finalize.const
                # Unless it's basic template data that won't be
                # finalized anyway.
                or isinstance(child, nodes.TemplateData)
            ):
                raise nodes.Impossible()

            const = self._output_child_to_const(child, frame, finalize)
        except (nodes.Impossible, Exception):
            # The node was not constant and needs to be evaluated at
            # runtime. Or another error was raised, which is easier
            # to debug at runtime.
            body.append(child)
            continue

        if body and isinstance(body[-1], list):
            body[-1].append(const)
        else:
            body.append([const])

    if frame.buffer is not None:
        if len(body) == 1:
            self.writeline(f"{frame.buffer}.append(")
        else:
            self.writeline(f"{frame.buffer}.extend((")

        self.indent()

    for item in body:
        if isinstance(item, list):
            # A group of constant data to join and output.
            val = self._output_const_repr(item)

            if frame.buffer is None:
                self.writeline("yield " + val)
            else:
                self.writeline(val + ",")
        else:
            if frame.buffer is None:
                self.writeline("yield ", item)
            else:
                self.newline(item)

            # A node to be evaluated at runtime.
            self._output_child_pre(item, frame, finalize)
            self.visit(item, frame)
            self._output_child_post(item, frame, finalize)

            if frame.buffer is not None:
                self.write(",")

    if frame.buffer is not None:
        self.outdent()
        self.writeline(")" if len(body) == 1 else "))")

    if frame.require_output_check:
        self.outdent()

def visit_Name(self, node: nodes.Name, frame: Frame) -> None:
    if node.ctx == "store" and (
        frame.toplevel or frame.loop_frame or frame.block_frame
    ):
        if self._assign_stack:
            self._assign_stack[-1].add(node.name)
    ref = frame.symbols.ref(node.name)

    # If we are looking up a variable we might have to deal with the
    # case where it's undefined.  We can skip that case if the load
    # instruction indicates a parameter which are always defined.
    if node.ctx == "load":
        load = frame.symbols.find_load(ref)
        if not (
            load is not None
            and load[0] == VAR_LOAD_PARAMETER
            and not self.parameter_is_undeclared(ref)
        ):
            self.write(
                f"(undefined(name={node.name!r}) if {ref} is missing else {ref})"
            )
            return

    self.write(ref)

def visit_Const(self, node: nodes.Const, frame: Frame) -> None:
    val = node.as_const(frame.eval_ctx)
    if isinstance(val, float):
        self.write(str(val))
    else:
        self.write(repr(val))

def visit_TemplateData(self, node: nodes.TemplateData, frame: Frame) -> None:
    try:
        self.write(repr(node.as_const(frame.eval_ctx)))
    except nodes.Impossible:
        self.write(
            f"(Markup if context.eval_ctx.autoescape else identity)({node.data!r})"
        )

def visit_Tuple(self, node: nodes.Tuple, frame: Frame) -> None:
    self.write("(")
    idx = -1
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item, frame)
    self.write(",)" if idx == 0 else ")")

def visit_List(self, node: nodes.List, frame: Frame) -> None:
    self.write("[")
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item, frame)
    self.write("]")

def visit_Dict(self, node: nodes.Dict, frame: Frame) -> None:
    self.write("{")
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item.key, frame)
        self.write(": ")
        self.visit(item.value, frame)
    self.write("}")

@optimizeconst
def visit_Concat(self, node: nodes.Concat, frame: Frame) -> None:
    if frame.eval_ctx.volatile:
        func_name = "(markup_join if context.eval_ctx.volatile else str_join)"
    elif frame.eval_ctx.autoescape:
        func_name = "markup_join"
    else:
        func_name = "str_join"
    self.write(f"{func_name}((")
    for arg in node.nodes:
        self.visit(arg, frame)
        self.write(", ")
    self.write("))")

@optimizeconst
def visit_Compare(self, node: nodes.Compare, frame: Frame) -> None:
    self.write("(")
    self.visit(node.expr, frame)
    for op in node.ops:
        self.visit(op, frame)
    self.write(")")

def visit_Operand(self, node: nodes.Operand, frame: Frame) -> None:
    self.write(f" {operators[node.op]} ")
    self.visit(node.expr, frame)

@optimizeconst
def visit_Getattr(self, node: nodes.Getattr, frame: Frame) -> None:
    if self.environment.is_async:
        self.write("(await auto_await(")

    self.write("environment.getattr(")
    self.visit(node.node, frame)
    self.write(f", {node.attr!r})")

    if self.environment.is_async:
        self.write("))")

@optimizeconst
def visit_Getitem(self, node: nodes.Getitem, frame: Frame) -> None:
    # slices bypass the environment getitem method.
    if isinstance(node.arg, nodes.Slice):
        self.visit(node.node, frame)
        self.write("[")
        self.visit(node.arg, frame)
        self.write("]")
    else:
        if self.environment.is_async:
            self.write("(await auto_await(")

        self.write("environment.getitem(")
        self.visit(node.node, frame)
        self.write(", ")
        self.visit(node.arg, frame)
        self.write(")")

        if self.environment.is_async:
            self.write("))")

def visit_Slice(self, node: nodes.Slice, frame: Frame) -> None:
    if node.start is not None:
        self.visit(node.start, frame)
    self.write(":")
    if node.stop is not None:
        self.visit(node.stop, frame)
    if node.step is not None:
        self.write(":")
        self.visit(node.step, frame)

@contextmanager
def _filter_test_common(
    self, node: t.Union[nodes.Filter, nodes.Test], frame: Frame, is_filter: bool
) -> t.Iterator[None]:
    if self.environment.is_async:
        self.write("(await auto_await(")

    if is_filter:
        self.write(f"{self.filters[node.name]}(")
        func = self.environment.filters.get(node.name)
    else:
        self.write(f"{self.tests[node.name]}(")
        func = self.environment.tests.get(node.name)

    # When inside an If or CondExpr frame, allow the filter to be
    # undefined at compile time and only raise an error if it's
    # actually called at runtime. See pull_dependencies.
    if func is None and not frame.soft_frame:
        type_name = "filter" if is_filter else "test"
        self.fail(f"No {type_name} named {node.name!r}.", node.lineno)

    pass_arg = {
        _PassArg.context: "context",
        _PassArg.eval_context: "context.eval_ctx",
        _PassArg.environment: "environment",
    }.get(
        _PassArg.from_obj(func)  # type: ignore
    )

    if pass_arg is not None:
        self.write(f"{pass_arg}, ")

    # Back to the visitor function to handle visiting the target of
    # the filter or test.
    yield

    self.signature(node, frame)
    self.write(")")

    if self.environment.is_async:
        self.write("))")

@optimizeconst
def visit_Filter(self, node: nodes.Filter, frame: Frame) -> None:
    with self._filter_test_common(node, frame, True):
        # if the filter node is None we are inside a filter block
        # and want to write to the current buffer
        if node.node is not None:
            self.visit(node.node, frame)
        elif frame.eval_ctx.volatile:
            self.write(
                f"(Markup(concat({frame.buffer}))"
                f" if context.eval_ctx.autoescape else concat({frame.buffer}))"
            )
        elif frame.eval_ctx.autoescape:
            self.write(f"Markup(concat({frame.buffer}))")
        else:
            self.write(f"concat({frame.buffer})")

@optimizeconst
def visit_Test(self, node: nodes.Test, frame: Frame) -> None:
    with self._filter_test_common(node, frame, False):
        self.visit(node.node, frame)

def write_expr2() -> None:
    if node.expr2 is not None:
        self.visit(node.expr2, frame)
        return

    self.write(
        f'cond_expr_undefined("the inline if-expression on'
        f" {self.position(node)} evaluated to false and no else"
        f' section was defined.")'
    )

@optimizeconst
def visit_Call(
    self, node: nodes.Call, frame: Frame, forward_caller: bool = False
) -> None:
    if self.environment.is_async:
        self.write("(await auto_await(")
    if self.environment.sandboxed:
        self.write("environment.call(context, ")
    else:
        self.write("context.call(")
    self.visit(node.node, frame)
    extra_kwargs = {"caller": "caller"} if forward_caller else None
    loop_kwargs = {"_loop_vars": "_loop_vars"} if frame.loop_frame else {}
    block_kwargs = {"_block_vars": "_block_vars"} if frame.block_frame else {}
    if extra_kwargs:
        extra_kwargs.update(loop_kwargs, **block_kwargs)
    elif loop_kwargs or block_kwargs:
        extra_kwargs = dict(loop_kwargs, **block_kwargs)
    self.signature(node, frame, extra_kwargs)
    self.write(")")
    if self.environment.is_async:
        self.write("))")

def visit_Keyword(self, node: nodes.Keyword, frame: Frame) -> None:
    self.write(node.key + "=")
    self.visit(node.value, frame)

def visit_MarkSafeIfAutoescape(
    self, node: nodes.MarkSafeIfAutoescape, frame: Frame
) -> None:
    self.write("(Markup if context.eval_ctx.autoescape else identity)(")
    self.visit(node.expr, frame)
    self.write(")")

def visit_EnvironmentAttribute(
    self, node: nodes.EnvironmentAttribute, frame: Frame
) -> None:
    self.write("environment." + node.name)

def visit_ExtensionAttribute(
    self, node: nodes.ExtensionAttribute, frame: Frame
) -> None:
    self.write(f"environment.extensions[{node.identifier!r}].{node.name}")

def visit_ContextReference(
    self, node: nodes.ContextReference, frame: Frame
) -> None:
    self.write("context")

def visit_DerivedContextReference(
    self, node: nodes.DerivedContextReference, frame: Frame
) -> None:
    self.write(self.derive_context(frame))

def visit_EvalContextModifier(
    self, node: nodes.EvalContextModifier, frame: Frame
) -> None:
    for keyword in node.options:
        self.writeline(f"context.eval_ctx.{keyword.key} = ")
        self.visit(keyword.value, frame)
        try:
            val = keyword.value.as_const(frame.eval_ctx)
        except nodes.Impossible:
            frame.eval_ctx.volatile = True
        else:
            setattr(frame.eval_ctx, keyword.key, val)

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> t.Dict[str, t.Any]:
    """Based on the runtime locals, get the context that would be
    available at that point in the template.
    """
    # Start with the current template context.
    ctx: t.Optional[Context] = real_locals.get("context")

    if ctx is not None:
        data: t.Dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: t.Dict[str, t.Tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def create_cache(
    size: int,
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Return the cache class for the given size."""
    if size == 0:
        return None

    if size < 0:
        return {}

    return LRUCache(size)  # type: ignore

def copy_cache(
    cache: t.Optional[t.MutableMapping[t.Any, t.Any]],
) -> t.Optional[t.MutableMapping[t.Tuple["weakref.ref[t.Any]", str], "Template"]]:
    """Create an empty copy of the given cache."""
    if cache is None:
        return None

    if type(cache) is dict:  # noqa E721
        return {}

    return LRUCache(cache.capacity)  # type: ignore

def load_extensions(
    environment: "Environment",
    extensions: t.Sequence[t.Union[str, t.Type["Extension"]]],
) -> t.Dict[str, "Extension"]:
    """Load the extensions from the list and bind it to the environment.
    Returns a dict of instantiated extensions.
    """
    result = {}

    for extension in extensions:
        if isinstance(extension, str):
            extension = t.cast(t.Type["Extension"], import_string(extension))

        result[extension.identifier] = extension(environment)

    return result

def _environment_config_check(environment: _env_bound) -> _env_bound:
    """Perform a sanity check on the environment."""
    assert issubclass(
        environment.undefined, Undefined
    ), "'undefined' must be a subclass of 'jinja2.Undefined'."
    assert (
        environment.block_start_string
        != environment.variable_start_string
        != environment.comment_start_string
    ), "block, variable and comment start strings must be different."
    assert environment.newline_sequence in {
        "\r",
        "\r\n",
        "\n",
    }, "'newline_sequence' must be one of '\\n', '\\r\\n', or '\\r'."
    return environment

def extend(self, **attributes: t.Any) -> None:
    """Add the items to the instance of the environment if they do not exist
    yet.  This is used by :ref:`extensions <writing-extensions>` to register
    callbacks and configuration values without breaking inheritance.
    """
    for key, value in attributes.items():
        if not hasattr(self, key):
            setattr(self, key, value)

@property
def lexer(self) -> Lexer:
    """The lexer for this environment."""
    return get_lexer(self)

def iter_extensions(self) -> t.Iterator["Extension"]:
    """Iterates over the extensions by priority."""
    return iter(sorted(self.extensions.values(), key=lambda x: x.priority))

def getitem(
    self, obj: t.Any, argument: t.Union[str, t.Any]
) -> t.Union[t.Any, Undefined]:
    """Get an item or attribute of an object but prefer the item."""
    try:
        return obj[argument]
    except (AttributeError, TypeError, LookupError):
        if isinstance(argument, str):
            try:
                attr = str(argument)
            except Exception:
                pass
            else:
                try:
                    return getattr(obj, attr)
                except AttributeError:
                    pass
        return self.undefined(obj=obj, name=argument)

def getattr(self, obj: t.Any, attribute: str) -> t.Any:
    """Get an item or attribute of an object but prefer the attribute.
    Unlike :meth:`getitem` the attribute *must* be a string.
    """
    try:
        return getattr(obj, attribute)
    except AttributeError:
        pass
    try:
        return obj[attribute]
    except (TypeError, LookupError, AttributeError):
        return self.undefined(obj=obj, name=attribute)

def _filter_test_common(
    self,
    name: t.Union[str, Undefined],
    value: t.Any,
    args: t.Optional[t.Sequence[t.Any]],
    kwargs: t.Optional[t.Mapping[str, t.Any]],
    context: t.Optional[Context],
    eval_ctx: t.Optional[EvalContext],
    is_filter: bool,
) -> t.Any:
    if is_filter:
        env_map = self.filters
        type_name = "filter"
    else:
        env_map = self.tests
        type_name = "test"

    func = env_map.get(name)  # type: ignore

    if func is None:
        msg = f"No {type_name} named {name!r}."

        if isinstance(name, Undefined):
            try:
                name._fail_with_undefined_error()
            except Exception as e:
                msg = f"{msg} ({e}; did you forget to quote the callable name?)"

        raise TemplateRuntimeError(msg)

    args = [value, *(args if args is not None else ())]
    kwargs = kwargs if kwargs is not None else {}
    pass_arg = _PassArg.from_obj(func)

    if pass_arg is _PassArg.context:
        if context is None:
            raise TemplateRuntimeError(
                f"Attempted to invoke a context {type_name} without context."
            )

        args.insert(0, context)
    elif pass_arg is _PassArg.eval_context:
        if eval_ctx is None:
            if context is not None:
                eval_ctx = context.eval_ctx
            else:
                eval_ctx = EvalContext(self)

        args.insert(0, eval_ctx)
    elif pass_arg is _PassArg.environment:
        args.insert(0, self)

    return func(*args, **kwargs)

@internalcode
def parse(
    self,
    source: str,
    name: t.Optional[str] = None,
    filename: t.Optional[str] = None,
) -> nodes.Template:
    """Parse the sourcecode and return the abstract syntax tree.  This
    tree of nodes is used by the compiler to convert the template into
    executable source- or bytecode.  This is useful for debugging or to
    extract information from templates.

    If you are :ref:`developing Jinja extensions <writing-extensions>`
    this gives you a good overview of the node tree generated.
    """
    try:
        return self._parse(source, name, filename)
    except TemplateSyntaxError:
        self.handle_exception(source=source)

def _parse(
    self, source: str, name: t.Optional[str], filename: t.Optional[str]
) -> nodes.Template:
    """Internal parsing function used by `parse` and `compile`."""
    return Parser(self, source, name, filename).parse()

def _compile(self, source: str, filename: str) -> CodeType:
    """Internal hook that can be overridden to hook a different compile
    method in.

    .. versionadded:: 2.5
    """
    return compile(source, filename, "exec")

def write_file(filename: str, data: str) -> None:
    if zip:
        info = ZipInfo(filename)
        info.external_attr = 0o755 << 16
        zip_file.writestr(info, data)
    else:
        with open(os.path.join(target, filename), "wb") as f:
            f.write(data.encode("utf8"))

@internalcode
def _load_template(
    self, name: str, globals: t.Optional[t.MutableMapping[str, t.Any]]
) -> "Template":
    if self.loader is None:
        raise TypeError("no loader for this environment specified")
    cache_key = (weakref.ref(self.loader), name)
    if self.cache is not None:
        template = self.cache.get(cache_key)
        if template is not None and (
            not self.auto_reload or template.is_up_to_date
        ):
            # template.globals is a ChainMap, modifying it will only
            # affect the template, not the environment globals.
            if globals:
                template.globals.update(globals)

            return template

    template = self.loader.load(self, name, self.make_globals(globals))

    if self.cache is not None:
        self.cache[cache_key] = template
    return template

@internalcode
def get_or_select_template(
    self,
    template_name_or_list: t.Union[
        str, "Template", t.List[t.Union[str, "Template"]]
    ],
    parent: t.Optional[str] = None,
    globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
) -> "Template":
    """Use :meth:`select_template` if an iterable of template names
    is given, or :meth:`get_template` if one name is given.

    .. versionadded:: 2.3
    """
    if isinstance(template_name_or_list, (str, Undefined)):
        return self.get_template(template_name_or_list, parent, globals)
    elif isinstance(template_name_or_list, Template):
        return template_name_or_list
    return self.select_template(template_name_or_list, parent, globals)

@classmethod
def from_module_dict(
    cls,
    environment: Environment,
    module_dict: t.MutableMapping[str, t.Any],
    globals: t.MutableMapping[str, t.Any],
) -> "Template":
    """Creates a template object from a module.  This is used by the
    module loader to create a template object.

    .. versionadded:: 2.4
    """
    return cls._from_namespace(environment, module_dict, globals)

def render(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This method accepts the same arguments as the `dict` constructor:
    A dict, a dict subclass or some keyword arguments.  If no arguments
    are given the context will be empty.  These two calls do the same::

        template.render(knights='that say nih')
        template.render({'knights': 'that say nih'})

    This will return the rendered template as a string.
    """
    if self.environment.is_async:
        import asyncio

        return asyncio.run(self.render_async(*args, **kwargs))

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(self.root_render_func(ctx))  # type: ignore
    except Exception:
        self.environment.handle_exception()

async def render_async(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This works similar to :meth:`render` but returns a coroutine
    that when awaited returns the entire rendered template string.  This
    requires the async feature to be enabled.

    Example usage::

        await template.render_async(knights='that say nih; asynchronously')
    """
    if not self.environment.is_async:
        raise RuntimeError(
            "The environment was not created with async mode enabled."
        )

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(  # type: ignore
            [n async for n in self.root_render_func(ctx)]  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

def stream(self, *args: t.Any, **kwargs: t.Any) -> "TemplateStream":
    """Works exactly like :meth:`generate` but returns a
    :class:`TemplateStream`.
    """
    return TemplateStream(self.generate(*args, **kwargs))

@internalcode
def _get_default_module(self, ctx: t.Optional[Context] = None) -> "TemplateModule":
    """If a context is passed in, this means that the template was
    imported. Imported templates have access to the current
    template's globals by default, but they can only be accessed via
    the context during runtime.

    If there are new globals, we need to create a new module because
    the cached module is already rendered and will not have access
    to globals from the current context. This new module is not
    cached because the template can be imported elsewhere, and it
    should have access to only the current template's globals.
    """
    if self.environment.is_async:
        raise RuntimeError("Module is not available in async mode.")

    if ctx is not None:
        keys = ctx.globals_keys - self.globals.keys()

        if keys:
            return self.make_module({k: ctx.parent[k] for k in keys})

    if self._module is None:
        self._module = self.make_module()

    return self._module

async def _get_default_module_async(
    self, ctx: t.Optional[Context] = None
) -> "TemplateModule":
    if ctx is not None:
        keys = ctx.globals_keys - self.globals.keys()

        if keys:
            return await self.make_module_async({k: ctx.parent[k] for k in keys})

    if self._module is None:
        self._module = await self.make_module_async()

    return self._module

def get_corresponding_lineno(self, lineno: int) -> int:
    """Return the source line number of a line number in the
    generated bytecode as they are not in sync.
    """
    for template_line, code_line in reversed(self.debug_info):
        if code_line <= lineno:
            return template_line
    return 1

@property
def is_up_to_date(self) -> bool:
    """If this variable is `False` there is a newer version available."""
    if self._uptodate is None:
        return True
    return self._uptodate()

@property
def debug_info(self) -> t.List[t.Tuple[int, int]]:
    """The debug info mapping."""
    if self._debug_info:
        return [
            tuple(map(int, x.split("=")))  # type: ignore
            for x in self._debug_info.split("&")
        ]

    return []

def __repr__(self) -> str:
    if self.name is None:
        name = f"memory:{id(self):x}"
    else:
        name = repr(self.name)
    return f"<{type(self).__name__} {name}>"

def __repr__(self) -> str:
    if self.__name__ is None:
        name = f"memory:{id(self):x}"
    else:
        name = repr(self.__name__)
    return f"<{type(self).__name__} {name}>"

def __init__(self, template: Template, undefined_to_none: bool) -> None:
    self._template = template
    self._undefined_to_none = undefined_to_none

def __init__(self, gen: t.Iterator[str]) -> None:
    self._gen = gen
    self.disable_buffering()

def dump(
    self,
    fp: t.Union[str, t.IO[bytes]],
    encoding: t.Optional[str] = None,
    errors: t.Optional[str] = "strict",
) -> None:
    """Dump the complete stream into a file or file-like object.
    Per default strings are written, if you want to encode
    before writing specify an `encoding`.

    Example usage::

        Template('Hello {{ name }}!').stream(name='foo').dump('hello.html')
    """
    close = False

    if isinstance(fp, str):
        if encoding is None:
            encoding = "utf-8"

        real_fp: t.IO[bytes] = open(fp, "wb")
        close = True
    else:
        real_fp = fp

    try:
        if encoding is not None:
            iterable = (x.encode(encoding, errors) for x in self)  # type: ignore
        else:
            iterable = self  # type: ignore

        if hasattr(real_fp, "writelines"):
            real_fp.writelines(iterable)
        else:
            for item in iterable:
                real_fp.write(item)
    finally:
        if close:
            real_fp.close()

def _buffered_generator(self, size: int) -> t.Iterator[str]:
    buf: t.List[str] = []
    c_size = 0
    push = buf.append

    while True:
        try:
            while c_size < size:
                c = next(self._gen)
                push(c)
                if c:
                    c_size += 1
        except StopIteration:
            if not c_size:
                return
        yield concat(buf)
        del buf[:]
        c_size = 0

def enable_buffering(self, size: int = 5) -> None:
    """Enable buffering.  Buffer `size` items before yielding them."""
    if size <= 1:
        raise ValueError("buffer size too small")

    self.buffered = True
    self._next = partial(next, self._buffered_generator(size))

@property
def message(self) -> t.Optional[str]:
    return self.args[0] if self.args else None

def __init__(
    self,
    names: t.Sequence[t.Union[str, "Undefined"]] = (),
    message: t.Optional[str] = None,
) -> None:
    if message is None:
        from .runtime import Undefined

        parts = []

        for name in names:
            if isinstance(name, Undefined):
                parts.append(name._undefined_message)
            else:
                parts.append(name)

        parts_str = ", ".join(map(str, parts))
        message = f"none of the templates given were found: {parts_str}"

    super().__init__(names[-1] if names else None, message)
    self.templates = list(names)

def __str__(self) -> str:
    # for translated errors we only return the message
    if self.translated:
        return t.cast(str, self.message)

    # otherwise attach some stuff
    location = f"line {self.lineno}"
    name = self.filename or self.name
    if name:
        location = f'File "{name}", {location}'
    lines = [t.cast(str, self.message), "  " + location]

    # if the source is set, add the line to the output
    if self.source is not None:
        try:
            line = self.source.splitlines()[self.lineno - 1]
        except IndexError:
            pass
        else:
            lines.append("    " + line.strip())

    return "\n".join(lines)

def attr(
    self, name: str, lineno: t.Optional[int] = None
) -> nodes.ExtensionAttribute:
    """Return an attribute node for the current extension.  This is useful
    to pass constants on extensions to generated template code.

    ::

        self.attr('_my_attribute', lineno=lineno)
    """
    return nodes.ExtensionAttribute(self.identifier, name, lineno=lineno)

@pass_context
def _gettext_alias(
    __context: Context, *args: t.Any, **kwargs: t.Any
) -> t.Union[t.Any, Undefined]:
    return __context.call(__context.resolve("gettext"), *args, **kwargs)

def _make_new_gettext(func: t.Callable[[str], str]) -> t.Callable[..., str]:
    @pass_context
    def gettext(__context: Context, __string: str, **variables: t.Any) -> str:
        rv = __context.call(func, __string)
        if __context.eval_ctx.autoescape:
            rv = Markup(rv)
        # Always treat as a format string, even if there are no
        # variables. This makes translation strings more consistent
        # and predictable. This requires escaping
        return rv % variables  # type: ignore

    return gettext

@pass_context
def gettext(__context: Context, __string: str, **variables: t.Any) -> str:
    rv = __context.call(func, __string)
    if __context.eval_ctx.autoescape:
        rv = Markup(rv)
    # Always treat as a format string, even if there are no
    # variables. This makes translation strings more consistent
    # and predictable. This requires escaping
    return rv % variables  # type: ignore

def _make_new_ngettext(func: t.Callable[[str, str, int], str]) -> t.Callable[..., str]:
    @pass_context
    def ngettext(
        __context: Context,
        __singular: str,
        __plural: str,
        __num: int,
        **variables: t.Any,
    ) -> str:
        variables.setdefault("num", __num)
        rv = __context.call(func, __singular, __plural, __num)
        if __context.eval_ctx.autoescape:
            rv = Markup(rv)
        # Always treat as a format string, see gettext comment above.
        return rv % variables  # type: ignore

    return ngettext

def _make_new_pgettext(func: t.Callable[[str, str], str]) -> t.Callable[..., str]:
    @pass_context
    def pgettext(
        __context: Context, __string_ctx: str, __string: str, **variables: t.Any
    ) -> str:
        variables.setdefault("context", __string_ctx)
        rv = __context.call(func, __string_ctx, __string)

        if __context.eval_ctx.autoescape:
            rv = Markup(rv)

        # Always treat as a format string, see gettext comment above.
        return rv % variables  # type: ignore

    return pgettext

@pass_context
def pgettext(
    __context: Context, __string_ctx: str, __string: str, **variables: t.Any
) -> str:
    variables.setdefault("context", __string_ctx)
    rv = __context.call(func, __string_ctx, __string)

    if __context.eval_ctx.autoescape:
        rv = Markup(rv)

    # Always treat as a format string, see gettext comment above.
    return rv % variables  # type: ignore

def _make_new_npgettext(
    func: t.Callable[[str, str, str, int], str],
) -> t.Callable[..., str]:
    @pass_context
    def npgettext(
        __context: Context,
        __string_ctx: str,
        __singular: str,
        __plural: str,
        __num: int,
        **variables: t.Any,
    ) -> str:
        variables.setdefault("context", __string_ctx)
        variables.setdefault("num", __num)
        rv = __context.call(func, __string_ctx, __singular, __plural, __num)

        if __context.eval_ctx.autoescape:
            rv = Markup(rv)

        # Always treat as a format string, see gettext comment above.
        return rv % variables  # type: ignore

    return npgettext

def _install(
    self, translations: "_SupportedTranslations", newstyle: t.Optional[bool] = None
) -> None:
    # ugettext and ungettext are preferred in case the I18N library
    # is providing compatibility with older Python versions.
    gettext = getattr(translations, "ugettext", None)
    if gettext is None:
        gettext = translations.gettext
    ngettext = getattr(translations, "ungettext", None)
    if ngettext is None:
        ngettext = translations.ngettext

    pgettext = getattr(translations, "pgettext", None)
    npgettext = getattr(translations, "npgettext", None)
    self._install_callables(
        gettext, ngettext, newstyle=newstyle, pgettext=pgettext, npgettext=npgettext
    )

def _install_callables(
    self,
    gettext: t.Callable[[str], str],
    ngettext: t.Callable[[str, str, int], str],
    newstyle: t.Optional[bool] = None,
    pgettext: t.Optional[t.Callable[[str, str], str]] = None,
    npgettext: t.Optional[t.Callable[[str, str, str, int], str]] = None,
) -> None:
    if newstyle is not None:
        self.environment.newstyle_gettext = newstyle  # type: ignore
    if self.environment.newstyle_gettext:  # type: ignore
        gettext = _make_new_gettext(gettext)
        ngettext = _make_new_ngettext(ngettext)

        if pgettext is not None:
            pgettext = _make_new_pgettext(pgettext)

        if npgettext is not None:
            npgettext = _make_new_npgettext(npgettext)

    self.environment.globals.update(
        gettext=gettext, ngettext=ngettext, pgettext=pgettext, npgettext=npgettext
    )

def _uninstall(self, translations: "_SupportedTranslations") -> None:
    for key in ("gettext", "ngettext", "pgettext", "npgettext"):
        self.environment.globals.pop(key, None)

def _extract(
    self,
    source: t.Union[str, nodes.Template],
    gettext_functions: t.Sequence[str] = GETTEXT_FUNCTIONS,
) -> t.Iterator[
    t.Tuple[int, str, t.Union[t.Optional[str], t.Tuple[t.Optional[str], ...]]]
]:
    if isinstance(source, str):
        source = self.environment.parse(source)
    return extract_from_ast(source, gettext_functions)

def parse(self, parser: "Parser") -> t.Union[nodes.Node, t.List[nodes.Node]]:
    """Parse a translatable tag."""
    lineno = next(parser.stream).lineno

    context = None
    context_token = parser.stream.next_if("string")

    if context_token is not None:
        context = context_token.value

    # find all the variables referenced.  Additionally a variable can be
    # defined in the body of the trans block too, but this is checked at
    # a later state.
    plural_expr: t.Optional[nodes.Expr] = None
    plural_expr_assignment: t.Optional[nodes.Assign] = None
    num_called_num = False
    variables: t.Dict[str, nodes.Expr] = {}
    trimmed = None
    while parser.stream.current.type != "block_end":
        if variables:
            parser.stream.expect("comma")

        # skip colon for python compatibility
        if parser.stream.skip_if("colon"):
            break

        token = parser.stream.expect("name")
        if token.value in variables:
            parser.fail(
                f"translatable variable {token.value!r} defined twice.",
                token.lineno,
                exc=TemplateAssertionError,
            )

        # expressions
        if parser.stream.current.type == "assign":
            next(parser.stream)
            variables[token.value] = var = parser.parse_expression()
        elif trimmed is None and token.value in ("trimmed", "notrimmed"):
            trimmed = token.value == "trimmed"
            continue
        else:
            variables[token.value] = var = nodes.Name(token.value, "load")

        if plural_expr is None:
            if isinstance(var, nodes.Call):
                plural_expr = nodes.Name("_trans", "load")
                variables[token.value] = plural_expr
                plural_expr_assignment = nodes.Assign(
                    nodes.Name("_trans", "store"), var
                )
            else:
                plural_expr = var
            num_called_num = token.value == "num"

    parser.stream.expect("block_end")

    plural = None
    have_plural = False
    referenced = set()

    # now parse until endtrans or pluralize
    singular_names, singular = self._parse_block(parser, True)
    if singular_names:
        referenced.update(singular_names)
        if plural_expr is None:
            plural_expr = nodes.Name(singular_names[0], "load")
            num_called_num = singular_names[0] == "num"

    # if we have a pluralize block, we parse that too
    if parser.stream.current.test("name:pluralize"):
        have_plural = True
        next(parser.stream)
        if parser.stream.current.type != "block_end":
            token = parser.stream.expect("name")
            if token.value not in variables:
                parser.fail(
                    f"unknown variable {token.value!r} for pluralization",
                    token.lineno,
                    exc=TemplateAssertionError,
                )
            plural_expr = variables[token.value]
            num_called_num = token.value == "num"
        parser.stream.expect("block_end")
        plural_names, plural = self._parse_block(parser, False)
        next(parser.stream)
        referenced.update(plural_names)
    else:
        next(parser.stream)

    # register free names as simple name expressions
    for name in referenced:
        if name not in variables:
            variables[name] = nodes.Name(name, "load")

    if not have_plural:
        plural_expr = None
    elif plural_expr is None:
        parser.fail("pluralize without variables", lineno)

    if trimmed is None:
        trimmed = self.environment.policies["ext.i18n.trimmed"]
    if trimmed:
        singular = self._trim_whitespace(singular)
        if plural:
            plural = self._trim_whitespace(plural)

    node = self._make_node(
        singular,
        plural,
        context,
        variables,
        plural_expr,
        bool(referenced),
        num_called_num and have_plural,
    )
    node.set_lineno(lineno)
    if plural_expr_assignment is not None:
        return [plural_expr_assignment, node]
    else:
        return node

def _parse_block(
    self, parser: "Parser", allow_pluralize: bool
) -> t.Tuple[t.List[str], str]:
    """Parse until the next block tag with a given name."""
    referenced = []
    buf = []

    while True:
        if parser.stream.current.type == "data":
            buf.append(parser.stream.current.value.replace("%", "%%"))
            next(parser.stream)
        elif parser.stream.current.type == "variable_begin":
            next(parser.stream)
            name = parser.stream.expect("name").value
            referenced.append(name)
            buf.append(f"%({name})s")
            parser.stream.expect("variable_end")
        elif parser.stream.current.type == "block_begin":
            next(parser.stream)
            block_name = (
                parser.stream.current.value
                if parser.stream.current.type == "name"
                else None
            )
            if block_name == "endtrans":
                break
            elif block_name == "pluralize":
                if allow_pluralize:
                    break
                parser.fail(
                    "a translatable section can have only one pluralize section"
                )
            elif block_name == "trans":
                parser.fail(
                    "trans blocks can't be nested; did you mean `endtrans`?"
                )
            parser.fail(
                f"control structures in translatable sections are not allowed; "
                f"saw `{block_name}`"
            )
        elif parser.stream.eos:
            parser.fail("unclosed translation block")
        else:
            raise RuntimeError("internal parser error")

    return referenced, concat(buf)

def parse(self, parser: "Parser") -> t.Union[nodes.Break, nodes.Continue]:
    token = next(parser.stream)
    if token.value == "break":
        return nodes.Break(lineno=token.lineno)
    return nodes.Continue(lineno=token.lineno)

def parse(self, parser: "Parser") -> nodes.Output:
    lineno = parser.stream.expect("name:debug").lineno
    context = nodes.ContextReference()
    result = self.call_method("_render", [context], lineno=lineno)
    return nodes.Output([result], lineno=lineno)

def _render(self, context: Context) -> str:
    result = {
        "context": context.get_all(),
        "filters": sorted(self.environment.filters.keys()),
        "tests": sorted(self.environment.tests.keys()),
    }

    # Set the depth since the intent is to show the top few names.
    return pprint.pformat(result, depth=3, compact=True)

def find_backwards(self, offset: int) -> t.List[str]:
    try:
        for _, token_type, token_value in reversed(
            self.tokens[self.offset : offset]
        ):
            if token_type in ("comment", "linecomment"):
                try:
                    prefix, comment = token_value.split(None, 1)
                except ValueError:
                    continue
                if prefix in self.comment_tags:
                    return [comment.rstrip()]
        return []
    finally:
        self.offset = offset

def find_comments(self, lineno: int) -> t.List[str]:
    if not self.comment_tags or self.last_lineno > lineno:
        return []
    for idx, (token_lineno, _, _) in enumerate(self.tokens[self.offset :]):
        if token_lineno > lineno:
            return self.find_backwards(self.offset + idx)
    return self.find_backwards(len(self.tokens))

def ignore_case(value: V) -> V:
    """For use as a postprocessor for :func:`make_attrgetter`. Converts strings
    to lowercase and returns other types as-is."""
    if isinstance(value, str):
        return t.cast(V, value.lower())

    return value

def attrgetter(item: t.Any) -> t.Any:
    for part in parts:
        item = environment.getitem(item, part)

        if default is not None and isinstance(item, Undefined):
            item = default

    if postprocess is not None:
        item = postprocess(item)

    return item

def attrgetter(item: t.Any) -> t.List[t.Any]:
    items = [None] * len(parts)

    for i, attribute_part in enumerate(parts):
        item_i = item

        for part in attribute_part:
            item_i = environment.getitem(item_i, part)

        if postprocess is not None:
            item_i = postprocess(item_i)

        items[i] = item_i

    return items

def _prepare_attribute_parts(
    attr: t.Optional[t.Union[str, int]],
) -> t.List[t.Union[str, int]]:
    if attr is None:
        return []

    if isinstance(attr, str):
        return [int(x) if x.isdigit() else x for x in attr.split(".")]

    return [attr]

def do_forceescape(value: "t.Union[str, HasHTML]") -> Markup:
    """Enforce HTML escaping.  This will probably double escape variables."""
    if hasattr(value, "__html__"):
        value = t.cast("HasHTML", value).__html__()

    return escape(str(value))

def do_urlencode(
    value: t.Union[str, t.Mapping[str, t.Any], t.Iterable[t.Tuple[str, t.Any]]],
) -> str:
    """Quote data for use in a URL path or query using UTF-8.

    Basic wrapper around :func:`urllib.parse.quote` when given a
    string, or :func:`urllib.parse.urlencode` for a dict or iterable.

    :param value: Data to quote. A string will be quoted directly. A
        dict or iterable of ``(key, value)`` pairs will be joined as a
        query string.

    When given a string, "/" is not quoted. HTTP servers treat "/" and
    "%2F" equivalently in paths. If you need quoted slashes, use the
    ``|replace("/", "%2F")`` filter.

    .. versionadded:: 2.7
    """
    if isinstance(value, str) or not isinstance(value, abc.Iterable):
        return url_quote(value)

    if isinstance(value, dict):
        items: t.Iterable[t.Tuple[str, t.Any]] = value.items()
    else:
        items = value  # type: ignore

    return "&".join(
        f"{url_quote(k, for_qs=True)}={url_quote(v, for_qs=True)}" for k, v in items
    )

@pass_eval_context
def do_replace(
    eval_ctx: "EvalContext", s: str, old: str, new: str, count: t.Optional[int] = None
) -> str:
    """Return a copy of the value with all occurrences of a substring
    replaced with a new one. The first argument is the substring
    that should be replaced, the second is the replacement string.
    If the optional third argument ``count`` is given, only the first
    ``count`` occurrences are replaced:

    .. sourcecode:: jinja

        {{ "Hello World"|replace("Hello", "Goodbye") }}
            -> Goodbye World

        {{ "aaaaargh"|replace("a", "d'oh, ", 2) }}
            -> d'oh, d'oh, aaargh
    """
    if count is None:
        count = -1

    if not eval_ctx.autoescape:
        return str(s).replace(str(old), str(new), count)

    if (
        hasattr(old, "__html__")
        or hasattr(new, "__html__")
        and not hasattr(s, "__html__")
    ):
        s = escape(s)
    else:
        s = soft_str(s)

    return s.replace(soft_str(old), soft_str(new), count)

def do_upper(s: str) -> str:
    """Convert a value to uppercase."""
    return soft_str(s).upper()

def do_lower(s: str) -> str:
    """Convert a value to lowercase."""
    return soft_str(s).lower()

def do_items(value: t.Union[t.Mapping[K, V], Undefined]) -> t.Iterator[t.Tuple[K, V]]:
    """Return an iterator over the ``(key, value)`` items of a mapping.

    ``x|items`` is the same as ``x.items()``, except if ``x`` is
    undefined an empty iterator is returned.

    This filter is useful if you expect the template to be rendered with
    an implementation of Jinja in another programming language that does
    not have a ``.items()`` method on its mapping type.

    .. code-block:: html+jinja

        <dl>
        {% for key, value in my_dict|items %}
            <dt>{{ key }}
            <dd>{{ value }}
        {% endfor %}
        </dl>

    .. versionadded:: 3.1
    """
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

def do_capitalize(s: str) -> str:
    """Capitalize a value. The first character will be uppercase, all others
    lowercase.
    """
    return soft_str(s).capitalize()

def do_title(s: str) -> str:
    """Return a titlecased version of the value. I.e. words will start with
    uppercase letters, all remaining characters are lowercase.
    """
    return "".join(
        [
            item[0].upper() + item[1:].lower()
            for item in _word_beginning_split_re.split(soft_str(s))
            if item
        ]
    )

def do_dictsort(
    value: t.Mapping[K, V],
    case_sensitive: bool = False,
    by: 'te.Literal["key", "value"]' = "key",
    reverse: bool = False,
) -> t.List[t.Tuple[K, V]]:
    """Sort a dict and yield (key, value) pairs. Python dicts may not
    be in the order you want to display them in, so sort them first.

    .. sourcecode:: jinja

        {% for key, value in mydict|dictsort %}
            sort the dict by key, case insensitive

        {% for key, value in mydict|dictsort(reverse=true) %}
            sort the dict by key, case insensitive, reverse order

        {% for key, value in mydict|dictsort(true) %}
            sort the dict by key, case sensitive

        {% for key, value in mydict|dictsort(false, 'value') %}
            sort the dict by value, case insensitive
    """
    if by == "key":
        pos = 0
    elif by == "value":
        pos = 1
    else:
        raise FilterArgumentError('You can only sort by either "key" or "value"')

    def sort_func(item: t.Tuple[t.Any, t.Any]) -> t.Any:
        value = item[pos]

        if not case_sensitive:
            value = ignore_case(value)

        return value

    return sorted(value.items(), key=sort_func, reverse=reverse)

def sort_func(item: t.Tuple[t.Any, t.Any]) -> t.Any:
    value = item[pos]

    if not case_sensitive:
        value = ignore_case(value)

    return value

@async_variant(sync_do_unique)  # type: ignore
async def do_unique(
    environment: "Environment",
    value: "t.Union[t.AsyncIterable[V], t.Iterable[V]]",
    case_sensitive: bool = False,
    attribute: t.Optional[t.Union[str, int]] = None,
) -> "t.Iterator[V]":
    return sync_do_unique(
        environment, await auto_to_list(value), case_sensitive, attribute
    )

def _min_or_max(
    environment: "Environment",
    value: "t.Iterable[V]",
    func: "t.Callable[..., V]",
    case_sensitive: bool,
    attribute: t.Optional[t.Union[str, int]],
) -> "t.Union[V, Undefined]":
    it = iter(value)

    try:
        first = next(it)
    except StopIteration:
        return environment.undefined("No aggregated item, sequence was empty.")

    key_func = make_attrgetter(
        environment, attribute, postprocess=ignore_case if not case_sensitive else None
    )
    return func(chain([first], it), key=key_func)

@pass_environment
def do_min(
    environment: "Environment",
    value: "t.Iterable[V]",
    case_sensitive: bool = False,
    attribute: t.Optional[t.Union[str, int]] = None,
) -> "t.Union[V, Undefined]":
    """Return the smallest item from the sequence.

    .. sourcecode:: jinja

        {{ [1, 2, 3]|min }}
            -> 1

    :param case_sensitive: Treat upper and lower case strings as distinct.
    :param attribute: Get the object with the min value of this attribute.
    """
    return _min_or_max(environment, value, min, case_sensitive, attribute)

@pass_environment
def do_max(
    environment: "Environment",
    value: "t.Iterable[V]",
    case_sensitive: bool = False,
    attribute: t.Optional[t.Union[str, int]] = None,
) -> "t.Union[V, Undefined]":
    """Return the largest item from the sequence.

    .. sourcecode:: jinja

        {{ [1, 2, 3]|max }}
            -> 3

    :param case_sensitive: Treat upper and lower case strings as distinct.
    :param attribute: Get the object with the max value of this attribute.
    """
    return _min_or_max(environment, value, max, case_sensitive, attribute)

@pass_eval_context
def sync_do_join(
    eval_ctx: "EvalContext",
    value: t.Iterable[t.Any],
    d: str = "",
    attribute: t.Optional[t.Union[str, int]] = None,
) -> str:
    """Return a string which is the concatenation of the strings in the
    sequence. The separator between elements is an empty string per
    default, you can define it with the optional parameter:

    .. sourcecode:: jinja

        {{ [1, 2, 3]|join('|') }}
            -> 1|2|3

        {{ [1, 2, 3]|join }}
            -> 123

    It is also possible to join certain attributes of an object:

    .. sourcecode:: jinja

        {{ users|join(', ', attribute='username') }}

    .. versionadded:: 2.6
       The `attribute` parameter was added.
    """
    if attribute is not None:
        value = map(make_attrgetter(eval_ctx.environment, attribute), value)

    # no automatic escaping?  joining is a lot easier then
    if not eval_ctx.autoescape:
        return str(d).join(map(str, value))

    # if the delimiter doesn't have an html representation we check
    # if any of the items has.  If yes we do a coercion to Markup
    if not hasattr(d, "__html__"):
        value = list(value)
        do_escape = False

        for idx, item in enumerate(value):
            if hasattr(item, "__html__"):
                do_escape = True
            else:
                value[idx] = str(item)

        if do_escape:
            d = escape(d)
        else:
            d = str(d)

        return d.join(value)

    # no html involved, to normal joining
    return soft_str(d).join(map(soft_str, value))

@async_variant(sync_do_join)  # type: ignore
async def do_join(
    eval_ctx: "EvalContext",
    value: t.Union[t.AsyncIterable[t.Any], t.Iterable[t.Any]],
    d: str = "",
    attribute: t.Optional[t.Union[str, int]] = None,
) -> str:
    return sync_do_join(eval_ctx, await auto_to_list(value), d, attribute)

def do_center(value: str, width: int = 80) -> str:
    """Centers the value in a field of a given width."""
    return soft_str(value).center(width)

@pass_environment
def sync_do_first(
    environment: "Environment", seq: "t.Iterable[V]"
) -> "t.Union[V, Undefined]":
    """Return the first item of a sequence."""
    try:
        return next(iter(seq))
    except StopIteration:
        return environment.undefined("No first item, sequence was empty.")

@async_variant(sync_do_first)  # type: ignore
async def do_first(
    environment: "Environment", seq: "t.Union[t.AsyncIterable[V], t.Iterable[V]]"
) -> "t.Union[V, Undefined]":
    try:
        return await auto_aiter(seq).__anext__()
    except StopAsyncIteration:
        return environment.undefined("No first item, sequence was empty.")

@pass_environment
def do_last(
    environment: "Environment", seq: "t.Reversible[V]"
) -> "t.Union[V, Undefined]":
    """Return the last item of a sequence.

    Note: Does not work with generators. You may want to explicitly
    convert it to a list:

    .. sourcecode:: jinja

        {{ data | selectattr('name', '==', 'Jinja') | list | last }}
    """
    try:
        return next(iter(reversed(seq)))
    except StopIteration:
        return environment.undefined("No last item, sequence was empty.")

@pass_context
def do_random(context: "Context", seq: "t.Sequence[V]") -> "t.Union[V, Undefined]":
    """Return a random item from the sequence."""
    try:
        return random.choice(seq)
    except IndexError:
        return context.environment.undefined("No random item, sequence was empty.")

def do_pprint(value: t.Any) -> str:
    """Pretty print a variable. Useful for debugging."""
    return pformat(value)

def do_wordcount(s: str) -> int:
    """Count the words in that string."""
    return len(_word_re.findall(soft_str(s)))

def do_int(value: t.Any, default: int = 0, base: int = 10) -> int:
    """Convert the value into an integer. If the
    conversion doesn't work it will return ``0``. You can
    override this default using the first parameter. You
    can also override the default base (10) in the second
    parameter, which handles input with prefixes such as
    0b, 0o and 0x for bases 2, 8 and 16 respectively.
    The base is ignored for decimal numbers and non-string values.
    """
    try:
        if isinstance(value, str):
            return int(value, base)

        return int(value)
    except (TypeError, ValueError):
        # this quirk is necessary so that "42.23"|int gives 42.
        try:
            return int(float(value))
        except (TypeError, ValueError, OverflowError):
            return default

def do_float(value: t.Any, default: float = 0.0) -> float:
    """Convert the value into a floating point number. If the
    conversion doesn't work it will return ``0.0``. You can
    override this default using the first parameter.
    """
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def do_format(value: str, *args: t.Any, **kwargs: t.Any) -> str:
    """Apply the given values to a `printf-style`_ format string, like
    ``string % values``.

    .. sourcecode:: jinja

        {{ "%s, %s!"|format(greeting, name) }}
        Hello, World!

    In most cases it should be more convenient and efficient to use the
    ``%`` operator or :meth:`str.format`.

    .. code-block:: text

        {{ "%s, %s!" % (greeting, name) }}
        {{ "{}, {}!".format(greeting, name) }}

    .. _printf-style: https://docs.python.org/library/stdtypes.html
        #printf-style-string-formatting
    """
    if args and kwargs:
        raise FilterArgumentError(
            "can't handle positional and keyword arguments at the same time"
        )

    return soft_str(value) % (kwargs or args)

def do_trim(value: str, chars: t.Optional[str] = None) -> str:
    """Strip leading and trailing characters, by default whitespace."""
    return soft_str(value).strip(chars)

def do_striptags(value: "t.Union[str, HasHTML]") -> str:
    """Strip SGML/XML tags and replace adjacent whitespace by one space."""
    if hasattr(value, "__html__"):
        value = t.cast("HasHTML", value).__html__()

    return Markup(str(value)).striptags()

@async_variant(sync_do_slice)  # type: ignore
async def do_slice(
    value: "t.Union[t.AsyncIterable[V], t.Iterable[V]]",
    slices: int,
    fill_with: t.Optional[t.Any] = None,
) -> "t.Iterator[t.List[V]]":
    return sync_do_slice(await auto_to_list(value), slices, fill_with)

def do_batch(
    value: "t.Iterable[V]", linecount: int, fill_with: "t.Optional[V]" = None
) -> "t.Iterator[t.List[V]]":
    """
    A filter that batches items. It works pretty much like `slice`
    just the other way round. It returns a list of lists with the
    given number of items. If you provide a second parameter this
    is used to fill up missing items. See this example:

    .. sourcecode:: html+jinja

        <table>
        {%- for row in items|batch(3, '&nbsp;') %}
          <tr>
          {%- for column in row %}
            <td>{{ column }}</td>
          {%- endfor %}
          </tr>
        {%- endfor %}
        </table>
    """
    tmp: t.List[V] = []

    for item in value:
        if len(tmp) == linecount:
            yield tmp
            tmp = []

        tmp.append(item)

    if tmp:
        if fill_with is not None and len(tmp) < linecount:
            tmp += [fill_with] * (linecount - len(tmp))

        yield tmp

def do_round(
    value: float,
    precision: int = 0,
    method: 'te.Literal["common", "ceil", "floor"]' = "common",
) -> float:
    """Round the number to a given precision. The first
    parameter specifies the precision (default is ``0``), the
    second the rounding method:

    - ``'common'`` rounds either up or down
    - ``'ceil'`` always rounds up
    - ``'floor'`` always rounds down

    If you don't specify a method ``'common'`` is used.

    .. sourcecode:: jinja

        {{ 42.55|round }}
            -> 43.0
        {{ 42.55|round(1, 'floor') }}
            -> 42.5

    Note that even if rounded to 0 precision, a float is returned.  If
    you need a real integer, pipe it through `int`:

    .. sourcecode:: jinja

        {{ 42.55|round|int }}
            -> 43
    """
    if method not in {"common", "ceil", "floor"}:
        raise FilterArgumentError("method must be common, ceil or floor")

    if method == "common":
        return round(value, precision)

    func = getattr(math, method)
    return t.cast(float, func(value * (10**precision)) / (10**precision))

@async_variant(sync_do_sum)  # type: ignore
async def do_sum(
    environment: "Environment",
    iterable: "t.Union[t.AsyncIterable[V], t.Iterable[V]]",
    attribute: t.Optional[t.Union[str, int]] = None,
    start: V = 0,  # type: ignore
) -> V:
    rv = start

    if attribute is not None:
        func = make_attrgetter(environment, attribute)
    else:

        def func(x: V) -> V:
            return x

    async for item in auto_aiter(iterable):
        rv += func(item)

    return rv

def sync_do_list(value: "t.Iterable[V]") -> "t.List[V]":
    """Convert the value into a list.  If it was a string the returned list
    will be a list of characters.
    """
    return list(value)

@async_variant(sync_do_list)  # type: ignore
async def do_list(value: "t.Union[t.AsyncIterable[V], t.Iterable[V]]") -> "t.List[V]":
    return await auto_to_list(value)

def do_mark_safe(value: str) -> Markup:
    """Mark the value as safe which means that in an environment with automatic
    escaping enabled this variable will not be escaped.
    """
    return Markup(value)

def do_mark_unsafe(value: str) -> str:
    """Mark a value as unsafe.  This is the reverse operation for :func:`safe`."""
    return str(value)

def do_reverse(value: t.Union[str, t.Iterable[V]]) -> t.Union[str, t.Iterable[V]]:
    """Reverse the object or return an iterator that iterates over it the other
    way round.
    """
    if isinstance(value, str):
        return value[::-1]

    try:
        return reversed(value)  # type: ignore
    except TypeError:
        try:
            rv = list(value)
            rv.reverse()
            return rv
        except TypeError as e:
            raise FilterArgumentError("argument must be iterable") from e

@pass_environment
def do_attr(
    environment: "Environment", obj: t.Any, name: str
) -> t.Union[Undefined, t.Any]:
    """Get an attribute of an object. ``foo|attr("bar")`` works like
    ``foo.bar``, but returns undefined instead of falling back to ``foo["bar"]``
    if the attribute doesn't exist.

    See :ref:`Notes on subscriptions <notes-on-subscriptions>` for more details.
    """
    # Environment.getattr will fall back to obj[name] if obj.name doesn't exist.
    # But we want to call env.getattr to get behavior such as sandboxing.
    # Determine if the attr exists first, so we know the fallback won't trigger.
    try:
        # This avoids executing properties/descriptors, but misses __getattr__
        # and __getattribute__ dynamic attrs.
        getattr_static(obj, name)
    except AttributeError:
        # This finds dynamic attrs, and we know it's not a descriptor at this point.
        if not hasattr(obj, name):
            return environment.undefined(obj=obj, name=name)

    return environment.getattr(obj, name)

@async_variant(sync_do_map)  # type: ignore
async def do_map(
    context: "Context",
    value: t.Union[t.AsyncIterable[t.Any], t.Iterable[t.Any]],
    *args: t.Any,
    **kwargs: t.Any,
) -> t.AsyncIterable[t.Any]:
    if value:
        func = prepare_map(context, args, kwargs)

        async for item in auto_aiter(value):
            yield await auto_await(func(item))

@pass_context
def sync_do_select(
    context: "Context", value: "t.Iterable[V]", *args: t.Any, **kwargs: t.Any
) -> "t.Iterator[V]":
    """Filters a sequence of objects by applying a test to each object,
    and only selecting the objects with the test succeeding.

    If no test is specified, each object will be evaluated as a boolean.

    Example usage:

    .. sourcecode:: jinja

        {{ numbers|select("odd") }}
        {{ numbers|select("odd") }}
        {{ numbers|select("divisibleby", 3) }}
        {{ numbers|select("lessthan", 42) }}
        {{ strings|select("equalto", "mystring") }}

    Similar to a generator comprehension such as:

    .. code-block:: python

        (n for n in numbers if test_odd(n))
        (n for n in numbers if test_divisibleby(n, 3))

    .. versionadded:: 2.7
    """
    return select_or_reject(context, value, args, kwargs, lambda x: x, False)

@async_variant(sync_do_select)  # type: ignore
