def remove_cookie_by_name(
    cookiejar: CookieJar, name: str, domain: str | None = None, path: str | None = None
) -> None:
    """Unsets a cookie by name, by default over all domains and paths.

    Wraps CookieJar.clear(), is O(n).
    """
    clearables: list[tuple[str, str, str]] = []
    for cookie in cookiejar:
        if cookie.name != name:
            continue
        if domain is not None and domain != cookie.domain:
            continue
        if path is not None and path != cookie.path:
            continue
        clearables.append((cookie.domain, cookie.path, cookie.name))

    for domain, path, name in clearables:
        cookiejar.clear(domain, path, name)

def set(
    self, name: str, value: str | Morsel[dict[str, str]] | None, **kwargs: Any
) -> Cookie | None:
    """Dict-like set() that also supports optional domain and path args in
    order to resolve naming collisions from using one cookie jar over
    multiple domains.
    """
    # support client code that unsets cookies by assignment of a None value:
    if value is None:
        remove_cookie_by_name(
            self, name, domain=kwargs.get("domain"), path=kwargs.get("path")
        )
        return

    if isinstance(value, Morsel):
        c = morsel_to_cookie(value)
    else:
        c = create_cookie(name, value, **kwargs)
    self.set_cookie(c)
    return c

def list_domains(self) -> list[str]:
    """Utility method to list all the domains in the jar."""
    domains: list[str] = []
    for cookie in iter(self):
        if cookie.domain not in domains:
            domains.append(cookie.domain)
    return domains

def list_paths(self) -> list[str]:
    """Utility method to list all the paths in the jar."""
    paths: list[str] = []
    for cookie in iter(self):
        if cookie.path not in paths:
            paths.append(cookie.path)
    return paths

def get_dict(
    self, domain: str | None = None, path: str | None = None
) -> dict[str, str | None]:
    """Takes as an argument an optional domain and path and returns a plain
    old Python dict of name-value pairs of cookies that meet the
    requirements.

    :rtype: dict
    """
    dictionary: dict[str, str | None] = {}
    for cookie in iter(self):
        if (domain is None or cookie.domain == domain) and (
            path is None or cookie.path == path
        ):
            dictionary[cookie.name] = cookie.value
    return dictionary

def __iter__(self) -> Iterator[Cookie]:  # type: ignore[override]
    """RequestCookieJar's __iter__ comes from CookieJar not MutableMapping."""
    return super().__iter__()

def __contains__(self, name: object) -> bool:
    try:
        return super().__contains__(name)
    except CookieConflictError:
        return True

def set_cookie(self, cookie: Cookie, *args: Any, **kwargs: Any) -> None:
    if (
        (value := cookie.value) is not None
        and value.startswith('"')
        and value.endswith('"')
    ):
        cookie.value = value.replace('\\"', "")
    return super().set_cookie(cookie, *args, **kwargs)

def update(  # type: ignore[override]
    self, other: CookieJar | SupportsKeysAndGetItem[str, str]
) -> None:
    """Updates this jar with cookies from another CookieJar or dict-like"""
    if isinstance(other, cookielib.CookieJar):
        for cookie in other:
            self.set_cookie(copy.copy(cookie))
    else:
        super().update(other)

def _find(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str | None:
    """Requests uses this method internally to get cookie values.

    If there are conflicting cookies, _find arbitrarily chooses one.
    See _find_no_duplicates if you want an exception thrown if there are
    conflicting cookies.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :return: cookie.value
    """
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    return cookie.value

    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def _find_no_duplicates(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str:
    """Both ``__get_item__`` and ``get`` call this function: it's never
    used elsewhere in Requests.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :raises KeyError: if cookie is not found
    :raises CookieConflictError: if there are multiple cookies
        that match name and optionally domain and path
    :return: cookie.value
    """
    toReturn = None
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if toReturn is not None:
                        # if there are multiple cookies that meet passed in criteria
                        raise CookieConflictError(
                            f"There are multiple cookies with name, {name!r}"
                        )
                    # we will eventually return this as long as no cookie conflict
                    toReturn = cookie.value

    if toReturn is not None:
        return toReturn
    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def __setstate__(self, state: dict[str, Any]) -> None:
    """Unlike a normal CookieJar, this class is pickleable."""
    self.__dict__.update(state)
    if "_cookies_lock" not in self.__dict__:
        self._cookies_lock = threading.RLock()

def get_policy(self) -> CookiePolicy:
    """Return the CookiePolicy instance used."""
    return self._policy

def _copy_cookie_jar(jar: CookieJar | None) -> CookieJar | None:  # type: ignore[reportUnusedFunction]  # cross-module usage in models.py
    if jar is None:
        return None

    if copy_method := getattr(jar, "copy", None):
        # We're dealing with an instance of RequestsCookieJar
        return copy_method()
    # We're dealing with a generic CookieJar instance
    new_jar = copy.copy(jar)
    new_jar.clear()
    for cookie in jar:
        new_jar.set_cookie(copy.copy(cookie))
    return new_jar

def cookiejar_from_dict(
    cookie_dict: dict[str, str] | None,
    cookiejar: CookieJar | None = None,
    overwrite: bool = True,
) -> CookieJar:
    """Returns a CookieJar from a key/value dictionary.

    :param cookie_dict: Dict of key/values to insert into CookieJar.
    :param cookiejar: (optional) A cookiejar to add the cookies to.
    :param overwrite: (optional) If False, will not replace cookies
        already in the jar with new ones.
    :rtype: CookieJar
    """
    if cookiejar is None:
        cookiejar = RequestsCookieJar()

    if cookie_dict is not None:
        names_from_jar = [cookie.name for cookie in cookiejar]
        for name in cookie_dict:
            if overwrite or (name not in names_from_jar):
                cookiejar.set_cookie(create_cookie(name, cookie_dict[name]))

    return cookiejar

def merge_cookies(
    cookiejar: CookieJar, cookies: dict[str, str] | CookieJar | None
) -> CookieJar:
    """Add cookies to cookiejar and returns a merged CookieJar.

    :param cookiejar: CookieJar object to add the cookies to.
    :param cookies: Dictionary or CookieJar object to be added.
    :rtype: CookieJar
    """
    if not isinstance(cookiejar, cookielib.CookieJar):  # runtime guard
        raise ValueError("You can only merge into CookieJar")

    if isinstance(cookies, dict):
        cookiejar = cookiejar_from_dict(cookies, cookiejar=cookiejar, overwrite=False)
    elif isinstance(cookies, cookielib.CookieJar):
        if update_method := getattr(cookiejar, "update", None):
            update_method(cookies)
        else:
            for cookie_in_jar in cookies:
                cookiejar.set_cookie(cookie_in_jar)

    return cookiejar

def _implementation():
    """Return a dict with the Python implementation and version.

    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.

    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()

    if implementation == "CPython":
        implementation_version = platform.python_version()
    elif implementation == "PyPy":
        pypy = sys.pypy_version_info  # type: ignore[attr-defined]
        implementation_version = f"{pypy.major}.{pypy.minor}.{pypy.micro}"  # pyright: ignore[reportUnknownMemberType]
        if sys.pypy_version_info.releaselevel != "final":  # type: ignore[attr-defined]
            implementation_version = "".join(
                [implementation_version, sys.pypy_version_info.releaselevel]  # type: ignore[attr-defined]
            )
    elif implementation == "Jython":
        implementation_version = platform.python_version()  # Complete Guess
    elif implementation == "IronPython":
        implementation_version = platform.python_version()  # Complete Guess
    else:
        implementation_version = "Unknown"

    return {"name": implementation, "version": implementation_version}

def info() -> dict[str, Any]:
    """Generate information for a bug report."""
    try:
        platform_info = {
            "system": platform.system(),
            "release": platform.release(),
        }
    except OSError:
        platform_info = {
            "system": "Unknown",
            "release": "Unknown",
        }

    implementation_info = _implementation()
    urllib3_info = {"version": urllib3.__version__}
    charset_normalizer_info = {"version": None}
    chardet_info: dict[str, str | None] = {"version": None}
    if charset_normalizer:
        charset_normalizer_info = {"version": charset_normalizer.__version__}
    if chardet:
        chardet_info = {"version": chardet.__version__}

    pyopenssl_info: dict[str, str | None] = {
        "version": None,
        "openssl_version": "",
    }
    if OpenSSL:
        pyopenssl_info = {
            "version": OpenSSL.__version__,
            "openssl_version": f"{OpenSSL.SSL.OPENSSL_VERSION_NUMBER:x}",
        }
    cryptography_info = {
        "version": getattr(cryptography, "__version__", ""),
    }
    idna_info = {
        "version": getattr(idna, "__version__", ""),
    }

    system_ssl = ssl.OPENSSL_VERSION_NUMBER
    system_ssl_info = {"version": f"{system_ssl:x}" if system_ssl is not None else ""}  # type: ignore[reportUnnecessaryComparison]

    return {
        "platform": platform_info,
        "implementation": implementation_info,
        "system_ssl": system_ssl_info,
        "using_pyopenssl": pyopenssl is not None,
        "using_charset_normalizer": chardet is None,
        "pyOpenSSL": pyopenssl_info,
        "urllib3": urllib3_info,
        "chardet": chardet_info,
        "charset_normalizer": charset_normalizer_info,
        "cryptography": cryptography_info,
        "idna": idna_info,
        "requests": {
            "version": requests_version,
        },
    }

def main():
    """Pretty-print the bug information as JSON."""
    print(json.dumps(info(), sort_keys=True, indent=2))

def dispatch_hook(
    key: str,
    hooks: _t.HooksInputType | None,
    hook_data: Response,
    **kwargs: Any,
) -> Response:
    """Dispatches a hook dictionary on a given piece of data."""
    hooks_dict = hooks or {}
    hook_list: Iterable[_t.HookType] | _t.HookType | None = hooks_dict.get(key)
    if hook_list:
        if isinstance(hook_list, Callable):
            hook_list = [hook_list]
        for hook in hook_list:
            _hook_data = hook(hook_data, **kwargs)
            if _hook_data is not None:
                hook_data = _hook_data
    return hook_data

@property
def path_url(self) -> str:
    """Build the path URL to use."""

    url: list[str] = []

    p = urlsplit(cast(str, self.url))

    path = p.path
    if not path:
        path = "/"

    url.append(path)

    query = p.query
    if query:
        url.append("?")
        url.append(query)

    return "".join(url)

@staticmethod
def _encode_params(
    data: _t.EncodableDataType,
) -> str | bytes | _t.SupportsRead[str | bytes]:
    """Encode parameters in a piece of data.

    Will successfully encode parameters when passed as a dict or a list of
    2-tuples. Order is retained if data is a list of 2-tuples but arbitrary
    if parameters are supplied as a dict.
    """

    if isinstance(data, (str, bytes)):
        return data
    elif _t.has_read(data):
        return data
    elif hasattr(data, "__iter__"):
        result: list[tuple[bytes, bytes]] = []
        for k, vs in to_key_val_list(data):
            if isinstance(vs, basestring) or not hasattr(vs, "__iter__"):
                vs = [vs]
            for v in vs:
                if v is not None:
                    result.append(
                        (
                            k.encode("utf-8") if isinstance(k, str) else k,
                            v.encode("utf-8") if isinstance(v, str) else v,
                        )
                    )
        return urlencode(result, doseq=True)
    else:
        return data  # type: ignore[return-value]  # unreachable for valid _t.DataType

@staticmethod
def _encode_files(
    files: _t.FilesType, data: _t.RawDataType | None
) -> tuple[bytes, str]:
    """Build the body for a multipart/form-data request.

    Will successfully encode files when passed as a dict or a list of
    tuples. Order is retained if data is a list of tuples but arbitrary
    if parameters are supplied as a dict.
    The tuples may be 2-tuples (filename, fileobj), 3-tuples (filename, fileobj, contentype)
    or 4-tuples (filename, fileobj, contentype, custom_headers).
    """
    if not files:
        raise ValueError("Files must be provided.")
    elif isinstance(data, basestring):
        raise ValueError("Data must not be a string.")

    new_fields: list[RequestField | tuple[str, bytes]] = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})

    for field, val in fields:
        if isinstance(val, basestring) or not hasattr(val, "__iter__"):
            val = [val]
        for v in val:
            if v is not None:
                # Don't call str() on bytestrings: in Py3 it all goes wrong.
                if not isinstance(v, bytes):
                    v = str(v)

                new_fields.append(
                    (
                        field.decode("utf-8")
                        if isinstance(field, bytes)
                        else field,
                        v.encode("utf-8") if isinstance(v, str) else v,
                    )
                )

    for k, v in files:
        # support for explicit filename
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                fn, fp = v
            elif len(v) == 3:
                fn, fp, ft = v
            else:
                fn, fp, ft, fh = v
        else:
            fn = guess_filename(v) or k
            fp = v

        if isinstance(fp, (str, bytes, bytearray)):
            fdata = fp
        elif _t.has_read(fp):
            fdata = fp.read()
        elif fp is None:  # defensive check for untyped callers
            continue
        else:
            fdata = fp

        rf = RequestField(name=k, data=fdata, filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)

    body, content_type = encode_multipart_formdata(new_fields)

    return body, content_type

def register_hook(
    self, event: str, hook: Iterable[_t.HookType] | _t.HookType
) -> None:
    """Properly register a hook."""

    if event not in self.hooks:
        raise ValueError(f'Unsupported event specified, with event name "{event}"')

    if isinstance(hook, Callable):
        self.hooks[event].append(hook)
    elif hasattr(hook, "__iter__"):
        self.hooks[event].extend(
            h for h in hook if isinstance(h, Callable)
        )  # defensive runtime filter

def deregister_hook(self, event: str, hook: _t.HookType) -> bool:
    """Deregister a previously registered hook.
    Returns True if the hook existed, False if not.
    """

    try:
        self.hooks[event].remove(hook)
        return True
    except ValueError:
        return False

def prepare_method(self, method: str | None) -> None:
    """Prepares the given HTTP method."""
    self.method = method
    if self.method is not None:
        self.method = to_native_string(self.method.upper())

@staticmethod
def _get_idna_encoded_host(host: str) -> str:
    import idna

    try:
        host = idna.encode(host, uts46=True).decode("utf-8")
    except idna.IDNAError:
        raise UnicodeError
    return host

def prepare_url(
    self,
    url: _t.UriType,
    params: _t.ParamsType,
) -> None:
    """Prepares the given HTTP URL."""
    #: Accept objects that have string representations.
    #: We're unable to blindly call unicode/str functions
    #: as this will include the bytestring indicator (b'')
    #: on python 3.x.
    #: https://github.com/psf/requests/pull/2238
    if isinstance(url, bytes):
        url = url.decode("utf8")
    else:
        url = str(url)

    # Remove leading whitespaces from url
    url = url.lstrip()

    # Don't do any URL preparation for non-HTTP schemes like `mailto`,
    # `data` etc to work around exceptions from `url_parse`, which
    # handles RFC 3986 only.
    if ":" in url and not url.lower().startswith("http"):
        self.url = url
        return

    # Support for unicode domain names and paths.
    try:
        scheme, auth, host, port, path, query, fragment = parse_url(url)
    except LocationParseError as e:
        raise InvalidURL(*e.args)

    if not scheme:
        raise MissingSchema(
            f"Invalid URL {url!r}: No scheme supplied. "
            f"Perhaps you meant https://{url}?"
        )

    if not host:
        raise InvalidURL(f"Invalid URL {url!r}: No host supplied")

    # In general, we want to try IDNA encoding the hostname if the string contains
    # non-ASCII characters. This allows users to automatically get the correct IDNA
    # behaviour. For strings containing only ASCII characters, we need to also verify
    # it doesn't start with a wildcard (*), before allowing the unencoded hostname.
    if not unicode_is_ascii(host):
        try:
            host = self._get_idna_encoded_host(host)
        except UnicodeError:
            raise InvalidURL("URL has an invalid label.")
    elif host.startswith(("*", ".")):
        raise InvalidURL("URL has an invalid label.")

    # Carefully reconstruct the network location
    netloc = auth or ""
    if netloc:
        netloc += "@"
    netloc += host
    if port:
        netloc += f":{port}"

    # Bare domains aren't valid URLs.
    if not path:
        path = "/"

    if isinstance(params, (str, bytes)):
        params = to_native_string(params)

    if params is not None:
        enc_params = self._encode_params(params)
    else:
        enc_params = ""

    if enc_params:
        if query:
            query = f"{query}&{enc_params}"
        else:
            query = enc_params

    url = requote_uri(urlunparse((scheme, netloc, path, "", query, fragment)))
    self.url = url

def prepare_headers(self, headers: Mapping[str, str | bytes] | None) -> None:
    """Prepares the given HTTP headers."""

    self.headers = CaseInsensitiveDict()
    if headers:
        for header in headers.items():
            # Raise exception on invalid header value.
            check_header_validity(header)
            name, value = header
            self.headers[to_native_string(name)] = value

def prepare_body(
    self, data: _t.DataType, files: _t.FilesType, json: _t.JsonType = None
) -> None:
    """Prepares the given HTTP body data."""

    # Check if file, fo, generator, iterator.
    # If not, run through normal process.

    # Nottin' on you.
    body = None
    content_type = None

    if not data and json is not None:
        # urllib3 requires a bytes-like body. Python 2's json.dumps
        # provides this natively, but Python 3 gives a Unicode string.
        content_type = "application/json"

        try:
            body = complexjson.dumps(json, allow_nan=False)
        except ValueError as ve:
            raise InvalidJSONError(ve, request=self)

        if not isinstance(body, bytes):
            body = body.encode("utf-8")

    # data that proxies attributes to underlying objects needs hasattr
    is_iterable = isinstance(data, Iterable) or hasattr(data, "__iter__")
    if is_iterable and not isinstance(data, (str, bytes, list, tuple, Mapping)):
        try:
            length = super_len(data)
        except (TypeError, AttributeError, UnsupportedOperation):
            length = None

        body = data

        if getattr(body, "tell", None) is not None:
            # Record the current file position before reading.
            # This will allow us to rewind a file in the event
            # of a redirect.
            try:
                self._body_position = body.tell()  # type: ignore[union-attr]  # guarded by getattr check
            except OSError:
                # This differentiates from None, allowing us to catch
                # a failed `tell()` later when trying to rewind the body
                self._body_position = object()

        if files:
            raise NotImplementedError(
                "Streamed bodies and files are mutually exclusive."
            )

        if length:
            self.headers["Content-Length"] = builtin_str(length)
        else:
            self.headers["Transfer-Encoding"] = "chunked"
    else:
        # After is_stream filtering, remaining data is raw (not streamed)
        raw_data = cast("_t.RawDataType | None", data)

        # Multi-part file uploads.
        if files:
            (body, content_type) = self._encode_files(files, raw_data)
        else:
            if raw_data:
                body = self._encode_params(raw_data)
                if isinstance(data, basestring) or _t.has_read(data):
                    content_type = None
                else:
                    content_type = "application/x-www-form-urlencoded"

        self.prepare_content_length(body)

        # Add content-type if it wasn't explicitly provided.
        if content_type and ("content-type" not in self.headers):
            self.headers["Content-Type"] = content_type

    self.body = body  # type: ignore[assignment]  # body transforms from DataType to BodyType

def prepare_content_length(self, body: _t.BodyType) -> None:
    """Prepare Content-Length header based on request method and body"""
    if body is not None:
        length = super_len(body)
        if length:
            # If length exists, set it. Otherwise, we fallback
            # to Transfer-Encoding: chunked.
            self.headers["Content-Length"] = builtin_str(length)
    elif (
        self.method not in ("GET", "HEAD")
        and self.headers.get("Content-Length") is None
    ):
        # Set Content-Length to 0 for methods that can have a body
        # but don't provide one. (i.e. not GET or HEAD)
        self.headers["Content-Length"] = "0"

def prepare_hooks(self, hooks: _t.HooksInputType | None) -> None:
    """Prepares the given hooks."""
    # hooks can be passed as None to the prepare method and to this
    # method. To prevent iterating over None, simply use an empty list
    # if hooks is False-y
    hooks = hooks or {}
    for event in hooks:
        self.register_hook(event, hooks[event])

def __getstate__(self) -> dict[str, Any]:
    # Consume everything; accessing the content attribute makes
    # sure the content has been fully read.
    if not self._content_consumed:
        self.content

    return {attr: getattr(self, attr, None) for attr in self.__attrs__}

def __setstate__(self, state: dict[str, Any]) -> None:
    for name, value in state.items():
        setattr(self, name, value)

    # pickled objects do not have .raw
    setattr(self, "_content_consumed", True)
    setattr(self, "raw", None)

def __iter__(self) -> Iterator[bytes]:
    """Allows you to use a response as an iterator."""
    return self.iter_content(128)

@property
def ok(self) -> bool:
    """Returns True if :attr:`status_code` is less than 400, False if not.

    This attribute checks if the status code of the response is between
    400 and 600 to see if there was a client error or a server error. If
    the status code is between 200 and 400, this will return True. This
    is **not** a check to see if the response code is ``200 OK``.
    """
    try:
        self.raise_for_status()
    except HTTPError:
        return False
    return True

@property
def is_redirect(self) -> bool:
    """True if this Response is a well-formed HTTP redirect that could have
    been processed automatically (by :meth:`Session.resolve_redirects`).
    """
    return "location" in self.headers and self.status_code in REDIRECT_STATI

@property
def is_permanent_redirect(self) -> bool:
    """True if this Response one of the permanent versions of redirect."""
    return "location" in self.headers and self.status_code in (
        codes.moved_permanently,
        codes.permanent_redirect,
    )

@property
def next(self) -> PreparedRequest | None:
    """Returns a PreparedRequest for the next request in a redirect chain, if there is one."""
    return self._next

@property
def apparent_encoding(self) -> str | None:
    """The apparent encoding, provided by the charset_normalizer or chardet libraries."""
    if chardet is not None:
        return chardet.detect(self.content)["encoding"]
    else:
        # If no character detection library is available, we'll fall back
        # to a standard Python utf-8 str.
        return "utf-8"

def iter_content(
    self, chunk_size: int | None = 1, decode_unicode: bool = False
) -> Iterator[str | bytes]:
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    chunk_size must be of type int or None. A value of None will
    function differently depending on the value of `stream`.
    stream=True will read data as it arrives in whatever size the
    chunks are received. If stream=False, data is returned as
    a single chunk.

    If decode_unicode is True, content will be decoded using encoding
    information from the response. If no encoding information is available,
    bytes will be returned. This can be bypassed by manually setting
    `encoding` on the response.
    """

    def generate() -> Generator[bytes, None, None]:
        # Special case for urllib3.
        if hasattr(self.raw, "stream"):
            try:
                yield from self.raw.stream(chunk_size, decode_content=True)
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
            except SSLError as e:
                raise RequestsSSLError(e)
        else:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    elif chunk_size is not None and not isinstance(
        chunk_size, int
    ):  # runtime guard for untyped callers
        raise TypeError(
            f"chunk_size must be an int, it is instead a {type(chunk_size)}."
        )

    if self._content_consumed:
        # simulate reading small chunks of the content
        content = cast(bytes, self._content)
        chunks = iter_slices(content, chunk_size)
    else:
        chunks = generate()

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def generate() -> Generator[bytes, None, None]:
    # Special case for urllib3.
    if hasattr(self.raw, "stream"):
        try:
            yield from self.raw.stream(chunk_size, decode_content=True)
        except ProtocolError as e:
            raise ChunkedEncodingError(e)
        except DecodeError as e:
            raise ContentDecodingError(e)
        except ReadTimeoutError as e:
            raise ConnectionError(e)
        except SSLError as e:
            raise RequestsSSLError(e)
    else:
        # Standard file-like object.
        while True:
            chunk = self.raw.read(chunk_size)
            if not chunk:
                break
            yield chunk

    self._content_consumed = True

def iter_lines(
    self,
    chunk_size: int = ITER_CHUNK_SIZE,
    decode_unicode: bool = False,
    delimiter: str | bytes | None = None,
) -> Iterator[str | bytes]:
    """Iterates over the response data, one line at a time.  When
    stream=True is set on the request, this avoids reading the
    content at once into memory for large responses.

    The decode_unicode param works the same as in `iter_content`, with the
    same caveats.

    .. note:: This method is not reentrant safe.
    """

    pending: str | bytes | None = None

    for chunk in self.iter_content(
        chunk_size=chunk_size, decode_unicode=decode_unicode
    ):
        if pending is not None:
            # TODO: remove cast after iter_lines rewrite
            chunk = cast("str | bytes", pending + chunk)

        if delimiter:
            lines = chunk.split(delimiter)  # type: ignore[arg-type]
        else:
            lines = chunk.splitlines()

        if lines and lines[-1] and chunk and lines[-1][-1] == chunk[-1]:
            pending = lines.pop()
        else:
            pending = None

        yield from lines

    if pending is not None:
        yield pending

@property
def content(self) -> bytes:
    """Content of the response, in bytes."""

    if self._content is False:
        # Read the contents.
        if self._content_consumed:
            raise RuntimeError("The content for this response was already consumed")

        if self.status_code == 0 or self.raw is None:
            self._content = None
        else:
            self._content = b"".join(self.iter_content(CONTENT_CHUNK_SIZE)) or b""

    self._content_consumed = True
    # don't need to release the connection; that's been handled by urllib3
    # since we exhausted the data.
    return self._content  # type: ignore[return-value]

def json(self, **kwargs: Any) -> Any:
    r"""Decodes the JSON response body (if any) as a Python object.

    This may return a dictionary, list, etc. depending on what is in the response.

    :param \*\*kwargs: Optional arguments that ``json.loads`` takes.
    :raises requests.exceptions.JSONDecodeError: If the response body does not
        contain valid json.
    """

    if not self.encoding and self.content and len(self.content) > 3:
        # No encoding set. JSON RFC 4627 section 3 states we should expect
        # UTF-8, -16 or -32. Detect which one to use; If the detection or
        # decoding fails, fall back to `self.text` (using charset_normalizer to make
        # a best guess).
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                # Wrong UTF codec detected; usually because it's not UTF-8
                # but some other 8-bit codec.  This is an RFC violation,
                # and the server didn't bother to tell us what codec *was*
                # used.
                pass
            except JSONDecodeError as e:
                raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

    try:
        return complexjson.loads(self.text, **kwargs)
    except JSONDecodeError as e:
        # Catch JSON-related errors and raise as requests.JSONDecodeError
        # This aliases json.JSONDecodeError and simplejson.JSONDecodeError
        raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

@property
def links(self) -> dict[str, dict[str, str]]:
    """Returns the parsed header links of the response, if any."""

    header = self.headers.get("link")

    resolved_links: dict[str, dict[str, str]] = {}

    if header:
        links = parse_header_links(header)

        for link in links:
            key = link.get("rel") or link.get("url")
            if key is not None:
                resolved_links[key] = link

    return resolved_links

def raise_for_status(self) -> None:
    """Raises :class:`HTTPError`, if one occurred."""

    http_error_msg = ""
    if isinstance(self.reason, bytes):
        # We attempt to decode utf-8 first because some servers
        # choose to localize their reason strings. If the string
        # isn't utf-8, we fall back to iso-8859-1 for all other
        # encodings. (See PR #3538)
        try:
            reason = self.reason.decode("utf-8")
        except UnicodeDecodeError:
            reason = self.reason.decode("iso-8859-1")
    else:
        reason = self.reason

    if 400 <= self.status_code < 500:
        http_error_msg = (
            f"{self.status_code} Client Error: {reason} for url: {self.url}"
        )

    elif 500 <= self.status_code < 600:
        http_error_msg = (
            f"{self.status_code} Server Error: {reason} for url: {self.url}"
        )

    if http_error_msg:
        raise HTTPError(http_error_msg, response=self)

def close(self) -> None:
    """Releases the connection back to the pool. Once this method has been
    called the underlying ``raw`` object must not be accessed again.

    *Note: Should not normally need to be called explicitly.*
    """
    if not self._content_consumed:
        self.raw.close()

    release_conn = getattr(self.raw, "release_conn", None)
    if release_conn is not None:
        release_conn()

def merge_hooks(
    request_hooks: _t.HooksType,
    session_hooks: _t.HooksType,
    dict_class: type = OrderedDict,
) -> _t.HooksType:
    """Properly merges both requests and session hooks.

    This is necessary because when request_hooks == {'response': []}, the
    merge breaks Session hooks entirely.
    """
    if session_hooks is None or session_hooks.get("response") == []:
        return request_hooks

    if request_hooks is None or request_hooks.get("response") == []:
        return session_hooks

    return merge_setting(request_hooks, session_hooks, dict_class)

def get_adapter(self, url: str) -> BaseAdapter:
    """
    Returns the appropriate connection adapter for the given URL.

    :rtype: requests.adapters.BaseAdapter
    """
    for prefix, adapter in self.adapters.items():
        if url.lower().startswith(prefix.lower()):
            return adapter

    # Nothing matches :-/
    raise InvalidSchema(f"No connection adapters were found for {url!r}")

def close(self) -> None:
    """Closes all adapters and as such the session"""
    for v in self.adapters.values():
        v.close()

def __getstate__(self) -> dict[str, Any]:
    state = {attr: getattr(self, attr, None) for attr in self.__attrs__}
    return state

def __setstate__(self, state: dict[str, Any]) -> None:
    for attr, value in state.items():
        setattr(self, attr, value)

def _init():
    for code, titles in _codes.items():
        for title in titles:
            setattr(codes, title, code)
            if not title.startswith(("\\", "/")):
                setattr(codes, title.upper(), code)

    def doc(code: int) -> str:
        names = ", ".join(f"``{n}``" for n in _codes[code])
        return "* %d: %s" % (code, names)

    global __doc__
    __doc__ = (
        __doc__ + "\n" + "\n".join(doc(code) for code in sorted(_codes))
        if __doc__ is not None
        else None
    )

def doc(code: int) -> str:
    names = ", ".join(f"``{n}``" for n in _codes[code])
    return "* %d: %s" % (code, names)

def __init__(
    self,
    data: Mapping[str, _VT] | Iterable[tuple[str, _VT]] | None = None,
    **kwargs: _VT,
) -> None:
    self._store = OrderedDict()
    if data is None:
        data = {}
    self.update(data, **kwargs)

def lower_items(self) -> Iterator[tuple[str, _VT]]:
    """Like iteritems(), but with all lowercase keys."""
    return ((lowerkey, keyval[1]) for (lowerkey, keyval) in self._store.items())

def __eq__(self, other: object) -> bool:
    if isinstance(other, Mapping):
        other_dict: CaseInsensitiveDict[Any] = CaseInsensitiveDict(other)  # type: ignore[reportUnknownArgumentType]
    else:
        return NotImplemented
    # Compare insensitively
    return dict(self.lower_items()) == dict(other_dict.lower_items())

def __init__(self, name: Any = None) -> None:
    self.name = name
    super().__init__()

def __getattr__(self, key: str) -> _VT | None:
    # We need this for type checkers to infer typing
    # on attribute access with status_codes.py
    if key in self.__dict__:
        return self.__dict__[key]
    else:
        raise AttributeError(
            f"'{type(self).__name__}' object has no attribute '{key}'"
        )

def __getitem__(self, key: str) -> _VT | None:  # type: ignore[override]
    # We allow fall-through here, so values default to None

    return self.__dict__.get(key, None)

def proxy_bypass_registry(host: str) -> bool:
    try:
        import winreg
    except ImportError:
        return False

    try:
        internetSettings = winreg.OpenKey(
            winreg.HKEY_CURRENT_USER,
            r"Software\Microsoft\Windows\CurrentVersion\Internet Settings",
        )
        # ProxyEnable could be REG_SZ or REG_DWORD, normalizing it
        proxyEnable = int(winreg.QueryValueEx(internetSettings, "ProxyEnable")[0])
        # ProxyOverride is almost always a string
        proxyOverride = winreg.QueryValueEx(internetSettings, "ProxyOverride")[0]
    except (OSError, ValueError):
        return False
    if not proxyEnable or not proxyOverride:
        return False

    # make a check value list from the registry entry: replace the
    # '<local>' string by the localhost entry and the corresponding
    # canonical entry.
    proxyOverride = proxyOverride.split(";")
    # filter out empty strings to avoid re.match return true in the following code.
    proxyOverride = filter(None, proxyOverride)
    # now check if we match one of the registry values.
    for test in proxyOverride:
        if test == "<local>":
            if "." not in host:
                return True
        test = test.replace(".", r"\.")  # mask dots
        test = test.replace("*", r".*")  # change glob sequence
        test = test.replace("?", r".")  # change glob char
        if re.match(test, host, re.I):
            return True
    return False

def proxy_bypass(host: str) -> bool:  # noqa
    """Return True, if the host should be bypassed.

    Checks proxy settings gathered from the environment, if specified,
    or the registry.
    """
    if getproxies_environment():
        return proxy_bypass_environment(host)
    else:
        return proxy_bypass_registry(host)

def dict_to_sequence(
    d: _t.SupportsItems[Any, Any] | Iterable[tuple[Any, Any]],
) -> Iterable[tuple[Any, Any]]:
    """Returns an internal sequence dictionary update."""

    if isinstance(d, _SupportsItems):
        return d.items()

    return d

def super_len(o: Any) -> int:
    total_length = None
    current_position = 0

    if not is_urllib3_1 and isinstance(o, str):
        # urllib3 2.x+ treats all strings as utf-8 instead
        # of latin-1 (iso-8859-1) like http.client.
        o = o.encode("utf-8")

    if hasattr(o, "__len__"):
        total_length = len(o)

    elif hasattr(o, "len"):
        total_length = o.len

    elif hasattr(o, "fileno"):
        try:
            fileno = o.fileno()
        except (io.UnsupportedOperation, AttributeError):
            # AttributeError is a surprising exception, seeing as how we've just checked
            # that `hasattr(o, 'fileno')`.  It happens for objects obtained via
            # `Tarfile.extractfile()`, per issue 5229.
            pass
        else:
            total_length = os.fstat(fileno).st_size

            # Having used fstat to determine the file length, we need to
            # confirm that this file was opened up in binary mode.
            if "b" not in o.mode:
                warnings.warn(
                    (
                        "Requests has determined the content-length for this "
                        "request using the binary size of the file: however, the "
                        "file has been opened in text mode (i.e. without the 'b' "
                        "flag in the mode). This may lead to an incorrect "
                        "content-length. In Requests 3.0, support will be removed "
                        "for files in text mode."
                    ),
                    FileModeWarning,
                )

    if hasattr(o, "tell"):
        try:
            current_position = o.tell()
        except OSError:
            # This can happen in some weird situations, such as when the file
            # is actually a special file descriptor like stdin. In this
            # instance, we don't know what the length is, so set it to zero and
            # let requests chunk it instead.
            if total_length is not None:
                current_position = total_length
        else:
            if hasattr(o, "seek") and total_length is None:
                # StringIO and BytesIO have seek but no usable fileno
                try:
                    # seek to end of file
                    o.seek(0, 2)
                    total_length = o.tell()

                    # seek back to current position to support
                    # partially read file-like objects
                    o.seek(current_position or 0)
                except OSError:
                    total_length = 0

    if total_length is None:
        total_length = 0

    return max(0, total_length - current_position)

def get_netrc_auth(
    url: _t.UriType, raise_errors: bool = False
) -> tuple[str, str] | None:
    """Returns the Requests tuple auth for a given url from netrc."""

    if isinstance(url, bytes):
        url = url.decode("utf-8")

    netrc_file = os.environ.get("NETRC")
    if netrc_file is not None:
        netrc_locations = (netrc_file,)
    else:
        netrc_locations = (f"~/{f}" for f in NETRC_FILES)

    try:
        from netrc import NetrcParseError, netrc

        netrc_path = None

        for f in netrc_locations:
            loc = os.path.expanduser(f)
            if os.path.exists(loc):
                netrc_path = loc
                break

        # Abort early if there isn't one.
        if netrc_path is None:
            return

        ri = urlparse(url)
        host = ri.hostname

        if host is None:
            return

        try:
            _netrc = netrc(netrc_path).authenticators(host)
            if _netrc and any(_netrc):
                # Return with login / password
                login_i = 0 if _netrc[0] else 1
                return (_netrc[login_i] or "", _netrc[2] or "")
        except (NetrcParseError, OSError):
            # If there was a parsing error or a permissions issue reading the file,
            # we'll just skip netrc auth unless explicitly asked to raise errors.
            if raise_errors:
                raise

    # App Engine hackiness.
    except (ImportError, AttributeError):
        pass

def guess_filename(obj: Any) -> str | None:
    """Tries to guess the filename of the given object."""
    name = getattr(obj, "name", None)
    if name and isinstance(name, (str, bytes)) and name[0] != "<" and name[-1] != ">":
        return os.path.basename(name)  # type: ignore[return-value]  # urllib3 accepts bytes but types str only

@contextlib.contextmanager
def atomic_open(filename: str) -> Generator[BufferedWriter, None, None]:
    """Write a file to the disk in an atomic fashion"""
    tmp_descriptor, tmp_name = tempfile.mkstemp(dir=os.path.dirname(filename))
    try:
        with os.fdopen(tmp_descriptor, "wb") as tmp_handler:
            yield tmp_handler
        os.replace(tmp_name, filename)
    except BaseException:
        os.remove(tmp_name)
        raise

def to_key_val_list(
    value: _t.SupportsItems[_KT, _VT] | Iterable[tuple[_KT, _VT]] | None,
) -> list[tuple[_KT, _VT]] | None:
    """Take an object and test to see if it can be represented as a
    dictionary. If it can be, return a list of tuples, e.g.,

    ::

        >>> to_key_val_list([('key', 'val')])
        [('key', 'val')]
        >>> to_key_val_list({'key': 'val'})
        [('key', 'val')]
        >>> to_key_val_list('string')
        Traceback (most recent call last):
        ...
        ValueError: cannot encode objects that are not 2-tuples

    :rtype: list
    """
    if value is None:
        return None

    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError("cannot encode objects that are not 2-tuples")

    if isinstance(value, _SupportsItems):
        return list(value.items())

    return list(value)

def get_encoding_from_headers(headers: CaseInsensitiveDict[str]) -> str | None:
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    :rtype: str
    """

    content_type = headers.get("content-type")

    if not content_type:
        return None

    content_type, params = _parse_content_type_header(content_type)

    if "charset" in params:
        return params["charset"].strip("'\"")

    if "text" in content_type:
        return "ISO-8859-1"

    if "application/json" in content_type:
        # Assume UTF-8 based on RFC 4627: https://www.ietf.org/rfc/rfc4627.txt since the charset was unset
        return "utf-8"

def stream_decode_response_unicode(
    iterator: Iterable[bytes], r: Response
) -> Generator[str | bytes, None, None]:
    """Stream decodes an iterator."""

    if r.encoding is None:
        yield from iterator
        return

    decoder = codecs.getincrementaldecoder(r.encoding)(errors="replace")
    for chunk in iterator:
        rv = decoder.decode(chunk)
        if rv:
            yield rv
    rv = decoder.decode(b"", final=True)
    if rv:
        yield rv

def iter_slices(
    string: bytes | str, slice_length: int | None
) -> Generator[bytes | str, None, None]:
    """Iterate over slices of a string."""
    pos = 0
    if slice_length is None or slice_length <= 0:
        slice_length = len(string)
    while pos < len(string):
        yield string[pos : pos + slice_length]
        pos += slice_length

def get_unicode_from_response(r: Response) -> str | bytes | None:
    """Returns the requested content back in unicode.

    :param r: Response object to get unicode content from.

    Tried:

    1. charset from content-type
    2. fall back and replace all unicode characters

    :rtype: str
    """
    warnings.warn(
        (
            "In requests 3.0, get_unicode_from_response will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )
    if r.content is None:  # type: ignore[reportUnnecessaryComparison]
        return None

    tried_encodings: list[str] = []

    # Try charset from content-type
    encoding = get_encoding_from_headers(r.headers)

    if encoding:
        try:
            return str(r.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)

    # Fall back:
    try:
        return str(r.content, encoding or "utf-8", errors="replace")
    except TypeError:
        return r.content

def unquote_unreserved(uri: str) -> str:
    """Un-escape any percent-escape sequences in a URI that are unreserved
    characters. This leaves all reserved, illegal and non-ASCII bytes encoded.

    :rtype: str
    """
    parts = uri.split("%")
    for i in range(1, len(parts)):
        h = parts[i][0:2]
        if len(h) == 2 and h.isalnum():
            try:
                c = chr(int(h, 16))
            except ValueError:
                raise InvalidURL(f"Invalid percent-escape sequence: '{h}'")

            if c in UNRESERVED_SET:
                parts[i] = c + parts[i][2:]
            else:
                parts[i] = f"%{parts[i]}"
        else:
            parts[i] = f"%{parts[i]}"
    return "".join(parts)

def is_ipv4_address(string_ip: str) -> bool:
    """
    :rtype: bool
    """
    try:
        socket.inet_aton(string_ip)
    except OSError:
        return False
    return True

def is_valid_cidr(string_network: str) -> bool:
    """
    Very simple check of the cidr format in no_proxy variable.

    :rtype: bool
    """
    if string_network.count("/") == 1:
        try:
            mask = int(string_network.split("/")[1])
        except ValueError:
            return False

        if mask < 1 or mask > 32:
            return False

        try:
            socket.inet_aton(string_network.split("/")[0])
        except OSError:
            return False
    else:
        return False
    return True

@contextlib.contextmanager
def set_environ(env_name: str, value: str | None) -> Generator[None, None, None]:
    """Set the environment variable 'env_name' to 'value'

    Save previous value, yield, and then restore the previous value stored in
    the environment variable 'env_name'.

    If 'value' is None, do nothing"""
    value_changed = value is not None
    old_value: str | None = None
    if value_changed:
        old_value = os.environ.get(env_name)
        os.environ[env_name] = value
    try:
        yield
    finally:
        if value_changed:
            if old_value is None:
                del os.environ[env_name]
            else:
                os.environ[env_name] = old_value

def should_bypass_proxies(url: str, no_proxy: str | None) -> bool:
    """
    Returns whether we should bypass proxies or not.

    :rtype: bool
    """

    # Prioritize lowercase environment variables over uppercase
    # to keep a consistent behaviour with other http projects (curl, wget).
    def get_proxy(key: str) -> str | None:
        return os.environ.get(key) or os.environ.get(key.upper())

    # First check whether no_proxy is defined. If it is, check that the URL
    # we're getting isn't in the no_proxy list.
    no_proxy_arg = no_proxy
    if no_proxy is None:
        no_proxy = get_proxy("no_proxy")
    parsed = urlparse(url)
    hostname = parsed.hostname

    if hostname is None:
        # URLs don't always have hostnames, e.g. file:/// urls.
        return True

    if no_proxy:
        # We need to check whether we match here. We need to see if we match
        # the end of the hostname, both with and without the port.
        no_proxy_hosts = (host for host in no_proxy.replace(" ", "").split(",") if host)

        if is_ipv4_address(hostname):
            for proxy_ip in no_proxy_hosts:
                if is_valid_cidr(proxy_ip):
                    if address_in_network(hostname, proxy_ip):
                        return True
                elif hostname == proxy_ip:
                    # If no_proxy ip was defined in plain IP notation instead of cidr notation &
                    # matches the IP of the index
                    return True
        else:
            host_with_port = hostname
            if parsed.port:
                host_with_port += f":{parsed.port}"

            for host in no_proxy_hosts:
                host = host.lstrip(".")
                if hostname == host or host_with_port == host:
                    return True
                host = "." + host
                if hostname.endswith(host) or host_with_port.endswith(host):
                    return True

    with set_environ("no_proxy", no_proxy_arg):
        try:
            bypass = proxy_bypass(hostname)
        except (TypeError, socket.gaierror):
            bypass = False

    if bypass:
        return True

    return False

def get_environ_proxies(url: str, no_proxy: str | None = None) -> dict[str, str]:
    """
    Return a dict of environment proxies.

    :rtype: dict
    """
    if should_bypass_proxies(url, no_proxy=no_proxy):
        return {}
    else:
        return getproxies()

def select_proxy(url: str, proxies: dict[str, str] | None) -> str | None:
    """Select a proxy for the url, if applicable.

    :param url: The url being for the request
    :param proxies: A dictionary of schemes or schemes and hosts to proxy URLs
    """
    proxies = proxies or {}
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get(urlparts.scheme, proxies.get("all"))

    proxy_keys = [
        urlparts.scheme + "://" + urlparts.hostname,
        urlparts.scheme,
        "all://" + urlparts.hostname,
        "all",
    ]
    proxy = None
    for proxy_key in proxy_keys:
        if proxy_key in proxies:
            proxy = proxies[proxy_key]
            break

    return proxy

def default_headers() -> CaseInsensitiveDict[str]:
    """
    :rtype: requests.structures.CaseInsensitiveDict
    """
    return CaseInsensitiveDict(
        {
            "User-Agent": default_user_agent(),
            "Accept-Encoding": DEFAULT_ACCEPT_ENCODING,
            "Accept": "*/*",
            "Connection": "keep-alive",
        }
    )

def parse_header_links(value: str) -> list[dict[str, str]]:
    """Return a list of parsed link headers proxies.

    i.e. Link: <http:/.../front.jpeg>; rel=front; type="image/jpeg",<http://.../back.jpeg>; rel=back;type="image/jpeg"

    :rtype: list
    """

    links: list[dict[str, str]] = []

    replace_chars = " '\""

    value = value.strip(replace_chars)
    if not value:
        return links

    for val in re.split(", *<", value):
        try:
            url, params = val.split(";", 1)
        except ValueError:
            url, params = val, ""

        link: dict[str, str] = {"url": url.strip("<> '\"")}

        for param in params.split(";"):
            try:
                key, value = param.split("=")
            except ValueError:
                break

            link[key.strip(replace_chars)] = value.strip(replace_chars)

        links.append(link)

    return links

def guess_json_utf(data: bytes) -> str | None:
    """
    :rtype: str
    """
    # JSON always starts with two ASCII characters, so detection is as
    # easy as counting the nulls and from their location and count
    # determine the encoding. Also detect a BOM, if present.
    sample = data[:4]
    if sample in (codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE):
        return "utf-32"  # BOM included
    if sample[:3] == codecs.BOM_UTF8:
        return "utf-8-sig"  # BOM included, MS style (discouraged)
    if sample[:2] in (codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
        return "utf-16"  # BOM included
    nullcount = sample.count(_null)
    if nullcount == 0:
        return "utf-8"
    if nullcount == 2:
        if sample[::2] == _null2:  # 1st and 3rd are null
            return "utf-16-be"
        if sample[1::2] == _null2:  # 2nd and 4th are null
            return "utf-16-le"
        # Did not detect 2 valid UTF-16 ascii-range characters
    if nullcount == 3:
        if sample[:3] == _null3:
            return "utf-32-be"
        if sample[1:] == _null3:
            return "utf-32-le"
        # Did not detect a valid UTF-32 ascii-range character
    return None

def _validate_header_part(
    header: tuple[str | bytes, str | bytes],
    header_part: str | bytes,
    header_validator_index: int,
) -> None:
    if isinstance(header_part, str):
        validator = _HEADER_VALIDATORS_STR[header_validator_index]
    elif isinstance(header_part, bytes):
        # runtime guard for non-str/bytes input
        validator = _HEADER_VALIDATORS_BYTE[header_validator_index]
    else:
        raise InvalidHeader(
            f"Header part ({header_part!r}) from {header} "
            f"must be of type str or bytes, not {type(header_part)}"
        )

    if not validator.match(header_part):  # type: ignore[arg-type]
        header_kind = "name" if header_validator_index == 0 else "value"
        raise InvalidHeader(
            f"Invalid leading whitespace, reserved character(s), or return "
            f"character(s) in header {header_kind}: {header_part!r}"
        )

def rewind_body(prepared_request: PreparedRequest) -> None:
    """Move file pointer back to its recorded starting position
    so it can be read again on redirect.
    """
    body_seek = getattr(prepared_request.body, "seek", None)
    if body_seek is not None and isinstance(
        prepared_request._body_position,
        integer_types,
    ):
        try:
            body_seek(prepared_request._body_position)
        except OSError:
            raise UnrewindableBodyError(
                "An error occurred when rewinding request body for redirect."
            )
    else:
        raise UnrewindableBodyError("Unable to rewind request body for redirect.")

def _make_text_stream(
    stream: t.BinaryIO,
    encoding: t.Optional[str],
    errors: t.Optional[str],
    force_readable: bool = False,
    force_writable: bool = False,
) -> t.TextIO:
    if encoding is None:
        encoding = get_best_encoding(stream)
    if errors is None:
        errors = "replace"
    return _NonClosingTextIOWrapper(
        stream,
        encoding,
        errors,
        line_buffering=True,
        force_readable=force_readable,
        force_writable=force_writable,
    )

def is_ascii_encoding(encoding: str) -> bool:
    """Checks if a given encoding is ascii."""
    try:
        return codecs.lookup(encoding).name == "ascii"
    except LookupError:
        return False

def get_best_encoding(stream: t.IO[t.Any]) -> str:
    """Returns the default stream encoding if not found."""
    rv = getattr(stream, "encoding", None) or sys.getdefaultencoding()
    if is_ascii_encoding(rv):
        return "utf-8"
    return rv

def __del__(self) -> None:
    try:
        self.detach()
    except Exception:
        pass

def isatty(self) -> bool:
    # https://bitbucket.org/pypy/pypy/issue/1803
    return self._stream.isatty()

def read1(self, size: int) -> bytes:
    f = getattr(self._stream, "read1", None)

    if f is not None:
        return t.cast(bytes, f(size))

    return self._stream.read(size)

def readable(self) -> bool:
    if self._force_readable:
        return True
    x = getattr(self._stream, "readable", None)
    if x is not None:
        return t.cast(bool, x())
    try:
        self._stream.read(0)
    except Exception:
        return False
    return True

def writable(self) -> bool:
    if self._force_writable:
        return True
    x = getattr(self._stream, "writable", None)
    if x is not None:
        return t.cast(bool, x())
    try:
        self._stream.write("")  # type: ignore
    except Exception:
        try:
            self._stream.write(b"")
        except Exception:
            return False
    return True

def seekable(self) -> bool:
    x = getattr(self._stream, "seekable", None)
    if x is not None:
        return t.cast(bool, x())
    try:
        self._stream.seek(self._stream.tell())
    except Exception:
        return False
    return True

def _is_binary_reader(stream: t.IO[t.Any], default: bool = False) -> bool:
    try:
        return isinstance(stream.read(0), bytes)
    except Exception:
        return default

def _is_binary_writer(stream: t.IO[t.Any], default: bool = False) -> bool:
    try:
        stream.write(b"")
    except Exception:
        try:
            stream.write("")
            return False
        except Exception:
            pass
        return default
    return True

def _find_binary_reader(stream: t.IO[t.Any]) -> t.Optional[t.BinaryIO]:
    # We need to figure out if the given stream is already binary.
    # This can happen because the official docs recommend detaching
    # the streams to get binary streams.  Some code might do this, so
    # we need to deal with this case explicitly.
    if _is_binary_reader(stream, False):
        return t.cast(t.BinaryIO, stream)

    buf = getattr(stream, "buffer", None)

    # Same situation here; this time we assume that the buffer is
    # actually binary in case it's closed.
    if buf is not None and _is_binary_reader(buf, True):
        return t.cast(t.BinaryIO, buf)

    return None

def _find_binary_writer(stream: t.IO[t.Any]) -> t.Optional[t.BinaryIO]:
    # We need to figure out if the given stream is already binary.
    # This can happen because the official docs recommend detaching
    # the streams to get binary streams.  Some code might do this, so
    # we need to deal with this case explicitly.
    if _is_binary_writer(stream, False):
        return t.cast(t.BinaryIO, stream)

    buf = getattr(stream, "buffer", None)

    # Same situation here; this time we assume that the buffer is
    # actually binary in case it's closed.
    if buf is not None and _is_binary_writer(buf, True):
        return t.cast(t.BinaryIO, buf)

    return None

def _is_compatible_text_stream(
    stream: t.TextIO, encoding: t.Optional[str], errors: t.Optional[str]
) -> bool:
    """Check if a stream's encoding and errors attributes are
    compatible with the desired values.
    """
    return _is_compat_stream_attr(
        stream, "encoding", encoding
    ) and _is_compat_stream_attr(stream, "errors", errors)

def get_binary_stdin() -> t.BinaryIO:
