def _make_cached_stream_func(
    src_func: t.Callable[[], t.Optional[t.TextIO]],
    wrapper_func: t.Callable[[], t.TextIO],
) -> t.Callable[[], t.Optional[t.TextIO]]:
    cache: t.MutableMapping[t.TextIO, t.TextIO] = WeakKeyDictionary()

    def func() -> t.Optional[t.TextIO]:
        stream = src_func()

        if stream is None:
            return None

        try:
            rv = cache.get(stream)
        except Exception:
            rv = None
        if rv is not None:
            return rv
        rv = wrapper_func()
        try:
            cache[stream] = rv
        except Exception:
            pass
        return rv

    return func

def func() -> t.Optional[t.TextIO]:
    stream = src_func()

    if stream is None:
        return None

    try:
        rv = cache.get(stream)
    except Exception:
        rv = None
    if rv is not None:
        return rv
    rv = wrapper_func()
    try:
        cache[stream] = rv
    except Exception:
        pass
    return rv

def __iter__(self) -> t.Iterator[V]:
    if not self.entered:
        raise RuntimeError("You need to use progress bars in a with block.")
    self.render_progress()
    return self.generator()

def render_finish(self) -> None:
    if self.is_hidden:
        return
    self.file.write(AFTER_BAR)
    self.file.flush()

@property
def pct(self) -> float:
    if self.finished:
        return 1.0
    return min(self.pos / (float(self.length or 1) or 1), 1.0)

@property
def time_per_iteration(self) -> float:
    if not self.avg:
        return 0.0
    return sum(self.avg) / float(len(self.avg))

@property
def eta(self) -> float:
    if self.length is not None and not self.finished:
        return self.time_per_iteration * (self.length - self.pos)
    return 0.0

def format_pos(self) -> str:
    pos = str(self.pos)
    if self.length is not None:
        pos += f"/{self.length}"
    return pos

def format_bar(self) -> str:
    if self.length is not None:
        bar_length = int(self.pct * self.width)
        bar = self.fill_char * bar_length
        bar += self.empty_char * (self.width - bar_length)
    elif self.finished:
        bar = self.fill_char * self.width
    else:
        chars = list(self.empty_char * (self.width or 1))
        if self.time_per_iteration != 0:
            chars[
                int(
                    (math.cos(self.pos * self.time_per_iteration) / 2.0 + 0.5)
                    * self.width
                )
            ] = self.fill_char
        bar = "".join(chars)
    return bar

def format_progress_line(self) -> str:
    show_percent = self.show_percent

    info_bits = []
    if self.length is not None and show_percent is None:
        show_percent = not self.show_pos

    if self.show_pos:
        info_bits.append(self.format_pos())
    if show_percent:
        info_bits.append(self.format_pct())
    if self.show_eta and self.eta_known and not self.finished:
        info_bits.append(self.format_eta())
    if self.item_show_func is not None:
        item_info = self.item_show_func(self.current_item)
        if item_info is not None:
            info_bits.append(item_info)

    return (
        self.bar_template
        % {
            "label": self.label,
            "bar": self.format_bar(),
            "info": self.info_sep.join(info_bits),
        }
    ).rstrip()

def make_step(self, n_steps: int) -> None:
    self.pos += n_steps
    if self.length is not None and self.pos >= self.length:
        self.finished = True

    if (time.time() - self.last_eta) < 1.0:
        return

    self.last_eta = time.time()

    # self.avg is a rolling list of length <= 7 of steps where steps are
    # defined as time elapsed divided by the total progress through
    # self.length.
    if self.pos:
        step = (time.time() - self.start) / self.pos
    else:
        step = time.time() - self.start

    self.avg = self.avg[-6:] + [step]

    self.eta_known = self.length is not None

def pager(generator: t.Iterable[str], color: t.Optional[bool] = None) -> None:
    """Decide what method to use for paging through text."""
    stdout = _default_text_stdout()

    # There are no standard streams attached to write to. For example,
    # pythonw on Windows.
    if stdout is None:
        stdout = StringIO()

    if not isatty(sys.stdin) or not isatty(stdout):
        return _nullpager(stdout, generator, color)
    pager_cmd = (os.environ.get("PAGER", None) or "").strip()
    if pager_cmd:
        if WIN:
            if _tempfilepager(generator, pager_cmd, color):
                return
        elif _pipepager(generator, pager_cmd, color):
            return
    if os.environ.get("TERM") in ("dumb", "emacs"):
        return _nullpager(stdout, generator, color)
    if (WIN or sys.platform.startswith("os2")) and _tempfilepager(
        generator, "more", color
    ):
        return
    if _pipepager(generator, "less", color):
        return

    import tempfile

    fd, filename = tempfile.mkstemp()
    os.close(fd)
    try:
        if _pipepager(generator, "more", color):
            return
        return _nullpager(stdout, generator, color)
    finally:
        os.unlink(filename)

def _nullpager(
    stream: t.TextIO, generator: t.Iterable[str], color: t.Optional[bool]
) -> None:
    """Simply print unformatted text.  This is the ultimate fallback."""
    for text in generator:
        if not color:
            text = strip_ansi(text)
        stream.write(text)

def get_editor(self) -> str:
    if self.editor is not None:
        return self.editor
    for key in "VISUAL", "EDITOR":
        rv = os.environ.get(key)
        if rv:
            return rv
    if WIN:
        return "notepad"
    for editor in "sensible-editor", "vim", "nano":
        if which(editor) is not None:
            return editor
    return "vi"

def edit_file(self, filename: str) -> None:
    import subprocess

    editor = self.get_editor()
    environ: t.Optional[t.Dict[str, str]] = None

    if self.env:
        environ = os.environ.copy()
        environ.update(self.env)

    try:
        c = subprocess.Popen(f'{editor} "{filename}"', env=environ, shell=True)
        exit_code = c.wait()
        if exit_code != 0:
            raise ClickException(
                _("{editor}: Editing failed").format(editor=editor)
            )
    except OSError as e:
        raise ClickException(
            _("{editor}: Editing failed: {e}").format(editor=editor, e=e)
        ) from e

def open_url(url: str, wait: bool = False, locate: bool = False) -> int:
    import subprocess

    def _unquote_file(url: str) -> str:
        from urllib.parse import unquote

        if url.startswith("file://"):
            url = unquote(url[7:])

        return url

    if sys.platform == "darwin":
        args = ["open"]
        if wait:
            args.append("-W")
        if locate:
            args.append("-R")
        args.append(_unquote_file(url))
        null = open("/dev/null", "w")
        try:
            return subprocess.Popen(args, stderr=null).wait()
        finally:
            null.close()
    elif WIN:
        if locate:
            url = _unquote_file(url)
            args = ["explorer", f"/select,{url}"]
        else:
            args = ["start"]
            if wait:
                args.append("/WAIT")
            args.append("")
            args.append(url)
        try:
            return subprocess.call(args)
        except OSError:
            # Command not found
            return 127
    elif CYGWIN:
        if locate:
            url = _unquote_file(url)
            args = ["cygstart", os.path.dirname(url)]
        else:
            args = ["cygstart"]
            if wait:
                args.append("-w")
            args.append(url)
        try:
            return subprocess.call(args)
        except OSError:
            # Command not found
            return 127

    try:
        if locate:
            url = os.path.dirname(_unquote_file(url)) or "."
        else:
            url = _unquote_file(url)
        c = subprocess.Popen(["xdg-open", url])
        if wait:
            return c.wait()
        return 0
    except OSError:
        if url.startswith(("http://", "https://")) and not locate and not wait:
            import webbrowser

            webbrowser.open(url)
            return 0
        return 1

def _unquote_file(url: str) -> str:
    from urllib.parse import unquote

    if url.startswith("file://"):
        url = unquote(url[7:])

    return url

@contextlib.contextmanager
def raw_terminal() -> t.Iterator[int]:
    yield -1

@contextlib.contextmanager
def raw_terminal() -> t.Iterator[int]:
    f: t.Optional[t.TextIO]
    fd: int

    if not isatty(sys.stdin):
        f = open("/dev/tty")
        fd = f.fileno()
    else:
        fd = sys.stdin.fileno()
        f = None

    try:
        old_settings = termios.tcgetattr(fd)

        try:
            tty.setraw(fd)
            yield fd
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
            sys.stdout.flush()

            if f is not None:
                f.close()
    except termios.error:
        pass

def indent_only(self, text: str) -> str:
    rv = []

    for idx, line in enumerate(text.splitlines()):
        indent = self.initial_indent

        if idx > 0:
            indent = self.subsequent_indent

        rv.append(f"{indent}{line}")

    return "\n".join(rv)

def get_buffer(obj, writable=False):
    buf = Py_buffer()
    flags = PyBUF_WRITABLE if writable else PyBUF_SIMPLE
    PyObject_GetBuffer(py_object(obj), byref(buf), flags)

    try:
        buffer_type = c_char * buf.len
        return buffer_type.from_address(buf.buf)
    finally:
        PyBuffer_Release(byref(buf))

def isatty(self):
    super().isatty()
    return True

def readinto(self, b):
    bytes_to_be_read = len(b)
    if not bytes_to_be_read:
        return 0
    elif bytes_to_be_read % 2:
        raise ValueError(
            "cannot read odd number of bytes from UTF-16-LE encoded console"
        )

    buffer = get_buffer(b, writable=True)
    code_units_to_be_read = bytes_to_be_read // 2
    code_units_read = c_ulong()

    rv = ReadConsoleW(
        HANDLE(self.handle),
        buffer,
        code_units_to_be_read,
        byref(code_units_read),
        None,
    )
    if GetLastError() == ERROR_OPERATION_ABORTED:
        # wait for KeyboardInterrupt
        time.sleep(0.1)
    if not rv:
        raise OSError(f"Windows error: {GetLastError()}")

    if buffer[0] == EOF:
        return 0
    return 2 * code_units_read.value

@staticmethod
def _get_error_message(errno):
    if errno == ERROR_SUCCESS:
        return "ERROR_SUCCESS"
    elif errno == ERROR_NOT_ENOUGH_MEMORY:
        return "ERROR_NOT_ENOUGH_MEMORY"
    return f"Windows error {errno}"

def __init__(self, text_stream: t.TextIO, byte_stream: t.BinaryIO) -> None:
    self._text_stream = text_stream
    self.buffer = byte_stream

@property
def name(self) -> str:
    return self.buffer.name

def write(self, x: t.AnyStr) -> int:
    if isinstance(x, str):
        return self._text_stream.write(x)
    try:
        self.flush()
    except Exception:
        pass
    return self.buffer.write(x)

def writelines(self, lines: t.Iterable[t.AnyStr]) -> None:
    for line in lines:
        self.write(line)

def _get_text_stdin(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedReader(_WindowsConsoleReader(STDIN_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))

def _get_text_stdout(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedWriter(_WindowsConsoleWriter(STDOUT_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))

def _get_text_stderr(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedWriter(_WindowsConsoleWriter(STDERR_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))

def _is_console(f: t.TextIO) -> bool:
    if not hasattr(f, "fileno"):
        return False

    try:
        fileno = f.fileno()
    except (OSError, io.UnsupportedOperation):
        return False

    handle = msvcrt.get_osfhandle(fileno)
    return bool(GetConsoleMode(handle, byref(DWORD())))

def _get_windows_console_stream(
    f: t.TextIO, encoding: t.Optional[str], errors: t.Optional[str]
) -> t.Optional[t.TextIO]:
    if (
        get_buffer is not None
        and encoding in {"utf-16-le", None}
        and errors in {"strict", None}
        and _is_console(f)
    ):
        func = _stream_factories.get(f.fileno())
        if func is not None:
            b = getattr(f, "buffer", None)

            if b is None:
                return None

            return func(b)

def _complete_visible_commands(
    ctx: "Context", incomplete: str
) -> t.Iterator[t.Tuple[str, "Command"]]:
    """List all the subcommands of a group that start with the
    incomplete value and aren't hidden.

    :param ctx: Invocation context for the group.
    :param incomplete: Value being completed. May be empty.
    """
    multi = t.cast(MultiCommand, ctx.command)

    for name in multi.list_commands(ctx):
        if name.startswith(incomplete):
            command = multi.get_command(ctx, name)

            if command is not None and not command.hidden:
                yield name, command

def _check_multicommand(
    base_command: "MultiCommand", cmd_name: str, cmd: "Command", register: bool = False
) -> None:
    if not base_command.chain or not isinstance(cmd, MultiCommand):
        return
    if register:
        hint = (
            "It is not possible to add multi commands as children to"
            " another multi command that is in chain mode."
        )
    else:
        hint = (
            "Found a multi command as subcommand to a multi command"
            " that is in chain mode. This is not supported."
        )
    raise RuntimeError(
        f"{hint}. Command {base_command.name!r} is set to chain and"
        f" {cmd_name!r} was added as a subcommand but it in itself is a"
        f" multi command. ({cmd_name!r} is a {type(cmd).__name__}"
        f" within a chained {type(base_command).__name__} named"
        f" {base_command.name!r})."
    )

@contextmanager
def augment_usage_errors(
    ctx: "Context", param: t.Optional["Parameter"] = None
) -> t.Iterator[None]:
    """Context manager that attaches extra information to exceptions."""
    try:
        yield
    except BadParameter as e:
        if e.ctx is None:
            e.ctx = ctx
        if param is not None and e.param is None:
            e.param = param
        raise
    except UsageError as e:
        if e.ctx is None:
            e.ctx = ctx
        raise

def iter_params_for_processing(
    invocation_order: t.Sequence["Parameter"],
    declaration_order: t.Sequence["Parameter"],
) -> t.List["Parameter"]:
    """Returns all declared parameters in the order they should be processed.

    The declared parameters are re-shuffled depending on the order in which
    they were invoked, as well as the eagerness of each parameters.

    The invocation order takes precedence over the declaration order. I.e. the
    order in which the user provided them to the CLI is respected.

    This behavior and its effect on callback evaluation is detailed at:
    https://click.palletsprojects.com/en/stable/advanced/#callback-evaluation-order
    """

    def sort_key(item: "Parameter") -> t.Tuple[bool, float]:
        try:
            idx: float = invocation_order.index(item)
        except ValueError:
            idx = float("inf")

        return not item.is_eager, idx

    return sorted(declaration_order, key=sort_key)

def sort_key(item: "Parameter") -> t.Tuple[bool, float]:
    try:
        idx: float = invocation_order.index(item)
    except ValueError:
        idx = float("inf")

    return not item.is_eager, idx

def __exit__(
    self,
    exc_type: t.Optional[t.Type[BaseException]],
    exc_value: t.Optional[BaseException],
    tb: t.Optional[TracebackType],
) -> None:
    self._depth -= 1
    if self._depth == 0:
        self.close()
    pop_context()

@property
def command_path(self) -> str:
    """The computed command path.  This is used for the ``usage``
    information on the help page.  It's automatically created by
    combining the info names of the chain of contexts to the root.
    """
    rv = ""
    if self.info_name is not None:
        rv = self.info_name
    if self.parent is not None:
        parent_command_path = [self.parent.command_path]

        if isinstance(self.parent.command, Command):
            for param in self.parent.command.get_params(self):
                parent_command_path.extend(param.get_usage_pieces(self))

        rv = f"{' '.join(parent_command_path)} {rv}"
    return rv.lstrip()

def find_root(self) -> "Context":
    """Finds the outermost context."""
    node = self
    while node.parent is not None:
        node = node.parent
    return node

def find_object(self, object_type: t.Type[V]) -> t.Optional[V]:
    """Finds the closest object of a given type."""
    node: t.Optional[Context] = self

    while node is not None:
        if isinstance(node.obj, object_type):
            return node.obj

        node = node.parent

    return None

def abort(self) -> "te.NoReturn":
    """Aborts the script."""
    raise Abort()

def exit(self, code: int = 0) -> "te.NoReturn":
    """Exits the application with a given exit code."""
    raise Exit(code)

def get_usage(self) -> str:
    """Helper method to get formatted usage string for the current
    context and command.
    """
    return self.command.get_usage(self)

def get_help(self) -> str:
    """Helper method to get formatted help page for the current
    context and command.
    """
    return self.command.get_help(self)

def _make_sub_context(self, command: "Command") -> "Context":
    """Create a new context of the same type as this context, but
    for a new command.

    :meta private:
    """
    return type(self)(command, info_name=command.name, parent=self)

def forward(__self, __cmd: "Command", *args: t.Any, **kwargs: t.Any) -> t.Any:
    """Similar to :meth:`invoke` but fills in default keyword
    arguments from the current context if the other command expects
    it.  This cannot invoke callbacks directly, only other commands.

    .. versionchanged:: 8.0
        All ``kwargs`` are tracked in :attr:`params` so they will be
        passed if ``forward`` is called at multiple levels.
    """
    # Can only forward to other commands, not direct callbacks.
    if not isinstance(__cmd, Command):
        raise TypeError("Callback is not a command.")

    for param in __self.params:
        if param not in kwargs:
            kwargs[param] = __self.params[param]

    return __self.invoke(__cmd, *args, **kwargs)

def __call__(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
    """Alias for :meth:`main`."""
    return self.main(*args, **kwargs)

def get_params(self, ctx: Context) -> t.List["Parameter"]:
    rv = self.params
    help_option = self.get_help_option(ctx)

    if help_option is not None:
        rv = [*rv, help_option]

    return rv

def get_help_option_names(self, ctx: Context) -> t.List[str]:
    """Returns the names for the help option."""
    all_names = set(ctx.help_option_names)
    for param in self.params:
        all_names.difference_update(param.opts)
        all_names.difference_update(param.secondary_opts)
    return list(all_names)

def make_parser(self, ctx: Context) -> OptionParser:
    """Creates the underlying option parser for this command."""
    parser = OptionParser(ctx)
    for param in self.get_params(ctx):
        param.add_to_parser(parser, ctx)
    return parser

def get_short_help_str(self, limit: int = 45) -> str:
    """Gets short help for the command or makes it by shortening the
    long help string.
    """
    if self.short_help:
        text = inspect.cleandoc(self.short_help)
    elif self.help:
        text = make_default_short_help(self.help, limit)
    else:
        text = ""

    if self.deprecated:
        text = _("(Deprecated) {text}").format(text=text)

    return text.strip()

def format_help_text(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes the help text to the formatter if it exists."""
    if self.help is not None:
        # truncate the help text to the first form feed
        text = inspect.cleandoc(self.help).partition("\f")[0]
    else:
        text = ""

    if self.deprecated:
        text = _("(Deprecated) {text}").format(text=text)

    if text:
        formatter.write_paragraph()

        with formatter.indentation():
            formatter.write_text(text)

def format_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes all the options into the formatter if they exist."""
    opts = []
    for param in self.get_params(ctx):
        rv = param.get_help_record(ctx)
        if rv is not None:
            opts.append(rv)

    if opts:
        with formatter.section(_("Options")):
            formatter.write_dl(opts)

def parse_args(self, ctx: Context, args: t.List[str]) -> t.List[str]:
    if not args and self.no_args_is_help and not ctx.resilient_parsing:
        echo(ctx.get_help(), color=ctx.color)
        ctx.exit()

    parser = self.make_parser(ctx)
    opts, args, param_order = parser.parse_args(args=args)

    for param in iter_params_for_processing(param_order, self.get_params(ctx)):
        value, args = param.handle_parse_result(ctx, opts, args)

    if args and not ctx.allow_extra_args and not ctx.resilient_parsing:
        ctx.fail(
            ngettext(
                "Got unexpected extra argument ({args})",
                "Got unexpected extra arguments ({args})",
                len(args),
            ).format(args=" ".join(map(str, args)))
        )

    ctx.args = args
    ctx._opt_prefixes.update(parser._opt_prefixes)
    return args

def invoke(self, ctx: Context) -> t.Any:
    """Given a context, this invokes the attached callback (if it exists)
    in the right way.
    """
    if self.deprecated:
        message = _(
            "DeprecationWarning: The command {name!r} is deprecated."
        ).format(name=self.name)
        echo(style(message, fg="red"), err=True)

    if self.callback is not None:
        return ctx.invoke(self.callback, **ctx.params)

def __init__(
    self,
    name: t.Optional[str] = None,
    invoke_without_command: bool = False,
    no_args_is_help: t.Optional[bool] = None,
    subcommand_metavar: t.Optional[str] = None,
    chain: bool = False,
    result_callback: t.Optional[t.Callable[..., t.Any]] = None,
    **attrs: t.Any,
) -> None:
    super().__init__(name, **attrs)

    if no_args_is_help is None:
        no_args_is_help = not invoke_without_command

    self.no_args_is_help = no_args_is_help
    self.invoke_without_command = invoke_without_command

    if subcommand_metavar is None:
        if chain:
            subcommand_metavar = "COMMAND1 [ARGS]... [COMMAND2 [ARGS]...]..."
        else:
            subcommand_metavar = "COMMAND [ARGS]..."

    self.subcommand_metavar = subcommand_metavar
    self.chain = chain
    # The result callback that is stored. This can be set or
    # overridden with the :func:`result_callback` decorator.
    self._result_callback = result_callback

    if self.chain:
        for param in self.params:
            if isinstance(param, Argument) and not param.required:
                raise RuntimeError(
                    "Multi commands in chain mode cannot have"
                    " optional arguments."
                )

def to_info_dict(self, ctx: Context) -> t.Dict[str, t.Any]:
    info_dict = super().to_info_dict(ctx)
    commands = {}

    for name in self.list_commands(ctx):
        command = self.get_command(ctx, name)

        if command is None:
            continue

        sub_ctx = ctx._make_sub_context(command)

        with sub_ctx.scope(cleanup=False):
            commands[name] = command.to_info_dict(sub_ctx)

    info_dict.update(commands=commands, chain=self.chain)
    return info_dict

def format_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    super().format_options(ctx, formatter)
    self.format_commands(ctx, formatter)

def decorator(f: F) -> F:
    old_callback = self._result_callback

    if old_callback is None or replace:
        self._result_callback = f
        return f

    def function(__value, *args, **kwargs):  # type: ignore
        inner = old_callback(__value, *args, **kwargs)
        return f(inner, *args, **kwargs)

    self._result_callback = rv = update_wrapper(t.cast(F, function), f)
    return rv  # type: ignore[return-value]

def function(__value, *args, **kwargs):  # type: ignore
    inner = old_callback(__value, *args, **kwargs)
    return f(inner, *args, **kwargs)

def format_commands(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Extra format methods for multi methods that adds all the commands
    after the options.
    """
    commands = []
    for subcommand in self.list_commands(ctx):
        cmd = self.get_command(ctx, subcommand)
        # What is this, the tool lied about a command.  Ignore it
        if cmd is None:
            continue
        if cmd.hidden:
            continue

        commands.append((subcommand, cmd))

    # allow for 3 times the default spacing
    if len(commands):
        limit = formatter.width - 6 - max(len(cmd[0]) for cmd in commands)

        rows = []
        for subcommand, cmd in commands:
            help = cmd.get_short_help_str(limit)
            rows.append((subcommand, help))

        if rows:
            with formatter.section(_("Commands")):
                formatter.write_dl(rows)

def parse_args(self, ctx: Context, args: t.List[str]) -> t.List[str]:
    if not args and self.no_args_is_help and not ctx.resilient_parsing:
        echo(ctx.get_help(), color=ctx.color)
        ctx.exit()

    rest = super().parse_args(ctx, args)

    if self.chain:
        ctx.protected_args = rest
        ctx.args = []
    elif rest:
        ctx.protected_args, ctx.args = rest[:1], rest[1:]

    return ctx.args

def _process_result(value: t.Any) -> t.Any:
    if self._result_callback is not None:
        value = ctx.invoke(self._result_callback, value, **ctx.params)
    return value

def __init__(
    self,
    name: t.Optional[str] = None,
    commands: t.Optional[
        t.Union[t.MutableMapping[str, Command], t.Sequence[Command]]
    ] = None,
    **attrs: t.Any,
) -> None:
    super().__init__(name, **attrs)

    if commands is None:
        commands = {}
    elif isinstance(commands, abc.Sequence):
        commands = {c.name: c for c in commands if c.name is not None}

    #: The registered subcommands by their exported names.
    self.commands: t.MutableMapping[str, Command] = commands

def add_source(self, multi_cmd: MultiCommand) -> None:
    """Adds a new multi command to the chain dispatcher."""
    self.sources.append(multi_cmd)

def get_command(self, ctx: Context, cmd_name: str) -> t.Optional[Command]:
    for source in self.sources:
        rv = source.get_command(ctx, cmd_name)

        if rv is not None:
            if self.chain:
                _check_multicommand(self, cmd_name, rv)

            return rv

    return None

def list_commands(self, ctx: Context) -> t.List[str]:
    rv: t.Set[str] = set()

    for source in self.sources:
        rv.update(source.list_commands(ctx))

    return sorted(rv)

def _check_iter(value: t.Any) -> t.Iterator[t.Any]:
    """Check if the value is iterable but not a string. Raises a type
    error, or return an iterator over the value.
    """
    if isinstance(value, str):
        raise TypeError

    return iter(value)

def __init__(
    self,
    param_decls: t.Optional[t.Sequence[str]] = None,
    type: t.Optional[t.Union[types.ParamType, t.Any]] = None,
    required: bool = False,
    default: t.Optional[t.Union[t.Any, t.Callable[[], t.Any]]] = None,
    callback: t.Optional[t.Callable[[Context, "Parameter", t.Any], t.Any]] = None,
    nargs: t.Optional[int] = None,
    multiple: bool = False,
    metavar: t.Optional[str] = None,
    expose_value: bool = True,
    is_eager: bool = False,
    envvar: t.Optional[t.Union[str, t.Sequence[str]]] = None,
    shell_complete: t.Optional[
        t.Callable[
            [Context, "Parameter", str],
            t.Union[t.List["CompletionItem"], t.List[str]],
        ]
    ] = None,
) -> None:
    self.name: t.Optional[str]
    self.opts: t.List[str]
    self.secondary_opts: t.List[str]
    self.name, self.opts, self.secondary_opts = self._parse_decls(
        param_decls or (), expose_value
    )
    self.type: types.ParamType = types.convert_type(type, default)

    # Default nargs to what the type tells us if we have that
    # information available.
    if nargs is None:
        if self.type.is_composite:
            nargs = self.type.arity
        else:
            nargs = 1

    self.required = required
    self.callback = callback
    self.nargs = nargs
    self.multiple = multiple
    self.expose_value = expose_value
    self.default = default
    self.is_eager = is_eager
    self.metavar = metavar
    self.envvar = envvar
    self._custom_shell_complete = shell_complete

    if __debug__:
        if self.type.is_composite and nargs != self.type.arity:
            raise ValueError(
                f"'nargs' must be {self.type.arity} (or None) for"
                f" type {self.type!r}, but it was {nargs}."
            )

        # Skip no default or callable default.
        check_default = default if not callable(default) else None

        if check_default is not None:
            if multiple:
                try:
                    # Only check the first value against nargs.
                    check_default = next(_check_iter(check_default), None)
                except TypeError:
                    raise ValueError(
                        "'default' must be a list when 'multiple' is true."
                    ) from None

            # Can be None for multiple with empty default.
            if nargs != 1 and check_default is not None:
                try:
                    _check_iter(check_default)
                except TypeError:
                    if multiple:
                        message = (
                            "'default' must be a list of lists when 'multiple' is"
                            " true and 'nargs' != 1."
                        )
                    else:
                        message = "'default' must be a list when 'nargs' != 1."

                    raise ValueError(message) from None

                if nargs > 1 and len(check_default) != nargs:
                    subject = "item length" if multiple else "length"
                    raise ValueError(
                        f"'default' {subject} must match nargs={nargs}."
                    )

@property
def human_readable_name(self) -> str:
    """Returns the human readable name of this parameter.  This is the
    same as the name for options, but the metavar for arguments.
    """
    return self.name  # type: ignore

def make_metavar(self) -> str:
    if self.metavar is not None:
        return self.metavar

    metavar = self.type.get_metavar(self)

    if metavar is None:
        metavar = self.type.name.upper()

    if self.nargs != 1:
        metavar += "..."

    return metavar

def consume_value(
    self, ctx: Context, opts: t.Mapping[str, t.Any]
) -> t.Tuple[t.Any, ParameterSource]:
    value = opts.get(self.name)  # type: ignore
    source = ParameterSource.COMMANDLINE

    if value is None:
        value = self.value_from_envvar(ctx)
        source = ParameterSource.ENVIRONMENT

    if value is None:
        value = ctx.lookup_default(self.name)  # type: ignore
        source = ParameterSource.DEFAULT_MAP

    if value is None:
        value = self.get_default(ctx)
        source = ParameterSource.DEFAULT

    return value, source

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    """Convert and validate a value against the option's
    :attr:`type`, :attr:`multiple`, and :attr:`nargs`.
    """
    if value is None:
        return () if self.multiple or self.nargs == -1 else None

    def check_iter(value: t.Any) -> t.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            # This should only happen when passing in args manually,
            # the parser should construct an iterable when parsing
            # the command line.
            raise BadParameter(
                _("Value must be an iterable."), ctx=ctx, param=self
            ) from None

    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)

    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:  # t.Tuple[t.Any, ...]
            return tuple(self.type(x, self, ctx) for x in check_iter(value))

    else:  # nargs > 1

        def convert(value: t.Any) -> t.Any:  # t.Tuple[t.Any, ...]
            value = tuple(check_iter(value))

            if len(value) != self.nargs:
                raise BadParameter(
                    ngettext(
                        "Takes {nargs} values but 1 was given.",
                        "Takes {nargs} values but {len} were given.",
                        len(value),
                    ).format(nargs=self.nargs, len=len(value)),
                    ctx=ctx,
                    param=self,
                )

            return tuple(self.type(x, self, ctx) for x in value)

    if self.multiple:
        return tuple(convert(x) for x in check_iter(value))

    return convert(value)

def check_iter(value: t.Any) -> t.Iterator[t.Any]:
    try:
        return _check_iter(value)
    except TypeError:
        # This should only happen when passing in args manually,
        # the parser should construct an iterable when parsing
        # the command line.
        raise BadParameter(
            _("Value must be an iterable."), ctx=ctx, param=self
        ) from None

def convert(value: t.Any) -> t.Any:  # t.Tuple[t.Any, ...]
    value = tuple(check_iter(value))

    if len(value) != self.nargs:
        raise BadParameter(
            ngettext(
                "Takes {nargs} values but 1 was given.",
                "Takes {nargs} values but {len} were given.",
                len(value),
            ).format(nargs=self.nargs, len=len(value)),
            ctx=ctx,
            param=self,
        )

    return tuple(self.type(x, self, ctx) for x in value)

def value_is_missing(self, value: t.Any) -> bool:
    if value is None:
        return True

    if (self.nargs != 1 or self.multiple) and value == ():
        return True

    return False

def process_value(self, ctx: Context, value: t.Any) -> t.Any:
    value = self.type_cast_value(ctx, value)

    if self.required and self.value_is_missing(value):
        raise MissingParameter(ctx=ctx, param=self)

    if self.callback is not None:
        value = self.callback(ctx, self, value)

    return value

def resolve_envvar_value(self, ctx: Context) -> t.Optional[str]:
    if self.envvar is None:
        return None

    if isinstance(self.envvar, str):
        rv = os.environ.get(self.envvar)

        if rv:
            return rv
    else:
        for envvar in self.envvar:
            rv = os.environ.get(envvar)

            if rv:
                return rv

    return None

def value_from_envvar(self, ctx: Context) -> t.Optional[t.Any]:
    rv: t.Optional[t.Any] = self.resolve_envvar_value(ctx)

    if rv is not None and self.nargs != 1:
        rv = self.type.split_envvar_value(rv)

    return rv

def handle_parse_result(
    self, ctx: Context, opts: t.Mapping[str, t.Any], args: t.List[str]
) -> t.Tuple[t.Any, t.List[str]]:
    with augment_usage_errors(ctx, param=self):
        value, source = self.consume_value(ctx, opts)
        ctx.set_parameter_source(self.name, source)  # type: ignore

        try:
            value = self.process_value(ctx, value)
        except Exception:
            if not ctx.resilient_parsing:
                raise

            value = None

    if self.expose_value:
        ctx.params[self.name] = value  # type: ignore

    return value, args

def get_error_hint(self, ctx: Context) -> str:
    """Get a stringified version of the param for use in error messages to
    indicate which param caused the error.
    """
    hint_list = self.opts or [self.human_readable_name]
    return " / ".join(f"'{x}'" for x in hint_list)

def shell_complete(self, ctx: Context, incomplete: str) -> t.List["CompletionItem"]:
    """Return a list of completions for the incomplete value. If a
    ``shell_complete`` function was given during init, it is used.
    Otherwise, the :attr:`type`
    :meth:`~click.types.ParamType.shell_complete` function is used.

    :param ctx: Invocation context for this command.
    :param incomplete: Value being completed. May be empty.

    .. versionadded:: 8.0
    """
    if self._custom_shell_complete is not None:
        results = self._custom_shell_complete(ctx, self, incomplete)

        if results and isinstance(results[0], str):
            from click.shell_completion import CompletionItem

            results = [CompletionItem(c) for c in results]

        return t.cast(t.List["CompletionItem"], results)

    return self.type.shell_complete(ctx, self, incomplete)

def _parse_decls(
    self, decls: t.Sequence[str], expose_value: bool
) -> t.Tuple[t.Optional[str], t.List[str], t.List[str]]:
    opts = []
    secondary_opts = []
    name = None
    possible_names = []

    for decl in decls:
        if decl.isidentifier():
            if name is not None:
                raise TypeError(f"Name '{name}' defined twice")
            name = decl
        else:
            split_char = ";" if decl[:1] == "/" else "/"
            if split_char in decl:
                first, second = decl.split(split_char, 1)
                first = first.rstrip()
                if first:
                    possible_names.append(split_opt(first))
                    opts.append(first)
                second = second.lstrip()
                if second:
                    secondary_opts.append(second.lstrip())
                if first == second:
                    raise ValueError(
                        f"Boolean option {decl!r} cannot use the"
                        " same flag for true/false."
                    )
            else:
                possible_names.append(split_opt(decl))
                opts.append(decl)

    if name is None and possible_names:
        possible_names.sort(key=lambda x: -len(x[0]))  # group long options first
        name = possible_names[0][1].replace("-", "_").lower()
        if not name.isidentifier():
            name = None

    if name is None:
        if not expose_value:
            return None, opts, secondary_opts
        raise TypeError(
            f"Could not determine name for option with declarations {decls!r}"
        )

    if not opts and not secondary_opts:
        raise TypeError(
            f"No options defined but a name was passed ({name})."
            " Did you mean to declare an argument instead? Did"
            f" you mean to pass '--{name}'?"
        )

    return name, opts, secondary_opts

def add_to_parser(self, parser: OptionParser, ctx: Context) -> None:
    if self.multiple:
        action = "append"
    elif self.count:
        action = "count"
    else:
        action = "store"

    if self.is_flag:
        action = f"{action}_const"

        if self.is_bool_flag and self.secondary_opts:
            parser.add_option(
                obj=self, opts=self.opts, dest=self.name, action=action, const=True
            )
            parser.add_option(
                obj=self,
                opts=self.secondary_opts,
                dest=self.name,
                action=action,
                const=False,
            )
        else:
            parser.add_option(
                obj=self,
                opts=self.opts,
                dest=self.name,
                action=action,
                const=self.flag_value,
            )
    else:
        parser.add_option(
            obj=self,
            opts=self.opts,
            dest=self.name,
            action=action,
            nargs=self.nargs,
        )

def get_help_record(self, ctx: Context) -> t.Optional[t.Tuple[str, str]]:
    if self.hidden:
        return None

    any_prefix_is_slash = False

    def _write_opts(opts: t.Sequence[str]) -> str:
        nonlocal any_prefix_is_slash

        rv, any_slashes = join_options(opts)

        if any_slashes:
            any_prefix_is_slash = True

        if not self.is_flag and not self.count:
            rv += f" {self.make_metavar()}"

        return rv

    rv = [_write_opts(self.opts)]

    if self.secondary_opts:
        rv.append(_write_opts(self.secondary_opts))

    help = self.help or ""
    extra = []

    if self.show_envvar:
        envvar = self.envvar

        if envvar is None:
            if (
                self.allow_from_autoenv
                and ctx.auto_envvar_prefix is not None
                and self.name is not None
            ):
                envvar = f"{ctx.auto_envvar_prefix}_{self.name.upper()}"

        if envvar is not None:
            var_str = (
                envvar
                if isinstance(envvar, str)
                else ", ".join(str(d) for d in envvar)
            )
            extra.append(_("env var: {var}").format(var=var_str))

    # Temporarily enable resilient parsing to avoid type casting
    # failing for the default. Might be possible to extend this to
    # help formatting in general.
    resilient = ctx.resilient_parsing
    ctx.resilient_parsing = True

    try:
        default_value = self.get_default(ctx, call=False)
    finally:
        ctx.resilient_parsing = resilient

    show_default = False
    show_default_is_str = False

    if self.show_default is not None:
        if isinstance(self.show_default, str):
            show_default_is_str = show_default = True
        else:
            show_default = self.show_default
    elif ctx.show_default is not None:
        show_default = ctx.show_default

    if show_default_is_str or (show_default and (default_value is not None)):
        if show_default_is_str:
            default_string = f"({self.show_default})"
        elif isinstance(default_value, (list, tuple)):
            default_string = ", ".join(str(d) for d in default_value)
        elif inspect.isfunction(default_value):
            default_string = _("(dynamic)")
        elif self.is_bool_flag and self.secondary_opts:
            # For boolean flags that have distinct True/False opts,
            # use the opt without prefix instead of the value.
            default_string = split_opt(
                (self.opts if default_value else self.secondary_opts)[0]
            )[1]
        elif self.is_bool_flag and not self.secondary_opts and not default_value:
            default_string = ""
        elif default_value == "":
            default_string = '""'
        else:
            default_string = str(default_value)

        if default_string:
            extra.append(_("default: {default}").format(default=default_string))

    if (
        isinstance(self.type, types._NumberRangeBase)
        # skip count with default range type
        and not (self.count and self.type.min == 0 and self.type.max is None)
    ):
        range_str = self.type._describe_range()

        if range_str:
            extra.append(range_str)

    if self.required:
        extra.append(_("required"))

    if extra:
        extra_str = "; ".join(extra)
        help = f"{help}  [{extra_str}]" if help else f"[{extra_str}]"

    return ("; " if any_prefix_is_slash else " / ").join(rv), help

def _write_opts(opts: t.Sequence[str]) -> str:
    nonlocal any_prefix_is_slash

    rv, any_slashes = join_options(opts)

    if any_slashes:
        any_prefix_is_slash = True

    if not self.is_flag and not self.count:
        rv += f" {self.make_metavar()}"

    return rv

def get_default(
    self, ctx: Context, call: bool = True
) -> t.Optional[t.Union[t.Any, t.Callable[[], t.Any]]]:
    # If we're a non boolean flag our default is more complex because
    # we need to look at all flags in the same group to figure out
    # if we're the default one in which case we return the flag
    # value as default.
    if self.is_flag and not self.is_bool_flag:
        for param in ctx.command.params:
            if param.name == self.name and param.default:
                return t.cast(Option, param).flag_value

        return None

    return super().get_default(ctx, call=call)

def resolve_envvar_value(self, ctx: Context) -> t.Optional[str]:
    rv = super().resolve_envvar_value(ctx)

    if rv is not None:
        return rv

    if (
        self.allow_from_autoenv
        and ctx.auto_envvar_prefix is not None
        and self.name is not None
    ):
        envvar = f"{ctx.auto_envvar_prefix}_{self.name.upper()}"
        rv = os.environ.get(envvar)

        if rv:
            return rv

    return None

def value_from_envvar(self, ctx: Context) -> t.Optional[t.Any]:
    rv: t.Optional[t.Any] = self.resolve_envvar_value(ctx)

    if rv is None:
        return None

    value_depth = (self.nargs != 1) + bool(self.multiple)

    if value_depth > 0:
        rv = self.type.split_envvar_value(rv)

        if self.multiple and self.nargs != 1:
            rv = batch(rv, self.nargs)

    return rv

def consume_value(
    self, ctx: Context, opts: t.Mapping[str, "Parameter"]
) -> t.Tuple[t.Any, ParameterSource]:
    value, source = super().consume_value(ctx, opts)

    # The parser will emit a sentinel value if the option can be
    # given as a flag without a value. This is different from None
    # to distinguish from the flag not being given at all.
    if value is _flag_needs_value:
        if self.prompt is not None and not ctx.resilient_parsing:
            value = self.prompt_for_value(ctx)
            source = ParameterSource.PROMPT
        else:
            value = self.flag_value
            source = ParameterSource.COMMANDLINE

    elif (
        self.multiple
        and value is not None
        and any(v is _flag_needs_value for v in value)
    ):
        value = [self.flag_value if v is _flag_needs_value else v for v in value]
        source = ParameterSource.COMMANDLINE

    # The value wasn't set, or used the param's default, prompt if
    # prompting is enabled.
    elif (
        source in {None, ParameterSource.DEFAULT}
        and self.prompt is not None
        and (self.required or self.prompt_required)
        and not ctx.resilient_parsing
    ):
        value = self.prompt_for_value(ctx)
        source = ParameterSource.PROMPT

    return value, source

def __init__(
    self,
    param_decls: t.Sequence[str],
    required: t.Optional[bool] = None,
    **attrs: t.Any,
) -> None:
    if required is None:
        if attrs.get("default") is not None:
            required = False
        else:
            required = attrs.get("nargs", 1) > 0

    if "multiple" in attrs:
        raise TypeError("__init__() got an unexpected keyword argument 'multiple'.")

    super().__init__(param_decls, required=required, **attrs)

    if __debug__:
        if self.default is not None and self.nargs == -1:
            raise TypeError("'default' is not supported for nargs=-1.")

@property
def human_readable_name(self) -> str:
    if self.metavar is not None:
        return self.metavar
    return self.name.upper()  # type: ignore

def make_metavar(self) -> str:
    if self.metavar is not None:
        return self.metavar
    var = self.type.get_metavar(self)
    if not var:
        var = self.name.upper()  # type: ignore
    if not self.required:
        var = f"[{var}]"
    if self.nargs != 1:
        var += "..."
    return var

def _parse_decls(
    self, decls: t.Sequence[str], expose_value: bool
) -> t.Tuple[t.Optional[str], t.List[str], t.List[str]]:
    if not decls:
        if not expose_value:
            return None, [], []
        raise TypeError("Argument is marked as exposed, but does not have a name.")
    if len(decls) == 1:
        name = arg = decls[0]
        name = name.replace("-", "_").lower()
    else:
        raise TypeError(
            "Arguments take exactly one parameter declaration, got"
            f" {len(decls)}."
        )
    return name, [arg], []

def pass_context(f: "t.Callable[te.Concatenate[Context, P], R]") -> "t.Callable[P, R]":
    """Marks a callback as wanting to receive the current context
    object as first argument.
    """

    def new_func(*args: "P.args", **kwargs: "P.kwargs") -> "R":
        return f(get_current_context(), *args, **kwargs)

    return update_wrapper(new_func, f)

def pass_obj(f: "t.Callable[te.Concatenate[t.Any, P], R]") -> "t.Callable[P, R]":
    """Similar to :func:`pass_context`, but only pass the object on the
    context onwards (:attr:`Context.obj`).  This is useful if that object
    represents the state of a nested system.
    """

    def new_func(*args: "P.args", **kwargs: "P.kwargs") -> "R":
        return f(get_current_context().obj, *args, **kwargs)

    return update_wrapper(new_func, f)

def make_pass_decorator(
    object_type: t.Type[T], ensure: bool = False
) -> t.Callable[["t.Callable[te.Concatenate[T, P], R]"], "t.Callable[P, R]"]:
    """Given an object type this creates a decorator that will work
    similar to :func:`pass_obj` but instead of passing the object of the
    current context, it will find the innermost context of type
    :func:`object_type`.

    This generates a decorator that works roughly like this::

        from functools import update_wrapper

        def decorator(f):
            @pass_context
            def new_func(ctx, *args, **kwargs):
                obj = ctx.find_object(object_type)
                return ctx.invoke(f, obj, *args, **kwargs)
            return update_wrapper(new_func, f)
        return decorator

    :param object_type: the type of the object to pass.
    :param ensure: if set to `True`, a new object will be created and
                   remembered on the context if it's not there yet.
    """

    def decorator(f: "t.Callable[te.Concatenate[T, P], R]") -> "t.Callable[P, R]":
        def new_func(*args: "P.args", **kwargs: "P.kwargs") -> "R":
            ctx = get_current_context()

            obj: t.Optional[T]
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)

            if obj is None:
                raise RuntimeError(
                    "Managed to invoke callback without a context"
                    f" object of type {object_type.__name__!r}"
                    " existing."
                )

            return ctx.invoke(f, obj, *args, **kwargs)

        return update_wrapper(new_func, f)

    return decorator

def decorator(f: "t.Callable[te.Concatenate[T, P], R]") -> "t.Callable[P, R]":
    def new_func(*args: "P.args", **kwargs: "P.kwargs") -> "R":
        ctx = get_current_context()

        obj: t.Optional[T]
        if ensure:
            obj = ctx.ensure_object(object_type)
        else:
            obj = ctx.find_object(object_type)

        if obj is None:
            raise RuntimeError(
                "Managed to invoke callback without a context"
                f" object of type {object_type.__name__!r}"
                " existing."
            )

        return ctx.invoke(f, obj, *args, **kwargs)

    return update_wrapper(new_func, f)

def new_func(*args: "P.args", **kwargs: "P.kwargs") -> "R":
    ctx = get_current_context()

    obj: t.Optional[T]
    if ensure:
        obj = ctx.ensure_object(object_type)
    else:
        obj = ctx.find_object(object_type)

    if obj is None:
        raise RuntimeError(
            "Managed to invoke callback without a context"
            f" object of type {object_type.__name__!r}"
            " existing."
        )

    return ctx.invoke(f, obj, *args, **kwargs)

def pass_meta_key(
    key: str, *, doc_description: t.Optional[str] = None
) -> "t.Callable[[t.Callable[te.Concatenate[t.Any, P], R]], t.Callable[P, R]]":
    """Create a decorator that passes a key from
    :attr:`click.Context.meta` as the first argument to the decorated
    function.

    :param key: Key in ``Context.meta`` to pass.
    :param doc_description: Description of the object being passed,
        inserted into the decorator's docstring. Defaults to "the 'key'
        key from Context.meta".

    .. versionadded:: 8.0
    """

    def decorator(f: "t.Callable[te.Concatenate[t.Any, P], R]") -> "t.Callable[P, R]":
        def new_func(*args: "P.args", **kwargs: "P.kwargs") -> R:
            ctx = get_current_context()
            obj = ctx.meta[key]
            return ctx.invoke(f, obj, *args, **kwargs)

        return update_wrapper(new_func, f)

    if doc_description is None:
        doc_description = f"the {key!r} key from :attr:`click.Context.meta`"

    decorator.__doc__ = (
        f"Decorator that passes {doc_description} as the first argument"
        " to the decorated function."
    )
    return decorator

def decorator(f: "t.Callable[te.Concatenate[t.Any, P], R]") -> "t.Callable[P, R]":
    def new_func(*args: "P.args", **kwargs: "P.kwargs") -> R:
        ctx = get_current_context()
        obj = ctx.meta[key]
        return ctx.invoke(f, obj, *args, **kwargs)

    return update_wrapper(new_func, f)

def new_func(*args: "P.args", **kwargs: "P.kwargs") -> R:
    ctx = get_current_context()
    obj = ctx.meta[key]
    return ctx.invoke(f, obj, *args, **kwargs)

def decorator(f: _AnyCallable) -> CmdType:
    if isinstance(f, Command):
        raise TypeError("Attempted to convert a callback into a command twice.")

    attr_params = attrs.pop("params", None)
    params = attr_params if attr_params is not None else []

    try:
        decorator_params = f.__click_params__  # type: ignore
    except AttributeError:
        pass
    else:
        del f.__click_params__  # type: ignore
        params.extend(reversed(decorator_params))

    if attrs.get("help") is None:
        attrs["help"] = f.__doc__

    if t.TYPE_CHECKING:
        assert cls is not None
        assert not callable(name)

    cmd = cls(
        name=name or f.__name__.lower().replace("_", "-"),
        callback=f,
        params=params,
        **attrs,
    )
    cmd.__doc__ = f.__doc__
    return cmd

def group(
    name: t.Union[str, _AnyCallable, None] = None,
    cls: t.Optional[t.Type[GrpType]] = None,
    **attrs: t.Any,
) -> t.Union[Group, t.Callable[[_AnyCallable], t.Union[Group, GrpType]]]:
    """Creates a new :class:`Group` with a function as callback.  This
    works otherwise the same as :func:`command` just that the `cls`
    parameter is set to :class:`Group`.

    .. versionchanged:: 8.1
        This decorator can be applied without parentheses.
    """
    if cls is None:
        cls = t.cast(t.Type[GrpType], Group)

    if callable(name):
        return command(cls=cls, **attrs)(name)

    return command(name, cls, **attrs)

def _param_memo(f: t.Callable[..., t.Any], param: Parameter) -> None:
    if isinstance(f, Command):
        f.params.append(param)
    else:
        if not hasattr(f, "__click_params__"):
            f.__click_params__ = []  # type: ignore

        f.__click_params__.append(param)  # type: ignore

def decorator(f: FC) -> FC:
    _param_memo(f, cls(param_decls, **attrs))
    return f

def decorator(f: FC) -> FC:
    _param_memo(f, cls(param_decls, **attrs))
    return f

def callback(ctx: Context, param: Parameter, value: bool) -> None:
    if not value:
        ctx.abort()

def callback(ctx: Context, param: Parameter, value: bool) -> None:
    if not value or ctx.resilient_parsing:
        return

    nonlocal prog_name
    nonlocal version

    if prog_name is None:
        prog_name = ctx.find_root().info_name

    if version is None and package_name is not None:
        metadata: t.Optional[types.ModuleType]

        try:
            from importlib import metadata
        except ImportError:
            # Python < 3.8
            import importlib_metadata as metadata  # type: ignore

        try:
            version = metadata.version(package_name)  # type: ignore
        except metadata.PackageNotFoundError:  # type: ignore
            raise RuntimeError(
                f"{package_name!r} is not installed. Try passing"
                " 'package_name' instead."
            ) from None

    if version is None:
        raise RuntimeError(
            f"Could not determine the version for {package_name!r} automatically."
        )

    echo(
        message % {"prog": prog_name, "package": package_name, "version": version},
        color=ctx.color,
    )
    ctx.exit()

@staticmethod
def show_help(ctx: Context, param: Parameter, value: bool) -> None:
    """Callback that print the help page on ``<stdout>`` and exits."""
    if value and not ctx.resilient_parsing:
        echo(ctx.get_help(), color=ctx.color)
        ctx.exit()

def _join_param_hints(
    param_hint: t.Optional[t.Union[t.Sequence[str], str]],
) -> t.Optional[str]:
    if param_hint is not None and not isinstance(param_hint, str):
        return " / ".join(repr(x) for x in param_hint)

    return param_hint

def show(self, file: t.Optional[t.IO[t.Any]] = None) -> None:
    if file is None:
        file = get_text_stderr()

    echo(
        _("Error: {message}").format(message=self.format_message()),
        file=file,
        color=self.show_color,
    )

def show(self, file: t.Optional[t.IO[t.Any]] = None) -> None:
    if file is None:
        file = get_text_stderr()
    color = None
    hint = ""
    if (
        self.ctx is not None
        and self.ctx.command.get_help_option(self.ctx) is not None
    ):
        hint = _("Try '{command} {option}' for help.").format(
            command=self.ctx.command_path, option=self.ctx.help_option_names[0]
        )
        hint = f"{hint}\n"
    if self.ctx is not None:
        color = self.ctx.color
        echo(f"{self.ctx.get_usage()}\n{hint}", file=file, color=color)
    echo(
        _("Error: {message}").format(message=self.format_message()),
        file=file,
        color=color,
    )

def format_message(self) -> str:
    if self.param_hint is not None:
        param_hint = self.param_hint
    elif self.param is not None:
        param_hint = self.param.get_error_hint(self.ctx)  # type: ignore
    else:
        return _("Invalid value: {message}").format(message=self.message)

    return _("Invalid value for {param_hint}: {message}").format(
        param_hint=_join_param_hints(param_hint), message=self.message
    )

def format_message(self) -> str:
    if self.param_hint is not None:
        param_hint: t.Optional[str] = self.param_hint
    elif self.param is not None:
        param_hint = self.param.get_error_hint(self.ctx)  # type: ignore
    else:
        param_hint = None

    param_hint = _join_param_hints(param_hint)
    param_hint = f" {param_hint}" if param_hint else ""

    param_type = self.param_type
    if param_type is None and self.param is not None:
        param_type = self.param.param_type_name

    msg = self.message
    if self.param is not None:
        msg_extra = self.param.type.get_missing_message(self.param)
        if msg_extra:
            if msg:
                msg += f". {msg_extra}"
            else:
                msg = msg_extra

    msg = f" {msg}" if msg else ""

    # Translate param_type for known types.
    if param_type == "argument":
        missing = _("Missing argument")
    elif param_type == "option":
        missing = _("Missing option")
    elif param_type == "parameter":
        missing = _("Missing parameter")
    else:
        missing = _("Missing {param_type}").format(param_type=param_type)

    return f"{missing}{param_hint}.{msg}"

def __str__(self) -> str:
    if not self.message:
        param_name = self.param.name if self.param else None
        return _("Missing parameter: {param_name}").format(param_name=param_name)
    else:
        return self.message

def format_message(self) -> str:
    if not self.possibilities:
        return self.message

    possibility_str = ", ".join(sorted(self.possibilities))
    suggest = ngettext(
        "Did you mean {possibility}?",
        "(Possible options: {possibilities})",
        len(self.possibilities),
    ).format(possibility=possibility_str, possibilities=possibility_str)
    return f"{self.message} {suggest}"

def __init__(
    self, option_name: str, message: str, ctx: t.Optional["Context"] = None
) -> None:
    super().__init__(message, ctx)
    self.option_name = option_name

def __init__(self, filename: str, hint: t.Optional[str] = None) -> None:
    if hint is None:
        hint = _("unknown error")

    super().__init__(hint)
    self.ui_filename: str = format_filename(filename)
    self.filename = filename

def format_message(self) -> str:
    return _("Could not open file {filename!r}: {message}").format(
        filename=self.ui_filename, message=self.message
    )

def measure_table(rows: t.Iterable[t.Tuple[str, str]]) -> t.Tuple[int, ...]:
    widths: t.Dict[int, int] = {}

    for row in rows:
        for idx, col in enumerate(row):
            widths[idx] = max(widths.get(idx, 0), term_len(col))

    return tuple(y for x, y in sorted(widths.items()))

def iter_rows(
    rows: t.Iterable[t.Tuple[str, str]], col_count: int
) -> t.Iterator[t.Tuple[str, ...]]:
    for row in rows:
        yield row + ("",) * (col_count - len(row))

def _flush_par() -> None:
    if not buf:
        return
    if buf[0].strip() == "\b":
        p.append((indent or 0, True, "\n".join(buf[1:])))
    else:
        p.append((indent or 0, False, " ".join(buf)))
    del buf[:]

def write(self, string: str) -> None:
    """Writes a unicode string into the internal buffer."""
    self.buffer.append(string)

def indent(self) -> None:
    """Increases the indentation."""
    self.current_indent += self.indent_increment

def dedent(self) -> None:
    """Decreases the indentation."""
    self.current_indent -= self.indent_increment

def write_heading(self, heading: str) -> None:
    """Writes a heading into the buffer."""
    self.write(f"{'':>{self.current_indent}}{heading}:\n")

def write_paragraph(self) -> None:
    """Writes a paragraph into the buffer."""
    if self.buffer:
        self.write("\n")

@contextmanager
def indentation(self) -> t.Iterator[None]:
    """A context manager that increases the indentation."""
    self.indent()
    try:
        yield
    finally:
        self.dedent()

def getvalue(self) -> str:
    """Returns the buffer contents."""
    return "".join(self.buffer)

def push_context(ctx: "Context") -> None:
    """Pushes a new context to the current stack."""
    _local.__dict__.setdefault("stack", []).append(ctx)

def pop_context() -> None:
    """Removes the top level from the stack."""
    _local.stack.pop()

def _unpack_args(
    args: t.Sequence[str], nargs_spec: t.Sequence[int]
) -> t.Tuple[t.Sequence[t.Union[str, t.Sequence[t.Optional[str]], None]], t.List[str]]:
    """Given an iterable of arguments and an iterable of nargs specifications,
    it returns a tuple with all the unpacked arguments at the first index
    and all remaining arguments as the second.

    The nargs specification is the number of arguments that should be consumed
    or `-1` to indicate that this position should eat up all the remainders.

    Missing items are filled with `None`.
    """
    args = deque(args)
    nargs_spec = deque(nargs_spec)
    rv: t.List[t.Union[str, t.Tuple[t.Optional[str], ...], None]] = []
    spos: t.Optional[int] = None

    def _fetch(c: "te.Deque[V]") -> t.Optional[V]:
        try:
            if spos is None:
                return c.popleft()
            else:
                return c.pop()
        except IndexError:
            return None

    while nargs_spec:
        nargs = _fetch(nargs_spec)

        if nargs is None:
            continue

        if nargs == 1:
            rv.append(_fetch(args))
        elif nargs > 1:
            x = [_fetch(args) for _ in range(nargs)]

            # If we're reversed, we're pulling in the arguments in reverse,
            # so we need to turn them around.
            if spos is not None:
                x.reverse()

            rv.append(tuple(x))
        elif nargs < 0:
            if spos is not None:
                raise TypeError("Cannot have two nargs < 0")

            spos = len(rv)
            rv.append(None)

    # spos is the position of the wildcard (star).  If it's not `None`,
    # we fill it with the remainder.
    if spos is not None:
        rv[spos] = tuple(args)
        args = []
        rv[spos + 1 :] = reversed(rv[spos + 1 :])

    return tuple(rv), list(args)

def _fetch(c: "te.Deque[V]") -> t.Optional[V]:
    try:
        if spos is None:
            return c.popleft()
        else:
            return c.pop()
    except IndexError:
        return None

def split_opt(opt: str) -> t.Tuple[str, str]:
    first = opt[:1]
    if first.isalnum():
        return "", opt
    if opt[1:2] == first:
        return opt[:2], opt[2:]
    return first, opt[1:]

def normalize_opt(opt: str, ctx: t.Optional["Context"]) -> str:
    if ctx is None or ctx.token_normalize_func is None:
        return opt
    prefix, opt = split_opt(opt)
    return f"{prefix}{ctx.token_normalize_func(opt)}"

@property
def takes_value(self) -> bool:
    return self.action in ("store", "append")

def process(self, value: t.Any, state: "ParsingState") -> None:
    if self.action == "store":
        state.opts[self.dest] = value  # type: ignore
    elif self.action == "store_const":
        state.opts[self.dest] = self.const  # type: ignore
    elif self.action == "append":
        state.opts.setdefault(self.dest, []).append(value)  # type: ignore
    elif self.action == "append_const":
        state.opts.setdefault(self.dest, []).append(self.const)  # type: ignore
    elif self.action == "count":
        state.opts[self.dest] = state.opts.get(self.dest, 0) + 1  # type: ignore
    else:
        raise ValueError(f"unknown action '{self.action}'")
    state.order.append(self.obj)

def process(
    self,
    value: t.Union[t.Optional[str], t.Sequence[t.Optional[str]]],
    state: "ParsingState",
) -> None:
    if self.nargs > 1:
        assert value is not None
        holes = sum(1 for x in value if x is None)
        if holes == len(value):
            value = None
        elif holes != 0:
            raise BadArgumentUsage(
                _("Argument {name!r} takes {nargs} values.").format(
                    name=self.dest, nargs=self.nargs
                )
            )

    if self.nargs == -1 and self.obj.envvar is not None and value == ():
        # Replace empty tuple with None so that a value from the
        # environment may be tried.
        value = None

    state.opts[self.dest] = value  # type: ignore
    state.order.append(self.obj)

def __init__(self, rargs: t.List[str]) -> None:
    self.opts: t.Dict[str, t.Any] = {}
    self.largs: t.List[str] = []
    self.rargs = rargs
    self.order: t.List[CoreParameter] = []

def _process_args_for_args(self, state: ParsingState) -> None:
    pargs, args = _unpack_args(
        state.largs + state.rargs, [x.nargs for x in self._args]
    )

    for idx, arg in enumerate(self._args):
        arg.process(pargs[idx], state)

    state.largs = args
    state.rargs = []

def _process_args_for_options(self, state: ParsingState) -> None:
    while state.rargs:
        arg = state.rargs.pop(0)
        arglen = len(arg)
        # Double dashes always handled explicitly regardless of what
        # prefixes are valid.
        if arg == "--":
            return
        elif arg[:1] in self._opt_prefixes and arglen > 1:
            self._process_opts(arg, state)
        elif self.allow_interspersed_args:
            state.largs.append(arg)
        else:
            state.rargs.insert(0, arg)
            return

def _match_long_opt(
    self, opt: str, explicit_value: t.Optional[str], state: ParsingState
) -> None:
    if opt not in self._long_opt:
        from difflib import get_close_matches

        possibilities = get_close_matches(opt, self._long_opt)
        raise NoSuchOption(opt, possibilities=possibilities, ctx=self.ctx)

    option = self._long_opt[opt]
    if option.takes_value:
        # At this point it's safe to modify rargs by injecting the
        # explicit value, because no exception is raised in this
        # branch.  This means that the inserted value will be fully
        # consumed.
        if explicit_value is not None:
            state.rargs.insert(0, explicit_value)

        value = self._get_value_from_state(opt, option, state)

    elif explicit_value is not None:
        raise BadOptionUsage(
            opt, _("Option {name!r} does not take a value.").format(name=opt)
        )

    else:
        value = None

    option.process(value, state)

def _get_value_from_state(
    self, option_name: str, option: Option, state: ParsingState
) -> t.Any:
    nargs = option.nargs

    if len(state.rargs) < nargs:
        if option.obj._flag_needs_value:
            # Option allows omitting the value.
            value = _flag_needs_value
        else:
            raise BadOptionUsage(
                option_name,
                ngettext(
                    "Option {name!r} requires an argument.",
                    "Option {name!r} requires {nargs} arguments.",
                    nargs,
                ).format(name=option_name, nargs=nargs),
            )
    elif nargs == 1:
        next_rarg = state.rargs[0]

        if (
            option.obj._flag_needs_value
            and isinstance(next_rarg, str)
            and next_rarg[:1] in self._opt_prefixes
            and len(next_rarg) > 1
        ):
            # The next arg looks like the start of an option, don't
            # use it as the value if omitting the value is allowed.
            value = _flag_needs_value
        else:
            value = state.rargs.pop(0)
    else:
        value = tuple(state.rargs[:nargs])
        del state.rargs[:nargs]

    return value

def source_vars(self) -> t.Dict[str, t.Any]:
    """Vars for formatting :attr:`source_template`.

    By default this provides ``complete_func``, ``complete_var``,
    and ``prog_name``.
    """
    return {
        "complete_func": self.func_name,
        "complete_var": self.complete_var,
        "prog_name": self.prog_name,
    }

@staticmethod
def _check_version() -> None:
    import shutil
    import subprocess

    bash_exe = shutil.which("bash")

    if bash_exe is None:
        match = None
    else:
        output = subprocess.run(
            [bash_exe, "--norc", "-c", 'echo "${BASH_VERSION}"'],
            stdout=subprocess.PIPE,
        )
        match = re.search(r"^(\d+)\.(\d+)\.\d+", output.stdout.decode())

    if match is not None:
        major, minor = match.groups()

        if major < "4" or major == "4" and minor < "4":
            echo(
                _(
                    "Shell completion is not supported for Bash"
                    " versions older than 4.4."
                ),
                err=True,
            )
    else:
        echo(
            _("Couldn't detect Bash version, shell completion is not supported."),
            err=True,
        )

def source(self) -> str:
    self._check_version()
    return super().source()

def get_completion_args(self) -> t.Tuple[t.List[str], str]:
    cwords = split_arg_string(os.environ["COMP_WORDS"])
    cword = int(os.environ["COMP_CWORD"])
    args = cwords[1:cword]

    try:
        incomplete = cwords[cword]
    except IndexError:
        incomplete = ""

    return args, incomplete

def get_completion_args(self) -> t.Tuple[t.List[str], str]:
    cwords = split_arg_string(os.environ["COMP_WORDS"])
    cword = int(os.environ["COMP_CWORD"])
    args = cwords[1:cword]

    try:
        incomplete = cwords[cword]
