def format_completion(self, item: CompletionItem) -> str:
    if item.help:
        return f"{item.type},{item.value}\t{item.help}"

    return f"{item.type},{item.value}"

def _start_of_option(ctx: Context, value: str) -> bool:
    """Check if the value looks like the start of an option."""
    if not value:
        return False

    c = value[0]
    return c in ctx._opt_prefixes

def _is_incomplete_option(ctx: Context, args: t.List[str], param: Parameter) -> bool:
    """Determine if the given parameter is an option that needs a value.

    :param args: List of complete args before the incomplete value.
    :param param: Option object being checked.
    """
    if not isinstance(param, Option):
        return False

    if param.is_flag or param.count:
        return False

    last_option = None

    for index, arg in enumerate(reversed(args)):
        if index + 1 > param.nargs:
            break

        if _start_of_option(ctx, arg):
            last_option = arg

    return last_option is not None and last_option in param.opts

def hidden_prompt_func(prompt: str) -> str:
    import getpass

    return getpass.getpass(prompt)

def _format_default(default: t.Any) -> t.Any:
    if isinstance(default, (io.IOBase, LazyFile)) and hasattr(default, "name"):
        return default.name

    return default

def prompt_func(text: str) -> str:
    f = hidden_prompt_func if hide_input else visible_prompt_func
    try:
        # Write the prompt separately so that we get nice
        # coloring through colorama on Windows
        echo(text.rstrip(" "), nl=False, err=err)
        # Echo a space to stdout to work around an issue where
        # readline causes backspace to clear the whole line.
        return f(" ")
    except (KeyboardInterrupt, EOFError):
        # getpass doesn't print a newline if the user aborts input with ^C.
        # Allegedly this behavior is inherited from getpass(3).
        # A doc bug has been filed at https://bugs.python.org/issue24711
        if hide_input:
            echo(None, err=err)
        raise Abort() from None

def clear() -> None:
    """Clears the terminal screen.  This will have the effect of clearing
    the whole visible space of the terminal and moving the cursor to the
    top left.  This does not do anything if not connected to a terminal.

    .. versionadded:: 2.0
    """
    if not isatty(sys.stdout):
        return

    # ANSI escape \033[2J clears the screen, \033[1;1H moves the cursor
    echo("\033[2J\033[1;1H", nl=False)

def _interpret_color(
    color: t.Union[int, t.Tuple[int, int, int], str], offset: int = 0
) -> str:
    if isinstance(color, int):
        return f"{38 + offset};5;{color:d}"

    if isinstance(color, (tuple, list)):
        r, g, b = color
        return f"{38 + offset};2;{r:d};{g:d};{b:d}"

    return str(_ansi_colors[color] + offset)

def raw_terminal() -> t.ContextManager[int]:
    from ._termui_impl import raw_terminal as f

    return f()

def pause(info: t.Optional[str] = None, err: bool = False) -> None:
    """This command stops execution and waits for the user to press any
    key to continue.  This is similar to the Windows batch "pause"
    command.  If the program is not run through a terminal, this command
    will instead do nothing.

    .. versionadded:: 2.0

    .. versionadded:: 4.0
       Added the `err` parameter.

    :param info: The message to print before pausing. Defaults to
        ``"Press any key to continue..."``.
    :param err: if set to message goes to ``stderr`` instead of
                ``stdout``, the same as with echo.
    """
    if not isatty(sys.stdin) or not isatty(sys.stdout):
        return

    if info is None:
        info = _("Press any key to continue...")

    try:
        if info:
            echo(info, nl=False, err=err)
        try:
            getchar()
        except (KeyboardInterrupt, EOFError):
            pass
    finally:
        if info:
            echo(err=err)

def _echo(self, rv: bytes) -> bytes:
    if not self._paused:
        self._output.write(rv)

    return rv

@contextlib.contextmanager
def _pause_echo(stream: t.Optional[EchoingStdin]) -> t.Iterator[None]:
    if stream is None:
        yield
    else:
        stream._paused = True
        yield
        stream._paused = False

def __init__(
    self, buffer: t.BinaryIO, name: str, mode: str, **kwargs: t.Any
) -> None:
    super().__init__(buffer, **kwargs)
    self._name = name
    self._mode = mode

@property
def name(self) -> str:
    return self._name

@property
def mode(self) -> str:
    return self._mode

def make_input_stream(
    input: t.Optional[t.Union[str, bytes, t.IO[t.Any]]], charset: str
) -> t.BinaryIO:
    # Is already an input stream.
    if hasattr(input, "read"):
        rv = _find_binary_reader(t.cast(t.IO[t.Any], input))

        if rv is not None:
            return rv

        raise TypeError("Could not find binary reader for input stream.")

    if input is None:
        input = b""
    elif isinstance(input, str):
        input = input.encode(charset)

    return io.BytesIO(input)

@property
def output(self) -> str:
    """The (standard) output as unicode string."""
    return self.stdout

@property
def stdout(self) -> str:
    """The standard output as unicode string."""
    return self.stdout_bytes.decode(self.runner.charset, "replace").replace(
        "\r\n", "\n"
    )

@property
def stderr(self) -> str:
    """The standard error as unicode string."""
    if self.stderr_bytes is None:
        raise ValueError("stderr not separately captured")
    return self.stderr_bytes.decode(self.runner.charset, "replace").replace(
        "\r\n", "\n"
    )

def __repr__(self) -> str:
    exc_str = repr(self.exception) if self.exception else "okay"
    return f"<{type(self).__name__} {exc_str}>"

def make_env(
    self, overrides: t.Optional[t.Mapping[str, t.Optional[str]]] = None
) -> t.Mapping[str, t.Optional[str]]:
    """Returns the environment overrides for invoking a script."""
    rv = dict(self.env)
    if overrides:
        rv.update(overrides)
    return rv

@_pause_echo(echo_input)  # type: ignore
def hidden_input(prompt: t.Optional[str] = None) -> str:
    sys.stdout.write(f"{prompt or ''}\n")
    sys.stdout.flush()
    return text_input.readline().rstrip("\r\n")

@_pause_echo(echo_input)  # type: ignore
def _getchar(echo: bool) -> str:
    char = sys.stdin.read(1)

    if echo:
        sys.stdout.write(char)

    sys.stdout.flush()
    return char

def should_strip_ansi(
    stream: t.Optional[t.IO[t.Any]] = None, color: t.Optional[bool] = None
) -> bool:
    if color is None:
        return not default_color
    return not color

def __call__(
    self,
    value: t.Any,
    param: t.Optional["Parameter"] = None,
    ctx: t.Optional["Context"] = None,
) -> t.Any:
    if value is not None:
        return self.convert(value, param, ctx)

def __init__(self, func: t.Callable[[t.Any], t.Any]) -> None:
    self.name: str = func.__name__
    self.func = func

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    try:
        return self.func(value)
    except ValueError:
        try:
            value = str(value)
        except UnicodeError:
            value = value.decode("utf-8", "replace")

        self.fail(value, param, ctx)

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    return value

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    if isinstance(value, bytes):
        enc = _get_argv_encoding()
        try:
            value = value.decode(enc)
        except UnicodeError:
            fs_enc = sys.getfilesystemencoding()
            if fs_enc != enc:
                try:
                    value = value.decode(fs_enc)
                except UnicodeError:
                    value = value.decode("utf-8", "replace")
            else:
                value = value.decode("utf-8", "replace")
        return value
    return str(value)

def __init__(self, choices: t.Sequence[str], case_sensitive: bool = True) -> None:
    self.choices = choices
    self.case_sensitive = case_sensitive

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    # Match through normalization and case sensitivity
    # first do token_normalize_func, then lowercase
    # preserve original `value` to produce an accurate message in
    # `self.fail`
    normed_value = value
    normed_choices = {choice: choice for choice in self.choices}

    if ctx is not None and ctx.token_normalize_func is not None:
        normed_value = ctx.token_normalize_func(value)
        normed_choices = {
            ctx.token_normalize_func(normed_choice): original
            for normed_choice, original in normed_choices.items()
        }

    if not self.case_sensitive:
        normed_value = normed_value.casefold()
        normed_choices = {
            normed_choice.casefold(): original
            for normed_choice, original in normed_choices.items()
        }

    if normed_value in normed_choices:
        return normed_choices[normed_value]

    choices_str = ", ".join(map(repr, self.choices))
    self.fail(
        ngettext(
            "{value!r} is not {choice}.",
            "{value!r} is not one of {choices}.",
            len(self.choices),
        ).format(value=value, choice=choices_str, choices=choices_str),
        param,
        ctx,
    )

def __init__(self, formats: t.Optional[t.Sequence[str]] = None):
    self.formats: t.Sequence[str] = formats or [
        "%Y-%m-%d",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
    ]

def _try_to_convert_date(self, value: t.Any, format: str) -> t.Optional[datetime]:
    try:
        return datetime.strptime(value, format)
    except ValueError:
        return None

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    if isinstance(value, datetime):
        return value

    for format in self.formats:
        converted = self._try_to_convert_date(value, format)

        if converted is not None:
            return converted

    formats_str = ", ".join(map(repr, self.formats))
    self.fail(
        ngettext(
            "{value!r} does not match the format {format}.",
            "{value!r} does not match the formats {formats}.",
            len(self.formats),
        ).format(value=value, format=formats_str, formats=formats_str),
        param,
        ctx,
    )

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    try:
        return self._number_class(value)
    except ValueError:
        self.fail(
            _("{value!r} is not a valid {number_type}.").format(
                value=value, number_type=self.name
            ),
            param,
            ctx,
        )

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    import operator

    rv = super().convert(value, param, ctx)
    lt_min: bool = self.min is not None and (
        operator.le if self.min_open else operator.lt
    )(rv, self.min)
    gt_max: bool = self.max is not None and (
        operator.ge if self.max_open else operator.gt
    )(rv, self.max)

    if self.clamp:
        if lt_min:
            return self._clamp(self.min, 1, self.min_open)  # type: ignore

        if gt_max:
            return self._clamp(self.max, -1, self.max_open)  # type: ignore

    if lt_min or gt_max:
        self.fail(
            _("{value} is not in the range {range}.").format(
                value=rv, range=self._describe_range()
            ),
            param,
            ctx,
        )

    return rv

def __repr__(self) -> str:
    clamp = " clamped" if self.clamp else ""
    return f"<{type(self).__name__} {self._describe_range()}{clamp}>"

def _clamp(  # type: ignore
    self, bound: int, dir: "te.Literal[1, -1]", open: bool
) -> int:
    if not open:
        return bound

    return bound + dir

def __init__(
    self,
    min: t.Optional[float] = None,
    max: t.Optional[float] = None,
    min_open: bool = False,
    max_open: bool = False,
    clamp: bool = False,
) -> None:
    super().__init__(
        min=min, max=max, min_open=min_open, max_open=max_open, clamp=clamp
    )

    if (min_open or max_open) and clamp:
        raise TypeError("Clamping is not supported for open bounds.")

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    if value in {False, True}:
        return bool(value)

    norm = value.strip().lower()

    if norm in {"1", "true", "t", "yes", "y", "on"}:
        return True

    if norm in {"0", "false", "f", "no", "n", "off"}:
        return False

    self.fail(
        _("{value!r} is not a valid boolean.").format(value=value), param, ctx
    )

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    import uuid

    if isinstance(value, uuid.UUID):
        return value

    value = value.strip()

    try:
        return uuid.UUID(value)
    except ValueError:
        self.fail(
            _("{value!r} is not a valid UUID.").format(value=value), param, ctx
        )

def resolve_lazy_flag(self, value: "t.Union[str, os.PathLike[str]]") -> bool:
    if self.lazy is not None:
        return self.lazy
    if os.fspath(value) == "-":
        return False
    elif "w" in self.mode:
        return True
    return False

def convert(
    self,
    value: t.Union[str, "os.PathLike[str]", t.IO[t.Any]],
    param: t.Optional["Parameter"],
    ctx: t.Optional["Context"],
) -> t.IO[t.Any]:
    if _is_file_like(value):
        return value

    value = t.cast("t.Union[str, os.PathLike[str]]", value)

    try:
        lazy = self.resolve_lazy_flag(value)

        if lazy:
            lf = LazyFile(
                value, self.mode, self.encoding, self.errors, atomic=self.atomic
            )

            if ctx is not None:
                ctx.call_on_close(lf.close_intelligently)

            return t.cast(t.IO[t.Any], lf)

        f, should_close = open_stream(
            value, self.mode, self.encoding, self.errors, atomic=self.atomic
        )

        # If a context is provided, we automatically close the file
        # at the end of the context execution (or flush out).  If a
        # context does not exist, it's the caller's responsibility to
        # properly close the file.  This for instance happens when the
        # type is used with prompts.
        if ctx is not None:
            if should_close:
                ctx.call_on_close(safecall(f.close))
            else:
                ctx.call_on_close(safecall(f.flush))

        return f
    except OSError as e:
        self.fail(f"'{format_filename(value)}': {e.strerror}", param, ctx)

def coerce_path_result(
    self, value: "t.Union[str, os.PathLike[str]]"
) -> "t.Union[str, bytes, os.PathLike[str]]":
    if self.type is not None and not isinstance(value, self.type):
        if self.type is str:
            return os.fsdecode(value)
        elif self.type is bytes:
            return os.fsencode(value)
        else:
            return t.cast("os.PathLike[str]", self.type(value))

    return value

def convert(
    self,
    value: "t.Union[str, os.PathLike[str]]",
    param: t.Optional["Parameter"],
    ctx: t.Optional["Context"],
) -> "t.Union[str, bytes, os.PathLike[str]]":
    rv = value

    is_dash = self.file_okay and self.allow_dash and rv in (b"-", "-")

    if not is_dash:
        if self.resolve_path:
            # os.path.realpath doesn't resolve symlinks on Windows
            # until Python 3.8. Use pathlib for now.
            import pathlib

            rv = os.fsdecode(pathlib.Path(rv).resolve())

        try:
            st = os.stat(rv)
        except OSError:
            if not self.exists:
                return self.coerce_path_result(rv)
            self.fail(
                _("{name} {filename!r} does not exist.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if not self.file_okay and stat.S_ISREG(st.st_mode):
            self.fail(
                _("{name} {filename!r} is a file.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )
        if not self.dir_okay and stat.S_ISDIR(st.st_mode):
            self.fail(
                _("{name} {filename!r} is a directory.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.readable and not os.access(rv, os.R_OK):
            self.fail(
                _("{name} {filename!r} is not readable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.writable and not os.access(rv, os.W_OK):
            self.fail(
                _("{name} {filename!r} is not writable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

        if self.executable and not os.access(value, os.X_OK):
            self.fail(
                _("{name} {filename!r} is not executable.").format(
                    name=self.name.title(), filename=format_filename(value)
                ),
                param,
                ctx,
            )

    return self.coerce_path_result(rv)

@property
def name(self) -> str:  # type: ignore
    return f"<{' '.join(ty.name for ty in self.types)}>"

@property
def arity(self) -> int:  # type: ignore
    return len(self.types)

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    len_type = len(self.types)
    len_value = len(value)

    if len_value != len_type:
        self.fail(
            ngettext(
                "{len_type} values are required, but {len_value} was given.",
                "{len_type} values are required, but {len_value} were given.",
                len_value,
            ).format(len_type=len_type, len_value=len_value),
            param=param,
            ctx=ctx,
        )

    return tuple(ty(x, param, ctx) for ty, x in zip(self.types, value))

def convert_type(ty: t.Optional[t.Any], default: t.Optional[t.Any] = None) -> ParamType:
    """Find the most appropriate :class:`ParamType` for the given Python
    type. If the type isn't provided, it can be inferred from a default
    value.
    """
    guessed_type = False

    if ty is None and default is not None:
        if isinstance(default, (tuple, list)):
            # If the default is empty, ty will remain None and will
            # return STRING.
            if default:
                item = default[0]

                # A tuple of tuples needs to detect the inner types.
                # Can't call convert recursively because that would
                # incorrectly unwind the tuple to a single type.
                if isinstance(item, (tuple, list)):
                    ty = tuple(map(type, item))
                else:
                    ty = type(item)
        else:
            ty = type(default)

        guessed_type = True

    if isinstance(ty, tuple):
        return Tuple(ty)

    if isinstance(ty, ParamType):
        return ty

    if ty is str or ty is None:
        return STRING

    if ty is int:
        return INT

    if ty is float:
        return FLOAT

    if ty is bool:
        return BOOL

    if guessed_type:
        return STRING

    if __debug__:
        try:
            if issubclass(ty, ParamType):
                raise AssertionError(
                    f"Attempted to use an uninstantiated parameter type ({ty})."
                )
        except TypeError:
            # ty is an instance (correct), so issubclass fails.
            pass

    return FuncParamType(ty)

def safecall(func: "t.Callable[P, R]") -> "t.Callable[P, t.Optional[R]]":
    """Wraps a function so that it swallows exceptions."""

    def wrapper(*args: "P.args", **kwargs: "P.kwargs") -> t.Optional[R]:
        try:
            return func(*args, **kwargs)
        except Exception:
            pass
        return None

    return update_wrapper(wrapper, func)

def wrapper(*args: "P.args", **kwargs: "P.kwargs") -> t.Optional[R]:
    try:
        return func(*args, **kwargs)
    except Exception:
        pass
    return None

def make_str(value: t.Any) -> str:
    """Converts a value into a valid string."""
    if isinstance(value, bytes):
        try:
            return value.decode(sys.getfilesystemencoding())
        except UnicodeError:
            return value.decode("utf-8", "replace")
    return str(value)

def __repr__(self) -> str:
    if self._f is not None:
        return repr(self._f)
    return f"<unopened file '{format_filename(self.name)}' {self.mode}>"

def open(self) -> t.IO[t.Any]:
    """Opens the file if it's not yet open.  This call might fail with
    a :exc:`FileError`.  Not handling this error will produce an error
    that Click shows.
    """
    if self._f is not None:
        return self._f
    try:
        rv, self.should_close = open_stream(
            self.name, self.mode, self.encoding, self.errors, atomic=self.atomic
        )
    except OSError as e:
        from .exceptions import FileError

        raise FileError(self.name, hint=e.strerror) from e
    self._f = rv
    return rv

def close(self) -> None:
    """Closes the underlying file, no matter what."""
    if self._f is not None:
        self._f.close()

def close_intelligently(self) -> None:
    """This function only closes the file if it was opened by the lazy
    file wrapper.  For instance this will never close stdin.
    """
    if self.should_close:
        self.close()

def __iter__(self) -> t.Iterator[t.AnyStr]:
    self.open()
    return iter(self._f)  # type: ignore

def get_binary_stream(name: "te.Literal['stdin', 'stdout', 'stderr']") -> t.BinaryIO:
    """Returns a system stream for byte processing.

    :param name: the name of the stream to open.  Valid names are ``'stdin'``,
                 ``'stdout'`` and ``'stderr'``
    """
    opener = binary_streams.get(name)
    if opener is None:
        raise TypeError(f"Unknown standard stream '{name}'")
    return opener()

def flush(self) -> None:
    try:
        self.wrapped.flush()
    except OSError as e:
        import errno

        if e.errno != errno.EPIPE:
            raise

def _lookup_exception_handler(exc_handlers: ExceptionHandlers, exc: Exception) -> ExceptionHandler | None:
    for cls in type(exc).__mro__:
        if cls in exc_handlers:
            return exc_handlers[cls]
    return None

def wrap_app_handling_exceptions(app: ASGIApp, conn: Request | WebSocket) -> ASGIApp:
    exception_handlers: ExceptionHandlers
    status_handlers: StatusHandlers
    try:
        exception_handlers, status_handlers = conn.scope["starlette.exception_handlers"]
    except KeyError:
        exception_handlers, status_handlers = {}, {}

    async def wrapped_app(scope: Scope, receive: Receive, send: Send) -> None:
        response_started = False

        async def sender(message: Message) -> None:
            nonlocal response_started

            if message["type"] == "http.response.start":
                response_started = True
            await send(message)

        try:
            await app(scope, receive, sender)
        except Exception as exc:
            handler = None

            if isinstance(exc, HTTPException):
                handler = status_handlers.get(exc.status_code)

            if handler is None:
                handler = _lookup_exception_handler(exception_handlers, exc)

            if handler is None:
                raise exc

            if response_started:
                raise RuntimeError("Caught handled exception, but response already started.") from exc

            if is_async_callable(handler):
                response = await handler(conn, exc)
            else:
                response = await run_in_threadpool(handler, conn, exc)  # type: ignore
            if response is not None:
                await response(scope, receive, sender)

    return wrapped_app

