def _user_safe_decode(src: bytes | bytearray, codec: str) -> str:
    try:
        return src.decode(codec)
    except (UnicodeDecodeError, LookupError):
        return src.decode("latin-1")

def on_field_start(self) -> None:
    message = (FormMessage.FIELD_START, b"")
    self.messages.append(message)

def on_field_name(self, data: bytes, start: int, end: int) -> None:
    message = (FormMessage.FIELD_NAME, data[start:end])
    self.messages.append(message)

def on_field_data(self, data: bytes, start: int, end: int) -> None:
    message = (FormMessage.FIELD_DATA, data[start:end])
    self.messages.append(message)

def on_field_end(self) -> None:
    message = (FormMessage.FIELD_END, b"")
    self.messages.append(message)

def on_end(self) -> None:
    message = (FormMessage.END, b"")
    self.messages.append(message)

def on_part_data(self, data: bytes, start: int, end: int) -> None:
    message_bytes = data[start:end]
    if self._current_part.file is None:
        if len(self._current_part.data) + len(message_bytes) > self.max_part_size:
            raise MultiPartException(f"Part exceeded maximum size of {int(self.max_part_size / 1024)}KB.")
        self._current_part.data.extend(message_bytes)
    else:
        self._file_parts_to_write.append((self._current_part, message_bytes))

def on_part_end(self) -> None:
    if self._current_part.file is None:
        self.items.append(
            (
                self._current_part.field_name,
                _user_safe_decode(self._current_part.data, self._charset),
            )
        )
    else:
        self._file_parts_to_finish.append(self._current_part)
        # The file can be added to the items right now even though it's not
        # finished yet, because it will be finished in the `parse()` method, before
        # self.items is used in the return value.
        self.items.append((self._current_part.field_name, self._current_part.file))

def on_headers_finished(self) -> None:
    disposition, options = parse_options_header(self._current_part.content_disposition)
    try:
        self._current_part.field_name = _user_safe_decode(options[b"name"], self._charset)
    except KeyError:
        raise MultiPartException('The Content-Disposition header field "name" must be provided.')
    if b"filename" in options:
        self._current_files += 1
        if self._current_files > self.max_files:
            raise MultiPartException(f"Too many files. Maximum number of files is {self.max_files}.")
        filename = _user_safe_decode(options[b"filename"], self._charset)
        tempfile = SpooledTemporaryFile(max_size=self.max_file_size)
        self._files_to_close_on_error.append(tempfile)
        self._current_part.file = UploadFile(
            file=tempfile,  # type: ignore[arg-type]
            size=0,
            filename=filename,
            headers=Headers(raw=self._current_part.item_headers),
        )
    else:
        self._current_fields += 1
        if self._current_fields > self.max_fields:
            raise MultiPartException(f"Too many fields. Maximum number of fields is {self.max_fields}.")
        self._current_part.file = None

def __iter__(self) -> Iterator[Any]:
    as_tuple = (self.cls, self.args, self.kwargs)
    return iter(as_tuple)

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] not in ["http", "websocket"]:
        await self.app(scope, receive, send)
        return

    conn = HTTPConnection(scope)
    try:
        auth_result = await self.backend.authenticate(conn)
    except AuthenticationError as exc:
        response = self.on_error(conn, exc)
        if scope["type"] == "websocket":
            await send({"type": "websocket.close", "code": 1000})
        else:
            await response(scope, receive, send)
        return

    if auth_result is None:
        auth_result = AuthCredentials(), UnauthenticatedUser()
    scope["auth"], scope["user"] = auth_result
    await self.app(scope, receive, send)

@staticmethod
def default_on_error(conn: HTTPConnection, exc: Exception) -> Response:
    return PlainTextResponse(str(exc), status_code=400)

def __init__(self, app: ASGIApp, dispatch: DispatchFunction | None = None) -> None:
    self.app = app
    self.dispatch_func = self.dispatch if dispatch is None else dispatch

async def receive_or_disconnect() -> Message:
    if response_sent.is_set():
        return {"type": "http.disconnect"}

    async with anyio.create_task_group() as task_group:

        async def wrap(func: typing.Callable[[], typing.Awaitable[T]]) -> T:
            result = await func()
            task_group.cancel_scope.cancel()
            return result

        task_group.start_soon(wrap, response_sent.wait)
        message = await wrap(wrapped_receive)

    if response_sent.is_set():
        return {"type": "http.disconnect"}

    return message

async def send_no_error(message: Message) -> None:
    try:
        await send_stream.send(message)
    except anyio.BrokenResourceError:
        # recv_stream has been closed, i.e. response_sent has been set.
        return

async def body_stream() -> typing.AsyncGenerator[bytes, None]:
    async for message in recv_stream:
        assert message["type"] == "http.response.body"
        body = message.get("body", b"")
        if body:
            yield body
        if not message.get("more_body", False):
            break

    if app_exc is not None:
        raise app_exc

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if self.info is not None:
        await send({"type": "http.response.debug", "info": self.info})
    await send(
        {
            "type": "http.response.start",
            "status": self.status_code,
            "headers": self.raw_headers,
        }
    )

    async for chunk in self.body_iterator:
        await send({"type": "http.response.body", "body": chunk, "more_body": True})

    await send({"type": "http.response.body", "body": b"", "more_body": False})

    if self.background:
        await self.background()

def __init__(
    self,
    app: ASGIApp,
    allow_origins: typing.Sequence[str] = (),
    allow_methods: typing.Sequence[str] = ("GET",),
    allow_headers: typing.Sequence[str] = (),
    allow_credentials: bool = False,
    allow_origin_regex: str | None = None,
    expose_headers: typing.Sequence[str] = (),
    max_age: int = 600,
) -> None:
    if "*" in allow_methods:
        allow_methods = ALL_METHODS

    compiled_allow_origin_regex = None
    if allow_origin_regex is not None:
        compiled_allow_origin_regex = re.compile(allow_origin_regex)

    allow_all_origins = "*" in allow_origins
    allow_all_headers = "*" in allow_headers
    preflight_explicit_allow_origin = not allow_all_origins or allow_credentials

    simple_headers = {}
    if allow_all_origins:
        simple_headers["Access-Control-Allow-Origin"] = "*"
    if allow_credentials:
        simple_headers["Access-Control-Allow-Credentials"] = "true"
    if expose_headers:
        simple_headers["Access-Control-Expose-Headers"] = ", ".join(expose_headers)

    preflight_headers = {}
    if preflight_explicit_allow_origin:
        # The origin value will be set in preflight_response() if it is allowed.
        preflight_headers["Vary"] = "Origin"
    else:
        preflight_headers["Access-Control-Allow-Origin"] = "*"
    preflight_headers.update(
        {
            "Access-Control-Allow-Methods": ", ".join(allow_methods),
            "Access-Control-Max-Age": str(max_age),
        }
    )
    allow_headers = sorted(SAFELISTED_HEADERS | set(allow_headers))
    if allow_headers and not allow_all_headers:
        preflight_headers["Access-Control-Allow-Headers"] = ", ".join(allow_headers)
    if allow_credentials:
        preflight_headers["Access-Control-Allow-Credentials"] = "true"

    self.app = app
    self.allow_origins = allow_origins
    self.allow_methods = allow_methods
    self.allow_headers = [h.lower() for h in allow_headers]
    self.allow_all_origins = allow_all_origins
    self.allow_all_headers = allow_all_headers
    self.preflight_explicit_allow_origin = preflight_explicit_allow_origin
    self.allow_origin_regex = compiled_allow_origin_regex
    self.simple_headers = simple_headers
    self.preflight_headers = preflight_headers

def is_allowed_origin(self, origin: str) -> bool:
    if self.allow_all_origins:
        return True

    if self.allow_origin_regex is not None and self.allow_origin_regex.fullmatch(origin):
        return True

    return origin in self.allow_origins

def preflight_response(self, request_headers: Headers) -> Response:
    requested_origin = request_headers["origin"]
    requested_method = request_headers["access-control-request-method"]
    requested_headers = request_headers.get("access-control-request-headers")

    headers = dict(self.preflight_headers)
    failures = []

    if self.is_allowed_origin(origin=requested_origin):
        if self.preflight_explicit_allow_origin:
            # The "else" case is already accounted for in self.preflight_headers
            # and the value would be "*".
            headers["Access-Control-Allow-Origin"] = requested_origin
    else:
        failures.append("origin")

    if requested_method not in self.allow_methods:
        failures.append("method")

    # If we allow all headers, then we have to mirror back any requested
    # headers in the response.
    if self.allow_all_headers and requested_headers is not None:
        headers["Access-Control-Allow-Headers"] = requested_headers
    elif requested_headers is not None:
        for header in [h.lower() for h in requested_headers.split(",")]:
            if header.strip() not in self.allow_headers:
                failures.append("headers")
                break

    # We don't strictly need to use 400 responses here, since its up to
    # the browser to enforce the CORS policy, but its more informative
    # if we do.
    if failures:
        failure_text = "Disallowed CORS " + ", ".join(failures)
        return PlainTextResponse(failure_text, status_code=400, headers=headers)

    return PlainTextResponse("OK", status_code=200, headers=headers)

@staticmethod
def allow_explicit_origin(headers: MutableHeaders, origin: str) -> None:
    headers["Access-Control-Allow-Origin"] = origin
    headers.add_vary_header("Origin")

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http":
        await self.app(scope, receive, send)
        return

    response_started = False

    async def _send(message: Message) -> None:
        nonlocal response_started, send

        if message["type"] == "http.response.start":
            response_started = True
        await send(message)

    try:
        await self.app(scope, receive, _send)
    except Exception as exc:
        request = Request(scope)
        if self.debug:
            # In debug mode, return traceback responses.
            response = self.debug_response(request, exc)
        elif self.handler is None:
            # Use our default 500 error handler.
            response = self.error_response(request, exc)
        else:
            # Use an installed 500 error handler.
            if is_async_callable(self.handler):
                response = await self.handler(request, exc)
            else:
                response = await run_in_threadpool(self.handler, request, exc)

        if not response_started:
            await response(scope, receive, send)

        # We always continue to raise the exception.
        # This allows servers to log the error, or allows test clients
        # to optionally raise the error within the test case.
        raise exc

def format_line(self, index: int, line: str, frame_lineno: int, frame_index: int) -> str:
    values = {
        # HTML escape - line could contain < or >
        "line": html.escape(line).replace(" ", "&nbsp"),
        "lineno": (frame_lineno - frame_index) + index,
    }

    if index != frame_index:
        return LINE.format(**values)
    return CENTER_LINE.format(**values)

def generate_frame_html(self, frame: inspect.FrameInfo, is_collapsed: bool) -> str:
    code_context = "".join(
        self.format_line(
            index,
            line,
            frame.lineno,
            frame.index,  # type: ignore[arg-type]
        )
        for index, line in enumerate(frame.code_context or [])
    )

    values = {
        # HTML escape - filename could contain < or >, especially if it's a virtual
        # file e.g. <stdin> in the REPL
        "frame_filename": html.escape(frame.filename),
        "frame_lineno": frame.lineno,
        # HTML escape - if you try very hard it's possible to name a function with <
        # or >
        "frame_name": html.escape(frame.function),
        "code_context": code_context,
        "collapsed": "collapsed" if is_collapsed else "",
        "collapse_button": "+" if is_collapsed else "&#8210;",
    }
    return FRAME_TEMPLATE.format(**values)

def debug_response(self, request: Request, exc: Exception) -> Response:
    accept = request.headers.get("accept", "")

    if "text/html" in accept:
        content = self.generate_html(exc)
        return HTMLResponse(content, status_code=500)
    content = self.generate_plain_text(exc)
    return PlainTextResponse(content, status_code=500)

def __init__(
    self,
    app: ASGIApp,
    handlers: typing.Mapping[typing.Any, typing.Callable[[Request, Exception], Response]] | None = None,
    debug: bool = False,
) -> None:
    self.app = app
    self.debug = debug  # TODO: We ought to handle 404 cases if debug is set.
    self._status_handlers: StatusHandlers = {}
    self._exception_handlers: ExceptionHandlers = {
        HTTPException: self.http_exception,
        WebSocketException: self.websocket_exception,
    }
    if handlers is not None:  # pragma: no branch
        for key, value in handlers.items():
            self.add_exception_handler(key, value)

def add_exception_handler(
    self,
    exc_class_or_status_code: int | type[Exception],
    handler: typing.Callable[[Request, Exception], Response],
) -> None:
    if isinstance(exc_class_or_status_code, int):
        self._status_handlers[exc_class_or_status_code] = handler
    else:
        assert issubclass(exc_class_or_status_code, Exception)
        self._exception_handlers[exc_class_or_status_code] = handler

def http_exception(self, request: Request, exc: Exception) -> Response:
    assert isinstance(exc, HTTPException)
    if exc.status_code in {204, 304}:
        return Response(status_code=exc.status_code, headers=exc.headers)
    return PlainTextResponse(exc.detail, status_code=exc.status_code, headers=exc.headers)

def __init__(
    self,
    app: ASGIApp,
    allowed_hosts: typing.Sequence[str] | None = None,
    www_redirect: bool = True,
) -> None:
    if allowed_hosts is None:
        allowed_hosts = ["*"]

    for pattern in allowed_hosts:
        assert "*" not in pattern[1:], ENFORCE_DOMAIN_WILDCARD
        if pattern.startswith("*") and pattern != "*":
            assert pattern.startswith("*."), ENFORCE_DOMAIN_WILDCARD
    self.app = app
    self.allowed_hosts = list(allowed_hosts)
    self.allow_any = "*" in allowed_hosts
    self.www_redirect = www_redirect

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if self.allow_any or scope["type"] not in (
        "http",
        "websocket",
    ):  # pragma: no cover
        await self.app(scope, receive, send)
        return

    headers = Headers(scope=scope)
    host = headers.get("host", "").split(":")[0]
    is_valid_host = False
    found_www_redirect = False
    for pattern in self.allowed_hosts:
        if host == pattern or (pattern.startswith("*") and host.endswith(pattern[1:])):
            is_valid_host = True
            break
        elif "www." + host == pattern:
            found_www_redirect = True

    if is_valid_host:
        await self.app(scope, receive, send)
    else:
        response: Response
        if found_www_redirect and self.www_redirect:
            url = URL(scope=scope)
            redirect_url = url.replace(netloc="www." + url.netloc)
            response = RedirectResponse(url=str(redirect_url))
        else:
            response = PlainTextResponse("Invalid host header", status_code=400)
        await response(scope, receive, send)

def wsgi(
    self,
    environ: dict[str, typing.Any],
    start_response: typing.Callable[..., typing.Any],
) -> None:
    for chunk in self.app(environ, start_response):
        anyio.from_thread.run(
            self.stream_send.send,
            {"type": "http.response.body", "body": chunk, "more_body": True},
        )

    anyio.from_thread.run(self.stream_send.send, {"type": "http.response.body", "body": b""})

def __init__(self, scope: Scope, receive: Receive | None = None) -> None:
    assert scope["type"] in ("http", "websocket")
    self.scope = scope

@property
def app(self) -> typing.Any:
    return self.scope["app"]

@property
def url(self) -> URL:
    if not hasattr(self, "_url"):  # pragma: no branch
        self._url = URL(scope=self.scope)
    return self._url

@property
def headers(self) -> Headers:
    if not hasattr(self, "_headers"):
        self._headers = Headers(scope=self.scope)
    return self._headers

@property
def query_params(self) -> QueryParams:
    if not hasattr(self, "_query_params"):  # pragma: no branch
        self._query_params = QueryParams(self.scope["query_string"])
    return self._query_params

@property
def path_params(self) -> dict[str, typing.Any]:
    return self.scope.get("path_params", {})

@property
def cookies(self) -> dict[str, str]:
    if not hasattr(self, "_cookies"):
        cookies: dict[str, str] = {}
        cookie_header = self.headers.get("cookie")

        if cookie_header:
            cookies = cookie_parser(cookie_header)
        self._cookies = cookies
    return self._cookies

@property
def client(self) -> Address | None:
    # client is a 2 item tuple of (host, port), None if missing
    host_port = self.scope.get("client")
    if host_port is not None:
        return Address(*host_port)
    return None

@property
def session(self) -> dict[str, typing.Any]:
    assert "session" in self.scope, "SessionMiddleware must be installed to access request.session"
    return self.scope["session"]  # type: ignore[no-any-return]

@property
def auth(self) -> typing.Any:
    assert "auth" in self.scope, "AuthenticationMiddleware must be installed to access request.auth"
    return self.scope["auth"]

@property
def user(self) -> typing.Any:
    assert "user" in self.scope, "AuthenticationMiddleware must be installed to access request.user"
    return self.scope["user"]

@property
def state(self) -> State:
    if not hasattr(self, "_state"):
        # Ensure 'state' has an empty dict if it's not already populated.
        self.scope.setdefault("state", {})
        # Create a state instance with a reference to the dict in which it should
        # store info
        self._state = State(self.scope["state"])
    return self._state

def url_for(self, name: str, /, **path_params: typing.Any) -> URL:
    url_path_provider: Router | Starlette | None = self.scope.get("router") or self.scope.get("app")
    if url_path_provider is None:
        raise RuntimeError("The `url_for` method can only be used inside a Starlette application or with a router.")
    url_path = url_path_provider.url_path_for(name, **path_params)
    return url_path.make_absolute_url(base_url=self.base_url)

@property
def method(self) -> str:
    return typing.cast(str, self.scope["method"])

@property
def receive(self) -> Receive:
    return self._receive

async def stream(self) -> typing.AsyncGenerator[bytes, None]:
    if hasattr(self, "_body"):
        yield self._body
        yield b""
        return
    if self._stream_consumed:
        raise RuntimeError("Stream consumed")
    while not self._stream_consumed:
        message = await self._receive()
        if message["type"] == "http.request":
            body = message.get("body", b"")
            if not message.get("more_body", False):
                self._stream_consumed = True
            if body:
                yield body
        elif message["type"] == "http.disconnect":  # pragma: no branch
            self._is_disconnected = True
            raise ClientDisconnect()
    yield b""

def form(
    self,
    *,
    max_files: int | float = 1000,
    max_fields: int | float = 1000,
    max_part_size: int = 1024 * 1024,
) -> AwaitableOrContextManager[FormData]:
    return AwaitableOrContextManagerWrapper(
        self._get_form(max_files=max_files, max_fields=max_fields, max_part_size=max_part_size)
    )

async def is_disconnected(self) -> bool:
    if not self._is_disconnected:
        message: Message = {}

        # If message isn't immediately available, move on
        with anyio.CancelScope() as cs:
            cs.cancel()
            message = await self._receive()

        if message.get("type") == "http.disconnect":
            self._is_disconnected = True

    return self._is_disconnected

async def send_push_promise(self, path: str) -> None:
    if "http.response.push" in self.scope.get("extensions", {}):
        raw_headers: list[tuple[bytes, bytes]] = []
        for name in SERVER_PUSH_HEADERS_TO_COPY:
            for value in self.headers.getlist(name):
                raw_headers.append((name.encode("latin-1"), value.encode("latin-1")))
        await self._send({"type": "http.response.push", "path": path, "headers": raw_headers})

def render(self, content: typing.Any) -> bytes | memoryview:
    if content is None:
        return b""
    if isinstance(content, (bytes, memoryview)):
        return content
    return content.encode(self.charset)  # type: ignore

@property
def headers(self) -> MutableHeaders:
    if not hasattr(self, "_headers"):
        self._headers = MutableHeaders(raw=self.raw_headers)
    return self._headers

def set_cookie(
    self,
    key: str,
    value: str = "",
    max_age: int | None = None,
    expires: datetime | str | int | None = None,
    path: str | None = "/",
    domain: str | None = None,
    secure: bool = False,
    httponly: bool = False,
    samesite: typing.Literal["lax", "strict", "none"] | None = "lax",
) -> None:
    cookie: http.cookies.BaseCookie[str] = http.cookies.SimpleCookie()
    cookie[key] = value
    if max_age is not None:
        cookie[key]["max-age"] = max_age
    if expires is not None:
        if isinstance(expires, datetime):
            cookie[key]["expires"] = format_datetime(expires, usegmt=True)
        else:
            cookie[key]["expires"] = expires
    if path is not None:
        cookie[key]["path"] = path
    if domain is not None:
        cookie[key]["domain"] = domain
    if secure:
        cookie[key]["secure"] = True
    if httponly:
        cookie[key]["httponly"] = True
    if samesite is not None:
        assert samesite.lower() in [
            "strict",
            "lax",
            "none",
        ], "samesite must be either 'strict', 'lax' or 'none'"
        cookie[key]["samesite"] = samesite
    cookie_val = cookie.output(header="").strip()
    self.raw_headers.append((b"set-cookie", cookie_val.encode("latin-1")))

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    prefix = "websocket." if scope["type"] == "websocket" else ""
    await send(
        {
            "type": prefix + "http.response.start",
            "status": self.status_code,
            "headers": self.raw_headers,
        }
    )
    await send({"type": prefix + "http.response.body", "body": self.body})

    if self.background is not None:
        await self.background()

def render(self, content: typing.Any) -> bytes:
    return json.dumps(
        content,
        ensure_ascii=False,
        allow_nan=False,
        indent=None,
        separators=(",", ":"),
    ).encode("utf-8")

async def listen_for_disconnect(self, receive: Receive) -> None:
    while True:
        message = await receive()
        if message["type"] == "http.disconnect":
            break

async def stream_response(self, send: Send) -> None:
    await send(
        {
            "type": "http.response.start",
            "status": self.status_code,
            "headers": self.raw_headers,
        }
    )
    async for chunk in self.body_iterator:
        if not isinstance(chunk, (bytes, memoryview)):
            chunk = chunk.encode(self.charset)
        await send({"type": "http.response.body", "body": chunk, "more_body": True})

    await send({"type": "http.response.body", "body": b"", "more_body": False})

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    spec_version = tuple(map(int, scope.get("asgi", {}).get("spec_version", "2.0").split(".")))

    if spec_version >= (2, 4):
        try:
            await self.stream_response(send)
        except OSError:
            raise ClientDisconnect()
    else:
        async with anyio.create_task_group() as task_group:

            async def wrap(func: typing.Callable[[], typing.Awaitable[None]]) -> None:
                await func()
                task_group.cancel_scope.cancel()

            task_group.start_soon(wrap, partial(self.stream_response, send))
            await wrap(partial(self.listen_for_disconnect, receive))

    if self.background is not None:
        await self.background()

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    send_header_only: bool = scope["method"].upper() == "HEAD"
    if self.stat_result is None:
        try:
            stat_result = await anyio.to_thread.run_sync(os.stat, self.path)
            self.set_stat_headers(stat_result)
        except FileNotFoundError:
            raise RuntimeError(f"File at path {self.path} does not exist.")
        else:
            mode = stat_result.st_mode
            if not stat.S_ISREG(mode):
                raise RuntimeError(f"File at path {self.path} is not a file.")
    else:
        stat_result = self.stat_result

    headers = Headers(scope=scope)
    http_range = headers.get("range")
    http_if_range = headers.get("if-range")

    if http_range is None or (http_if_range is not None and not self._should_use_range(http_if_range)):
        await self._handle_simple(send, send_header_only)
    else:
        try:
            ranges = self._parse_range_header(http_range, stat_result.st_size)
        except MalformedRangeHeader as exc:
            return await PlainTextResponse(exc.content, status_code=400)(scope, receive, send)
        except RangeNotSatisfiable as exc:
            response = PlainTextResponse(status_code=416, headers={"Content-Range": f"*/{exc.max_size}"})
            return await response(scope, receive, send)

        if len(ranges) == 1:
            start, end = ranges[0]
            await self._handle_single_range(send, start, end, stat_result.st_size, send_header_only)
        else:
            await self._handle_multiple_ranges(send, ranges, stat_result.st_size, send_header_only)

    if self.background is not None:
        await self.background()

@staticmethod
def _parse_range_header(http_range: str, file_size: int) -> list[tuple[int, int]]:
    ranges: list[tuple[int, int]] = []
    try:
        units, range_ = http_range.split("=", 1)
    except ValueError:
        raise MalformedRangeHeader()

    units = units.strip().lower()

    if units != "bytes":
        raise MalformedRangeHeader("Only support bytes range")

    ranges = [
        (
            int(_[0]) if _[0] else file_size - int(_[1]),
            int(_[1]) + 1 if _[0] and _[1] and int(_[1]) < file_size else file_size,
        )
        for _ in _RANGE_PATTERN.findall(range_)
        if _ != ("", "")
    ]

    if len(ranges) == 0:
        raise MalformedRangeHeader("Range header: range must be requested")

    if any(not (0 <= start < file_size) for start, _ in ranges):
        raise RangeNotSatisfiable(file_size)

    if any(start > end for start, end in ranges):
        raise MalformedRangeHeader("Range header: start must be less than end")

    if len(ranges) == 1:
        return ranges

    # Merge ranges
    result: list[tuple[int, int]] = []
    for start, end in ranges:
        for p in range(len(result)):
            p_start, p_end = result[p]
            if start > p_end:
                continue
            elif end < p_start:
                result.insert(p, (start, end))  # THIS IS NOT REACHED!
                break
            else:
                result[p] = (min(start, p_start), max(end, p_end))
                break
        else:
            result.append((start, end))

    return result

def __init__(self, name: str, path_params: dict[str, typing.Any]) -> None:
    params = ", ".join(list(path_params.keys()))
    super().__init__(f'No route exists for name "{name}" and params "{params}".')

def replace_params(
    path: str,
    param_convertors: dict[str, Convertor[typing.Any]],
    path_params: dict[str, str],
) -> tuple[str, dict[str, str]]:
    for key, value in list(path_params.items()):
        if "{" + key + "}" in path:
            convertor = param_convertors[key]
            value = convertor.to_string(value)
            path = path.replace("{" + key + "}", value)
            path_params.pop(key)
    return path, path_params

def __init__(
    self,
    path: str,
    endpoint: typing.Callable[..., typing.Any],
    *,
    methods: list[str] | None = None,
    name: str | None = None,
    include_in_schema: bool = True,
    middleware: typing.Sequence[Middleware] | None = None,
) -> None:
    assert path.startswith("/"), "Routed paths must start with '/'"
    self.path = path
    self.endpoint = endpoint
    self.name = get_name(endpoint) if name is None else name
    self.include_in_schema = include_in_schema

    endpoint_handler = endpoint
    while isinstance(endpoint_handler, functools.partial):
        endpoint_handler = endpoint_handler.func
    if inspect.isfunction(endpoint_handler) or inspect.ismethod(endpoint_handler):
        # Endpoint is function or method. Treat it as `func(request) -> response`.
        self.app = request_response(endpoint)
        if methods is None:
            methods = ["GET"]
    else:
        # Endpoint is a class. Treat it as ASGI.
        self.app = endpoint

    if middleware is not None:
        for cls, args, kwargs in reversed(middleware):
            self.app = cls(self.app, *args, **kwargs)

    if methods is None:
        self.methods = None
    else:
        self.methods = {method.upper() for method in methods}
        if "GET" in self.methods:
            self.methods.add("HEAD")

    self.path_regex, self.path_format, self.param_convertors = compile_path(path)

def matches(self, scope: Scope) -> tuple[Match, Scope]:
    path_params: dict[str, typing.Any]
    if scope["type"] == "http":
        route_path = get_route_path(scope)
        match = self.path_regex.match(route_path)
        if match:
            matched_params = match.groupdict()
            for key, value in matched_params.items():
                matched_params[key] = self.param_convertors[key].convert(value)
            path_params = dict(scope.get("path_params", {}))
            path_params.update(matched_params)
            child_scope = {"endpoint": self.endpoint, "path_params": path_params}
            if self.methods and scope["method"] not in self.methods:
                return Match.PARTIAL, child_scope
            else:
                return Match.FULL, child_scope
    return Match.NONE, {}

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())

    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)

    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="http")

async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
    if self.methods and scope["method"] not in self.methods:
        headers = {"Allow": ", ".join(self.methods)}
        if "app" in scope:
            raise HTTPException(status_code=405, headers=headers)
        else:
            response = PlainTextResponse("Method Not Allowed", status_code=405, headers=headers)
        await response(scope, receive, send)
    else:
        await self.app(scope, receive, send)

def __eq__(self, other: typing.Any) -> bool:
    return (
        isinstance(other, Route)
        and self.path == other.path
        and self.endpoint == other.endpoint
        and self.methods == other.methods
    )

def matches(self, scope: Scope) -> tuple[Match, Scope]:
    path_params: dict[str, typing.Any]
    if scope["type"] == "websocket":
        route_path = get_route_path(scope)
        match = self.path_regex.match(route_path)
        if match:
            matched_params = match.groupdict()
            for key, value in matched_params.items():
                matched_params[key] = self.param_convertors[key].convert(value)
            path_params = dict(scope.get("path_params", {}))
            path_params.update(matched_params)
            child_scope = {"endpoint": self.endpoint, "path_params": path_params}
            return Match.FULL, child_scope
    return Match.NONE, {}

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())

    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)

    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="websocket")

@property
def routes(self) -> list[BaseRoute]:
    return getattr(self._base_app, "routes", [])

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    if self.name is not None and name == self.name and "path" in path_params:
        # 'name' matches "<mount_name>".
        path_params["path"] = path_params["path"].lstrip("/")
        path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
        if not remaining_params:
            return URLPath(path=path)
    elif self.name is None or name.startswith(self.name + ":"):
        if self.name is None:
            # No mount name.
            remaining_name = name
        else:
            # 'name' matches "<mount_name>:<child_name>".
            remaining_name = name[len(self.name) + 1 :]
        path_kwarg = path_params.get("path")
        path_params["path"] = ""
        path_prefix, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
        if path_kwarg is not None:
            remaining_params["path"] = path_kwarg
        for route in self.routes or []:
            try:
                url = route.url_path_for(remaining_name, **remaining_params)
                return URLPath(path=path_prefix.rstrip("/") + str(url), protocol=url.protocol)
            except NoMatchFound:
                pass
    raise NoMatchFound(name, path_params)

@property
def routes(self) -> list[BaseRoute]:
    return getattr(self.app, "routes", [])

def matches(self, scope: Scope) -> tuple[Match, Scope]:
    if scope["type"] in ("http", "websocket"):  # pragma:no branch
        headers = Headers(scope=scope)
        host = headers.get("host", "").split(":")[0]
        match = self.host_regex.match(host)
        if match:
            matched_params = match.groupdict()
            for key, value in matched_params.items():
                matched_params[key] = self.param_convertors[key].convert(value)
            path_params = dict(scope.get("path_params", {}))
            path_params.update(matched_params)
            child_scope = {"path_params": path_params, "endpoint": self.app}
            return Match.FULL, child_scope
    return Match.NONE, {}

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    if self.name is not None and name == self.name and "path" in path_params:
        # 'name' matches "<mount_name>".
        path = path_params.pop("path")
        host, remaining_params = replace_params(self.host_format, self.param_convertors, path_params)
        if not remaining_params:
            return URLPath(path=path, host=host)
    elif self.name is None or name.startswith(self.name + ":"):
        if self.name is None:
            # No mount name.
            remaining_name = name
        else:
            # 'name' matches "<mount_name>:<child_name>".
            remaining_name = name[len(self.name) + 1 :]
        host, remaining_params = replace_params(self.host_format, self.param_convertors, path_params)
        for route in self.routes or []:
            try:
                url = route.url_path_for(remaining_name, **remaining_params)
                return URLPath(path=str(url), protocol=url.protocol, host=host)
            except NoMatchFound:
                pass
    raise NoMatchFound(name, path_params)

def _wrap_gen_lifespan_context(
    lifespan_context: typing.Callable[[typing.Any], typing.Generator[typing.Any, typing.Any, typing.Any]],
) -> typing.Callable[[typing.Any], typing.AsyncContextManager[typing.Any]]:
    cmgr = contextlib.contextmanager(lifespan_context)

    @functools.wraps(cmgr)
    def wrapper(app: typing.Any) -> _AsyncLiftContextManager[typing.Any]:
        return _AsyncLiftContextManager(cmgr(app))

    return wrapper

@functools.wraps(cmgr)
def wrapper(app: typing.Any) -> _AsyncLiftContextManager[typing.Any]:
    return _AsyncLiftContextManager(cmgr(app))

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    for route in self.routes:
        try:
            return route.url_path_for(name, **path_params)
        except NoMatchFound:
            pass
    raise NoMatchFound(name, path_params)

async def startup(self) -> None:
    """
    Run any `.on_startup` event handlers.
    """
    for handler in self.on_startup:
        if is_async_callable(handler):
            await handler()
        else:
            handler()

async def shutdown(self) -> None:
    """
    Run any `.on_shutdown` event handlers.
    """
    for handler in self.on_shutdown:
        if is_async_callable(handler):
            await handler()
        else:
            handler()

def add_event_handler(self, event_type: str, func: typing.Callable[[], typing.Any]) -> None:  # pragma: no cover
    assert event_type in ("startup", "shutdown")

    if event_type == "startup":
        self.on_startup.append(func)
    else:
        self.on_shutdown.append(func)

def render(self, content: typing.Any) -> bytes:
    assert yaml is not None, "`pyyaml` must be installed to use OpenAPIResponse."
    assert isinstance(content, dict), "The schema passed to OpenAPIResponse should be a dictionary."
    return yaml.dump(content, default_flow_style=False).encode("utf-8")

def get_endpoints(self, routes: list[BaseRoute]) -> list[EndpointInfo]:
    """
    Given the routes, yields the following information:

    - path
        eg: /users/
    - http_method
        one of 'get', 'post', 'put', 'patch', 'delete', 'options'
    - func
        method ready to extract the docstring
    """
    endpoints_info: list[EndpointInfo] = []

    for route in routes:
        if isinstance(route, (Mount, Host)):
            routes = route.routes or []
            if isinstance(route, Mount):
                path = self._remove_converter(route.path)
            else:
                path = ""
            sub_endpoints = [
                EndpointInfo(
                    path="".join((path, sub_endpoint.path)),
                    http_method=sub_endpoint.http_method,
                    func=sub_endpoint.func,
                )
                for sub_endpoint in self.get_endpoints(routes)
            ]
            endpoints_info.extend(sub_endpoints)

        elif not isinstance(route, Route) or not route.include_in_schema:
            continue

        elif inspect.isfunction(route.endpoint) or inspect.ismethod(route.endpoint):
            path = self._remove_converter(route.path)
            for method in route.methods or ["GET"]:
                if method == "HEAD":
                    continue
                endpoints_info.append(EndpointInfo(path, method.lower(), route.endpoint))
        else:
            path = self._remove_converter(route.path)
            for method in ["get", "post", "put", "patch", "delete", "options"]:
                if not hasattr(route.endpoint, method):
                    continue
                func = getattr(route.endpoint, method)
                endpoints_info.append(EndpointInfo(path, method.lower(), func))

    return endpoints_info

def OpenAPIResponse(self, request: Request) -> Response:
    routes = request.app.routes
    schema = self.get_schema(routes=routes)
    return OpenAPIResponse(schema)

def get_schema(self, routes: list[BaseRoute]) -> dict[str, typing.Any]:
    schema = dict(self.base_schema)
    schema.setdefault("paths", {})
    endpoints_info = self.get_endpoints(routes)

    for endpoint in endpoints_info:
        parsed = self.parse_docstring(endpoint.func)

        if not parsed:
            continue

        if endpoint.path not in schema["paths"]:
            schema["paths"][endpoint.path] = {}

        schema["paths"][endpoint.path][endpoint.http_method] = parsed

    return schema

def __init__(self, headers: Headers):
    super().__init__(
        status_code=304,
        headers={name: value for name, value in headers.items() if name in self.NOT_MODIFIED_HEADERS},
    )

async def get_response(self, path: str, scope: Scope) -> Response:
    """
    Returns an HTTP response, given the incoming path, method and request headers.
    """
    if scope["method"] not in ("GET", "HEAD"):
        raise HTTPException(status_code=405)

    try:
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, path)
    except PermissionError:
        raise HTTPException(status_code=401)
    except OSError as exc:
        # Filename is too long, so it can't be a valid static file.
        if exc.errno == errno.ENAMETOOLONG:
            raise HTTPException(status_code=404)

        raise exc

    if stat_result and stat.S_ISREG(stat_result.st_mode):
        # We have a static file to serve.
        return self.file_response(full_path, stat_result, scope)

    elif stat_result and stat.S_ISDIR(stat_result.st_mode) and self.html:
        # We're in HTML mode, and have got a directory URL.
        # Check if we have 'index.html' file to serve.
        index_path = os.path.join(path, "index.html")
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, index_path)
        if stat_result is not None and stat.S_ISREG(stat_result.st_mode):
            if not scope["path"].endswith("/"):
                # Directory URLs should redirect to always end in "/".
                url = URL(scope=scope)
                url = url.replace(path=url.path + "/")
                return RedirectResponse(url=url)
            return self.file_response(full_path, stat_result, scope)

    if self.html:
        # Check for '404.html' if we're in HTML mode.
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, "404.html")
        if stat_result and stat.S_ISREG(stat_result.st_mode):
            return FileResponse(full_path, stat_result=stat_result, status_code=404)
    raise HTTPException(status_code=404)

def lookup_path(self, path: str) -> tuple[str, os.stat_result | None]:
    for directory in self.all_directories:
        joined_path = os.path.join(directory, path)
        if self.follow_symlink:
            full_path = os.path.abspath(joined_path)
        else:
            full_path = os.path.realpath(joined_path)
            directory = os.path.realpath(directory)
        if os.path.commonpath([full_path, directory]) != str(directory):
            # Don't allow misbehaving clients to break out of the static files directory.
            continue
        try:
            return full_path, os.stat(full_path)
        except (FileNotFoundError, NotADirectoryError):
            continue
    return "", None

def file_response(
    self,
    full_path: PathLike,
    stat_result: os.stat_result,
    scope: Scope,
    status_code: int = 200,
) -> Response:
    request_headers = Headers(scope=scope)

    response = FileResponse(full_path, status_code=status_code, stat_result=stat_result)
    if self.is_not_modified(response.headers, request_headers):
        return NotModifiedResponse(response.headers)
    return response

def is_not_modified(self, response_headers: Headers, request_headers: Headers) -> bool:
    """
    Given the request and response headers, return `True` if an HTTP
    "Not Modified" response could be returned instead.
    """
    try:
        if_none_match = request_headers["if-none-match"]
        etag = response_headers["etag"]
        if etag in [tag.strip(" W/") for tag in if_none_match.split(",")]:
            return True
    except KeyError:
        pass

    try:
        if_modified_since = parsedate(request_headers["if-modified-since"])
        last_modified = parsedate(response_headers["last-modified"])
        if if_modified_since is not None and last_modified is not None and if_modified_since >= last_modified:
            return True
    except KeyError:
        pass

    return False

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    request = self.context.get("request", {})
    extensions = request.get("extensions", {})
    if "http.response.debug" in extensions:  # pragma: no branch
        await send(
            {
                "type": "http.response.debug",
                "info": {
                    "template": self.template,
                    "context": self.context,
                },
            }
        )
    await super().__call__(scope, receive, send)

def _create_env(
    self,
    directory: str | PathLike[str] | typing.Sequence[str | PathLike[str]],
    **env_options: typing.Any,
) -> jinja2.Environment:
    loader = jinja2.FileSystemLoader(directory)
    env_options.setdefault("loader", loader)
    env_options.setdefault("autoescape", True)

    return jinja2.Environment(**env_options)

def _setup_env_defaults(self, env: jinja2.Environment) -> None:
    @pass_context
    def url_for(
        context: dict[str, typing.Any],
        name: str,
        /,
        **path_params: typing.Any,
    ) -> URL:
        request: Request = context["request"]
        return request.url_for(name, **path_params)

    env.globals.setdefault("url_for", url_for)

@pass_context
def url_for(
    context: dict[str, typing.Any],
    name: str,
    /,
    **path_params: typing.Any,
) -> URL:
    request: Request = context["request"]
    return request.url_for(name, **path_params)

def _is_asgi3(app: ASGI2App | ASGI3App) -> TypeGuard[ASGI3App]:
    if inspect.isclass(app):
        return hasattr(app, "__await__")
    return is_async_callable(app)

def _raise_on_close(self, message: Message) -> None:
    if message["type"] == "websocket.close":
        raise WebSocketDisconnect(code=message.get("code", 1000), reason=message.get("reason", ""))
    elif message["type"] == "websocket.http.response.start":
        status_code: int = message["status"]
        headers: list[tuple[bytes, bytes]] = message["headers"]
        body: list[bytes] = []
        while True:
            message = self.receive()
            assert message["type"] == "websocket.http.response.body"
            body.append(message["body"])
            if not message.get("more_body", False):
                break
        raise WebSocketDenialResponse(status_code=status_code, headers=headers, content=b"".join(body))

def send_json(self, data: typing.Any, mode: typing.Literal["text", "binary"] = "text") -> None:
    text = json.dumps(data, separators=(",", ":"), ensure_ascii=False)
    if mode == "text":
        self.send({"type": "websocket.receive", "text": text})
    else:
        self.send({"type": "websocket.receive", "bytes": text.encode("utf-8")})

def receive_text(self) -> str:
    message = self.receive()
    self._raise_on_close(message)
    return typing.cast(str, message["text"])

def receive_bytes(self) -> bytes:
    message = self.receive()
    self._raise_on_close(message)
    return typing.cast(bytes, message["bytes"])

def receive_json(self, mode: typing.Literal["text", "binary"] = "text") -> typing.Any:
    message = self.receive()
    self._raise_on_close(message)
    if mode == "text":
        text = message["text"]
    else:
        text = message["bytes"].decode("utf-8")
    return json.loads(text)

async def receive() -> Message:
    nonlocal request_complete

    if request_complete:
        if not response_complete.is_set():
            await response_complete.wait()
        return {"type": "http.disconnect"}

    body = request.read()
    if isinstance(body, str):
        body_bytes: bytes = body.encode("utf-8")  # pragma: no cover
    elif body is None:
        body_bytes = b""  # pragma: no cover
    elif isinstance(body, GeneratorType):
        try:  # pragma: no cover
            chunk = body.send(None)
            if isinstance(chunk, str):
                chunk = chunk.encode("utf-8")
            return {"type": "http.request", "body": chunk, "more_body": True}
        except StopIteration:  # pragma: no cover
            request_complete = True
            return {"type": "http.request", "body": b""}
    else:
        body_bytes = body

    request_complete = True
    return {"type": "http.request", "body": body_bytes}

@contextlib.contextmanager
def _portal_factory(self) -> typing.Generator[anyio.abc.BlockingPortal, None, None]:
    if self.portal is not None:
        yield self.portal
    else:
        with anyio.from_thread.start_blocking_portal(**self.async_backend) as portal:
            yield portal

def __enter__(self) -> TestClient:
    with contextlib.ExitStack() as stack:
        self.portal = portal = stack.enter_context(anyio.from_thread.start_blocking_portal(**self.async_backend))

        @stack.callback
        def reset_portal() -> None:
            self.portal = None

        send: anyio.create_memory_object_stream[typing.MutableMapping[str, typing.Any] | None] = (
            anyio.create_memory_object_stream(math.inf)
        )
        receive: anyio.create_memory_object_stream[typing.MutableMapping[str, typing.Any]] = (
            anyio.create_memory_object_stream(math.inf)
        )
        for channel in (*send, *receive):
            stack.callback(channel.close)
        self.stream_send = StapledObjectStream(*send)
        self.stream_receive = StapledObjectStream(*receive)
        self.task = portal.start_task_soon(self.lifespan)
        portal.call(self.wait_startup)

        @stack.callback
        def wait_shutdown() -> None:
            portal.call(self.wait_shutdown)

        self.exit_stack = stack.pop_all()

    return self

@stack.callback
def reset_portal() -> None:
    self.portal = None

@stack.callback
def wait_shutdown() -> None:
    portal.call(self.wait_shutdown)

async def lifespan(self) -> None:
    scope = {"type": "lifespan", "state": self.app_state}
    try:
        await self.app(scope, self.stream_receive.receive, self.stream_send.send)
    finally:
        await self.stream_send.send(None)

def __init__(self, code: int = 1000, reason: str | None = None) -> None:
    self.code = code
    self.reason = reason or ""

async def receive(self) -> Message:
    """
    Receive ASGI websocket messages, ensuring valid state transitions.
    """
    if self.client_state == WebSocketState.CONNECTING:
        message = await self._receive()
        message_type = message["type"]
        if message_type != "websocket.connect":
            raise RuntimeError(f'Expected ASGI message "websocket.connect", but got {message_type!r}')
        self.client_state = WebSocketState.CONNECTED
        return message
    elif self.client_state == WebSocketState.CONNECTED:
        message = await self._receive()
        message_type = message["type"]
        if message_type not in {"websocket.receive", "websocket.disconnect"}:
            raise RuntimeError(
                f'Expected ASGI message "websocket.receive" or "websocket.disconnect", but got {message_type!r}'
            )
        if message_type == "websocket.disconnect":
            self.client_state = WebSocketState.DISCONNECTED
        return message
    else:
        raise RuntimeError('Cannot call "receive" once a disconnect message has been received.')

async def send(self, message: Message) -> None:
    """
    Send ASGI websocket messages, ensuring valid state transitions.
    """
    if self.application_state == WebSocketState.CONNECTING:
        message_type = message["type"]
        if message_type not in {"websocket.accept", "websocket.close", "websocket.http.response.start"}:
            raise RuntimeError(
                'Expected ASGI message "websocket.accept", "websocket.close" or "websocket.http.response.start", '
                f"but got {message_type!r}"
            )
        if message_type == "websocket.close":
            self.application_state = WebSocketState.DISCONNECTED
        elif message_type == "websocket.http.response.start":
            self.application_state = WebSocketState.RESPONSE
        else:
            self.application_state = WebSocketState.CONNECTED
        await self._send(message)
    elif self.application_state == WebSocketState.CONNECTED:
        message_type = message["type"]
        if message_type not in {"websocket.send", "websocket.close"}:
            raise RuntimeError(
                f'Expected ASGI message "websocket.send" or "websocket.close", but got {message_type!r}'
            )
        if message_type == "websocket.close":
            self.application_state = WebSocketState.DISCONNECTED
        try:
            await self._send(message)
        except OSError:
            self.application_state = WebSocketState.DISCONNECTED
            raise WebSocketDisconnect(code=1006)
    elif self.application_state == WebSocketState.RESPONSE:
        message_type = message["type"]
        if message_type != "websocket.http.response.body":
            raise RuntimeError(f'Expected ASGI message "websocket.http.response.body", but got {message_type!r}')
        if not message.get("more_body", False):
            self.application_state = WebSocketState.DISCONNECTED
        await self._send(message)
    else:
        raise RuntimeError('Cannot call "send" once a close message has been sent.')

def _raise_on_disconnect(self, message: Message) -> None:
    if message["type"] == "websocket.disconnect":
        raise WebSocketDisconnect(message["code"], message.get("reason"))

async def receive_text(self) -> str:
    if self.application_state != WebSocketState.CONNECTED:
        raise RuntimeError('WebSocket is not connected. Need to call "accept" first.')
    message = await self.receive()
    self._raise_on_disconnect(message)
    return typing.cast(str, message["text"])

async def receive_bytes(self) -> bytes:
    if self.application_state != WebSocketState.CONNECTED:
        raise RuntimeError('WebSocket is not connected. Need to call "accept" first.')
    message = await self.receive()
    self._raise_on_disconnect(message)
    return typing.cast(bytes, message["bytes"])

async def receive_json(self, mode: str = "text") -> typing.Any:
    if mode not in {"text", "binary"}:
        raise RuntimeError('The "mode" argument should be "text" or "binary".')
    if self.application_state != WebSocketState.CONNECTED:
        raise RuntimeError('WebSocket is not connected. Need to call "accept" first.')
    message = await self.receive()
    self._raise_on_disconnect(message)

    if mode == "text":
        text = message["text"]
    else:
        text = message["bytes"].decode("utf-8")
    return json.loads(text)

async def iter_text(self) -> typing.AsyncIterator[str]:
    try:
        while True:
            yield await self.receive_text()
    except WebSocketDisconnect:
        pass

async def iter_bytes(self) -> typing.AsyncIterator[bytes]:
    try:
        while True:
            yield await self.receive_bytes()
    except WebSocketDisconnect:
        pass

async def iter_json(self) -> typing.AsyncIterator[typing.Any]:
    try:
        while True:
            yield await self.receive_json()
    except WebSocketDisconnect:
        pass

async def send_json(self, data: typing.Any, mode: str = "text") -> None:
    if mode not in {"text", "binary"}:
        raise RuntimeError('The "mode" argument should be "text" or "binary".')
    text = json.dumps(data, separators=(",", ":"), ensure_ascii=False)
    if mode == "text":
        await self.send({"type": "websocket.send", "text": text})
    else:
        await self.send({"type": "websocket.send", "bytes": text.encode("utf-8")})

async def send_denial_response(self, response: Response) -> None:
    if "websocket.http.response" in self.scope.get("extensions", {}):
        await response(self.scope, self.receive, self.send)
    else:
        raise RuntimeError("The server doesn't support the Websocket Denial Response extension.")

def __init__(self, code: int = 1000, reason: str | None = None) -> None:
    self.code = code
    self.reason = reason or ""

def __rich_console__(
    self, console: Console, options: ConsoleOptions
) -> RenderResult:
    for y in range(0, 5):
        for x in range(options.max_width):
            h = x / options.max_width
            l = 0.1 + ((y / 5) * 0.7)
            r1, g1, b1 = colorsys.hls_to_rgb(h, l, 1.0)
            r2, g2, b2 = colorsys.hls_to_rgb(h, l + 0.7 / 10, 1.0)
            bgcolor = Color.from_rgb(r1 * 255, g1 * 255, b1 * 255)
            color = Color.from_rgb(r2 * 255, g2 * 255, b2 * 255)
            yield Segment("▄", Style(color=color, bgcolor=bgcolor))
        yield Segment.line()

def __rich_measure__(
    self, console: "Console", options: ConsoleOptions
) -> Measurement:
    return Measurement(1, options.max_width)

def _emoji_replace(
    text: str,
    default_variant: Optional[str] = None,
    _emoji_sub: _EmojiSubMethod = re.compile(r"(:(\S*?)(?:(?:\-)(emoji|text))?:)").sub,
) -> str:
    """Replace emoji code in text."""
    get_emoji = EMOJI.__getitem__
    variants = {"text": "\uFE0E", "emoji": "\uFE0F"}
    get_variant = variants.get
    default_variant_code = variants.get(default_variant, "") if default_variant else ""

    def do_replace(match: Match[str]) -> str:
        emoji_code, emoji_name, variant = match.groups()
        try:
            return get_emoji(emoji_name.lower()) + get_variant(
                variant, default_variant_code
            )
        except KeyError:
            return emoji_code

    return _emoji_sub(do_replace, text)

def do_replace(match: Match[str]) -> str:
    emoji_code, emoji_name, variant = match.groups()
    try:
        return get_emoji(emoji_name.lower()) + get_variant(
            variant, default_variant_code
        )
    except KeyError:
        return emoji_code

def _make_title(self, obj: Any) -> Text:
    """Make a default title."""
    title_str = (
        str(obj)
        if (isclass(obj) or callable(obj) or ismodule(obj))
        else str(type(obj))
    )
    title_text = self.highlighter(title_str)
    return title_text

def __rich__(self) -> Panel:
    return Panel.fit(
        Group(*self._render()),
        title=self.title,
        border_style="scope.border",
        padding=(0, 1),
    )

def _get_signature(self, name: str, obj: Any) -> Optional[Text]:
    """Get a signature for a callable."""
    try:
        _signature = str(signature(obj)) + ":"
    except ValueError:
        _signature = "(...)"
    except TypeError:
        return None

    source_filename: Optional[str] = None
    try:
        source_filename = getfile(obj)
    except (OSError, TypeError):
        # OSError is raised if obj has no source file, e.g. when defined in REPL.
        pass

    callable_name = Text(name, style="inspect.callable")
    if source_filename:
        callable_name.stylize(f"link file://{source_filename}")
    signature_text = self.highlighter(_signature)

    qualname = name or getattr(obj, "__qualname__", name)

    # If obj is a module, there may be classes (which are callable) to display
    if inspect.isclass(obj):
        prefix = "class"
    elif inspect.iscoroutinefunction(obj):
        prefix = "async def"
    else:
        prefix = "def"

    qual_signature = Text.assemble(
        (f"{prefix} ", f"inspect.{prefix.replace(' ', '_')}"),
        (qualname, "inspect.callable"),
        signature_text,
    )

    return qual_signature

def _render(self) -> Iterable[RenderableType]:
    """Render object."""

    def sort_items(item: Tuple[str, Any]) -> Tuple[bool, str]:
        key, (_error, value) = item
        return (callable(value), key.strip("_").lower())

    def safe_getattr(attr_name: str) -> Tuple[Any, Any]:
        """Get attribute or any exception."""
        try:
            return (None, getattr(obj, attr_name))
        except Exception as error:
            return (error, None)

    obj = self.obj
    keys = dir(obj)
    total_items = len(keys)
    if not self.dunder:
        keys = [key for key in keys if not key.startswith("__")]
    if not self.private:
        keys = [key for key in keys if not key.startswith("_")]
    not_shown_count = total_items - len(keys)
    items = [(key, safe_getattr(key)) for key in keys]
    if self.sort:
        items.sort(key=sort_items)

    items_table = Table.grid(padding=(0, 1), expand=False)
    items_table.add_column(justify="right")
    add_row = items_table.add_row
    highlighter = self.highlighter

    if callable(obj):
        signature = self._get_signature("", obj)
        if signature is not None:
            yield signature
            yield ""

    if self.docs:
        _doc = self._get_formatted_doc(obj)
        if _doc is not None:
            doc_text = Text(_doc, style="inspect.help")
            doc_text = highlighter(doc_text)
            yield doc_text
            yield ""

    if self.value and not (isclass(obj) or callable(obj) or ismodule(obj)):
        yield Panel(
            Pretty(obj, indent_guides=True, max_length=10, max_string=60),
            border_style="inspect.value.border",
        )
        yield ""

    for key, (error, value) in items:
        key_text = Text.assemble(
            (
                key,
                "inspect.attr.dunder" if key.startswith("__") else "inspect.attr",
            ),
            (" =", "inspect.equals"),
        )
        if error is not None:
            warning = key_text.copy()
            warning.stylize("inspect.error")
            add_row(warning, highlighter(repr(error)))
            continue

        if callable(value):
            if not self.methods:
                continue

            _signature_text = self._get_signature(key, value)
            if _signature_text is None:
                add_row(key_text, Pretty(value, highlighter=highlighter))
            else:
                if self.docs:
                    docs = self._get_formatted_doc(value)
                    if docs is not None:
                        _signature_text.append("\n" if "\n" in docs else " ")
                        doc = highlighter(docs)
                        doc.stylize("inspect.doc")
                        _signature_text.append(doc)

                add_row(key_text, _signature_text)
        else:
            add_row(key_text, Pretty(value, highlighter=highlighter))
    if items_table.row_count:
        yield items_table
    elif not_shown_count:
        yield Text.from_markup(
            f"[b cyan]{not_shown_count}[/][i] attribute(s) not shown.[/i] "
            f"Run [b][magenta]inspect[/]([not b]inspect[/])[/b] for options."
        )

def sort_items(item: Tuple[str, Any]) -> Tuple[bool, str]:
    key, (_error, value) = item
    return (callable(value), key.strip("_").lower())

def safe_getattr(attr_name: str) -> Tuple[Any, Any]:
    """Get attribute or any exception."""
    try:
        return (None, getattr(obj, attr_name))
    except Exception as error:
        return (error, None)

def get_object_types_mro(obj: Union[object, Type[Any]]) -> Tuple[type, ...]:
    """Returns the MRO of an object's class, or of the object itself if it's a class."""
    if not hasattr(obj, "__mro__"):
        # N.B. we cannot use `if type(obj) is type` here because it doesn't work with
        # some types of classes, such as the ones that use abc.ABCMeta.
        obj = type(obj)
    return getattr(obj, "__mro__", ())

def get_object_types_mro_as_strings(obj: object) -> Collection[str]:
    """
    Returns the MRO of an object's class as full qualified names, or of the object itself if it's a class.

    Examples:
        `object_types_mro_as_strings(JSONDecoder)` will return `['json.decoder.JSONDecoder', 'builtins.object']`
    """
    return [
        f'{getattr(type_, "__module__", "")}.{getattr(type_, "__qualname__", "")}'
        for type_ in get_object_types_mro(obj)
    ]

def is_object_one_of_types(
    obj: object, fully_qualified_types_names: Collection[str]
) -> bool:
    """
    Returns `True` if the given object's class (or the object itself, if it's a class) has one of the
    fully qualified names in its MRO.
    """
    for type_name in get_object_types_mro_as_strings(obj):
        if type_name in fully_qualified_types_names:
            return True
    return False

def loop_first(values: Iterable[T]) -> Iterable[Tuple[bool, T]]:
    """Iterate and generate a tuple with a flag for first value."""
    iter_values = iter(values)
    try:
        value = next(iter_values)
    except StopIteration:
        return
    yield True, value
    for value in iter_values:
        yield False, value

def loop_last(values: Iterable[T]) -> Iterable[Tuple[bool, T]]:
    """Iterate and generate a tuple with a flag for last value."""
    iter_values = iter(values)
    try:
        previous_value = next(iter_values)
    except StopIteration:
        return
    for value in iter_values:
        yield False, previous_value
        previous_value = value
    yield True, previous_value

def loop_first_last(values: Iterable[T]) -> Iterable[Tuple[bool, bool, T]]:
    """Iterate and generate a tuple with a flag for first and last value."""
    iter_values = iter(values)
    try:
        previous_value = next(iter_values)
    except StopIteration:
        return
    first = True
    for value in iter_values:
        yield first, False, previous_value
        first = False
        previous_value = value
    yield first, True, previous_value

def pick_bool(*values: Optional[bool]) -> bool:
    """Pick the first non-none bool or return the last value.

    Args:
        *values (bool): Any number of boolean or None values.

    Returns:
        bool: First non-none boolean.
    """
    assert values, "1 or more values required"
    for value in values:
        if value is not None:
            return value
    return bool(value)

@property
def top(self) -> T:
    """Get top of stack."""
    return self[-1]

def push(self, item: T) -> None:
    """Push an item on to the stack (append in stack nomenclature)."""
    self.append(item)

@classmethod
def from_param(cls, value: "WindowsCoordinates") -> COORD:
    """Converts a WindowsCoordinates into a wintypes _COORD structure.
    This classmethod is internally called by ctypes to perform the conversion.

    Args:
        value (WindowsCoordinates): The input coordinates to convert.

    Returns:
        wintypes._COORD: The converted coordinates struct.
    """
    return COORD(value.col, value.row)

@property
def cursor_position(self) -> WindowsCoordinates:
    """Returns the current position of the cursor (0-based)

    Returns:
        WindowsCoordinates: The current cursor position.
    """
    coord: COORD = GetConsoleScreenBufferInfo(self._handle).dwCursorPosition
    return WindowsCoordinates(row=coord.Y, col=coord.X)

@property
def screen_size(self) -> WindowsCoordinates:
    """Returns the current size of the console screen buffer, in character columns and rows

    Returns:
        WindowsCoordinates: The width and height of the screen as WindowsCoordinates.
    """
    screen_size: COORD = GetConsoleScreenBufferInfo(self._handle).dwSize
    return WindowsCoordinates(row=screen_size.Y, col=screen_size.X)

def move_cursor_up(self) -> None:
    """Move the cursor up a single cell"""
    cursor_position = self.cursor_position
    SetConsoleCursorPosition(
        self._handle,
        coords=WindowsCoordinates(
            row=cursor_position.row - 1, col=cursor_position.col
        ),
    )

def move_cursor_down(self) -> None:
    """Move the cursor down a single cell"""
    cursor_position = self.cursor_position
    SetConsoleCursorPosition(
        self._handle,
        coords=WindowsCoordinates(
            row=cursor_position.row + 1,
            col=cursor_position.col,
        ),
    )

def move_cursor_forward(self) -> None:
    """Move the cursor forward a single cell. Wrap to the next line if required."""
    row, col = self.cursor_position
    if col == self.screen_size.col - 1:
        row += 1
        col = 0
    else:
        col += 1
    SetConsoleCursorPosition(
        self._handle, coords=WindowsCoordinates(row=row, col=col)
    )

def move_cursor_backward(self) -> None:
    """Move the cursor backward a single cell. Wrap to the previous line if required."""
    row, col = self.cursor_position
    if col == 0:
        row -= 1
        col = self.screen_size.col - 1
    else:
        col -= 1
    SetConsoleCursorPosition(
        self._handle, coords=WindowsCoordinates(row=row, col=col)
    )

def _get_cursor_size(self) -> int:
    """Get the percentage of the character cell that is filled by the cursor"""
    cursor_info = CONSOLE_CURSOR_INFO()
    GetConsoleCursorInfo(self._handle, cursor_info=cursor_info)
    return int(cursor_info.dwSize)

def get_windows_console_features() -> WindowsConsoleFeatures:
    features = WindowsConsoleFeatures()
    return features

def legacy_windows_render(buffer: Iterable[Segment], term: LegacyWindowsTerm) -> None:
    """Makes appropriate Windows Console API calls based on the segments in the buffer.

    Args:
        buffer (Iterable[Segment]): Iterable of Segments to convert to Win32 API calls.
        term (LegacyWindowsTerm): Used to call the Windows Console API.
    """
    for text, style, control in buffer:
        if not control:
            if style:
                term.write_styled(text, style)
            else:
                term.write_text(text)
        else:
            control_codes: Sequence[ControlCode] = control
            for control_code in control_codes:
                control_type = control_code[0]
                if control_type == ControlType.CURSOR_MOVE_TO:
                    _, x, y = cast(Tuple[ControlType, int, int], control_code)
                    term.move_cursor_to(WindowsCoordinates(row=y - 1, col=x - 1))
                elif control_type == ControlType.CARRIAGE_RETURN:
                    term.write_text("\r")
                elif control_type == ControlType.HOME:
                    term.move_cursor_to(WindowsCoordinates(0, 0))
                elif control_type == ControlType.CURSOR_UP:
                    term.move_cursor_up()
                elif control_type == ControlType.CURSOR_DOWN:
                    term.move_cursor_down()
                elif control_type == ControlType.CURSOR_FORWARD:
                    term.move_cursor_forward()
                elif control_type == ControlType.CURSOR_BACKWARD:
                    term.move_cursor_backward()
                elif control_type == ControlType.CURSOR_MOVE_TO_COLUMN:
                    _, column = cast(Tuple[ControlType, int], control_code)
                    term.move_cursor_to_column(column - 1)
                elif control_type == ControlType.HIDE_CURSOR:
                    term.hide_cursor()
                elif control_type == ControlType.SHOW_CURSOR:
                    term.show_cursor()
                elif control_type == ControlType.ERASE_IN_LINE:
                    _, mode = cast(Tuple[ControlType, int], control_code)
                    if mode == 0:
                        term.erase_end_of_line()
                    elif mode == 1:
                        term.erase_start_of_line()
                    elif mode == 2:
                        term.erase_line()
                elif control_type == ControlType.SET_WINDOW_TITLE:
                    _, title = cast(Tuple[ControlType, str], control_code)
                    term.set_title(title)

@classmethod
def __subclasshook__(cls, other: type) -> bool:
    """Check if this class supports the rich render protocol."""
    return hasattr(other, "__rich_console__") or hasattr(other, "__rich__")

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    align = self.align
    width = console.measure(self.renderable, options=options).maximum
    rendered = console.render(
        Constrain(
            self.renderable, width if self.width is None else min(width, self.width)
        ),
        options.update(height=None),
    )
    lines = list(Segment.split_lines(rendered))
    width, height = Segment.get_shape(lines)
    lines = Segment.set_shape(lines, width, height)
    new_line = Segment.line()
    excess_space = options.max_width - width
    style = console.get_style(self.style) if self.style is not None else None

    def generate_segments() -> Iterable[Segment]:
        if excess_space <= 0:
            # Exact fit
            for line in lines:
                yield from line
                yield new_line

        elif align == "left":
            # Pad on the right
            pad = Segment(" " * excess_space, style) if self.pad else None
            for line in lines:
                yield from line
                if pad:
                    yield pad
                yield new_line

        elif align == "center":
            # Pad left and right
            left = excess_space // 2
            pad = Segment(" " * left, style)
            pad_right = (
                Segment(" " * (excess_space - left), style) if self.pad else None
            )
            for line in lines:
                if left:
                    yield pad
                yield from line
                if pad_right:
                    yield pad_right
                yield new_line

        elif align == "right":
            # Padding on left
            pad = Segment(" " * excess_space, style)
            for line in lines:
                yield pad
                yield from line
                yield new_line

    blank_line = (
        Segment(f"{' ' * (self.width or options.max_width)}\n", style)
        if self.pad
        else Segment("\n")
    )

    def blank_lines(count: int) -> Iterable[Segment]:
        if count > 0:
            for _ in range(count):
                yield blank_line

    vertical_height = self.height or options.height
    iter_segments: Iterable[Segment]
    if self.vertical and vertical_height is not None:
        if self.vertical == "top":
            bottom_space = vertical_height - height
            iter_segments = chain(generate_segments(), blank_lines(bottom_space))
        elif self.vertical == "middle":
            top_space = (vertical_height - height) // 2
            bottom_space = vertical_height - top_space - height
            iter_segments = chain(
                blank_lines(top_space),
                generate_segments(),
                blank_lines(bottom_space),
            )
        else:  #  self.vertical == "bottom":
            top_space = vertical_height - height
            iter_segments = chain(blank_lines(top_space), generate_segments())
    else:
        iter_segments = generate_segments()
    if self.style:
        style = console.get_style(self.style)
        iter_segments = Segment.apply_style(iter_segments, style)
    yield from iter_segments

def generate_segments() -> Iterable[Segment]:
    if excess_space <= 0:
        # Exact fit
        for line in lines:
            yield from line
            yield new_line

    elif align == "left":
        # Pad on the right
        pad = Segment(" " * excess_space, style) if self.pad else None
        for line in lines:
            yield from line
            if pad:
                yield pad
            yield new_line

    elif align == "center":
        # Pad left and right
        left = excess_space // 2
        pad = Segment(" " * left, style)
        pad_right = (
            Segment(" " * (excess_space - left), style) if self.pad else None
        )
        for line in lines:
            if left:
                yield pad
            yield from line
            if pad_right:
                yield pad_right
            yield new_line

    elif align == "right":
        # Padding on left
        pad = Segment(" " * excess_space, style)
        for line in lines:
            yield pad
            yield from line
            yield new_line

def blank_lines(count: int) -> Iterable[Segment]:
    if count > 0:
        for _ in range(count):
            yield blank_line

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> Measurement:
    measurement = Measurement.get(console, options, self.renderable)
    return measurement

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    style = console.get_style(self.style) if self.style is not None else None
    lines = console.render_lines(
        self.renderable, options.update(height=None), pad=False
    )
    width, _height = Segment.get_shape(lines)
    new_line = Segment.line()
    height = options.height or options.size.height
    top_space = (height - len(lines)) // 2
    bottom_space = height - top_space - len(lines)
    blank_line = Segment(f"{' ' * width}", style)

    def blank_lines(count: int) -> Iterable[Segment]:
        for _ in range(count):
            yield blank_line
            yield new_line

    if top_space > 0:
        yield from blank_lines(top_space)
    for line in lines:
        yield from line
        yield new_line
    if bottom_space > 0:
        yield from blank_lines(bottom_space)

def blank_lines(count: int) -> Iterable[Segment]:
    for _ in range(count):
        yield blank_line
        yield new_line

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> Measurement:
    measurement = Measurement.get(console, options, self.renderable)
    return measurement

def _ansi_tokenize(ansi_text: str) -> Iterable[_AnsiToken]:
    """Tokenize a string in to plain text and ANSI codes.

    Args:
        ansi_text (str): A String containing ANSI codes.

    Yields:
        AnsiToken: A named tuple of (plain, sgr, osc)
    """

    position = 0
    sgr: Optional[str]
    osc: Optional[str]
    for match in re_ansi.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        if start > position:
            yield _AnsiToken(ansi_text[position:start])
        if sgr:
            if sgr == "(":
                position = end + 1
                continue
            if sgr.endswith("m"):
                yield _AnsiToken("", sgr[1:-1], osc)
        else:
            yield _AnsiToken("", sgr, osc)
        position = end
    if position < len(ansi_text):
        yield _AnsiToken(ansi_text[position:])

def decode_line(self, line: str) -> Text:
    """Decode a line containing ansi codes.

    Args:
        line (str): A line of terminal output.

    Returns:
        Text: A Text instance marked up according to ansi codes.
    """
    from_ansi = Color.from_ansi
    from_rgb = Color.from_rgb
    _Style = Style
    text = Text()
    append = text.append
    line = line.rsplit("\r", 1)[-1]
    for plain_text, sgr, osc in _ansi_tokenize(line):
        if plain_text:
            append(plain_text, self.style or None)
        elif osc is not None:
            if osc.startswith("8;"):
                _params, semicolon, link = osc[2:].partition(";")
                if semicolon:
                    self.style = self.style.update_link(link or None)
        elif sgr is not None:
            # Translate in to semi-colon separated codes
            # Ignore invalid codes, because we want to be lenient
            codes = [
                min(255, int(_code) if _code else 0)
                for _code in sgr.split(";")
                if _code.isdigit() or _code == ""
            ]
            iter_codes = iter(codes)
            for code in iter_codes:
                if code == 0:
                    # reset
                    self.style = _Style.null()
                elif code in SGR_STYLE_MAP:
                    # styles
                    self.style += _Style.parse(SGR_STYLE_MAP[code])
                elif code == 38:
                    #  Foreground
                    with suppress(StopIteration):
                        color_type = next(iter_codes)
                        if color_type == 5:
                            self.style += _Style.from_color(
                                from_ansi(next(iter_codes))
                            )
                        elif color_type == 2:
                            self.style += _Style.from_color(
                                from_rgb(
                                    next(iter_codes),
                                    next(iter_codes),
                                    next(iter_codes),
                                )
                            )
                elif code == 48:
                    # Background
                    with suppress(StopIteration):
                        color_type = next(iter_codes)
                        if color_type == 5:
                            self.style += _Style.from_color(
                                None, from_ansi(next(iter_codes))
                            )
                        elif color_type == 2:
                            self.style += _Style.from_color(
                                None,
                                from_rgb(
                                    next(iter_codes),
                                    next(iter_codes),
                                    next(iter_codes),
                                ),
                            )

    return text

def __rich_measure__(
    self, console: Console, options: ConsoleOptions
) -> Measurement:
    return (
        Measurement(self.width, self.width)
        if self.width is not None
        else Measurement(4, options.max_width)
    )

@lru_cache(4096)
def cached_cell_len(text: str) -> int:
    """Get the number of cells required to display text.

    This method always caches, which may use up a lot of memory. It is recommended to use
    `cell_len` over this method.

    Args:
        text (str): Text to display.

    Returns:
        int: Get the number of cells required to display text.
    """
    if _is_single_cell_widths(text):
        return len(text)
    return sum(map(get_character_cell_size, text))

def cell_len(text: str, _cell_len: Callable[[str], int] = cached_cell_len) -> int:
    """Get the number of cells required to display text.

    Args:
        text (str): Text to display.

    Returns:
        int: Get the number of cells required to display text.
    """
    if len(text) < 512:
        return _cell_len(text)
    if _is_single_cell_widths(text):
        return len(text)
    return sum(map(get_character_cell_size, text))

def set_cell_size(text: str, total: int) -> str:
    """Set the length of a string to fit within given number of cells."""

    if _is_single_cell_widths(text):
        size = len(text)
        if size < total:
            return text + " " * (total - size)
        return text[:total]

    if total <= 0:
        return ""
    cell_size = cell_len(text)
    if cell_size == total:
        return text
    if cell_size < total:
        return text + " " * (total - cell_size)

    start = 0
    end = len(text)

    # Binary search until we find the right size
    while True:
        pos = (start + end) // 2
        before = text[: pos + 1]
        before_len = cell_len(before)
        if before_len == total + 1 and cell_len(before[-1]) == 2:
            return before[:-1] + " "
        if before_len == total:
            return before
        if before_len > total:
            end = pos
        else:
            start = pos

def __rich__(self) -> "Text":
    """Displays the actual color if Rich printed."""
    from .style import Style
    from .text import Text

    return Text.assemble(
        f"<color {self.name!r} ({self.type.name.lower()})",
        ("⬤", Style(color=self)),
        " >",
    )

@property
def system(self) -> ColorSystem:
    """Get the native color system for this color."""
    if self.type == ColorType.DEFAULT:
        return ColorSystem.STANDARD
    return ColorSystem(int(self.type))

@property
def is_system_defined(self) -> bool:
