def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    _padding = Padding.unpack(self.padding)
    renderable = (
        Padding(self.renderable, _padding) if any(_padding) else self.renderable
    )
    style = console.get_style(self.style)
    partial_border_style = console.get_style(self.border_style)
    border_style = style + partial_border_style
    width = (
        options.max_width
        if self.width is None
        else min(options.max_width, self.width)
    )

    safe_box: bool = console.safe_box if self.safe_box is None else self.safe_box
    box = self.box.substitute(options, safe=safe_box)

    def align_text(
        text: Text, width: int, align: str, character: str, style: Style
    ) -> Text:
        """Gets new aligned text.

        Args:
            text (Text): Title or subtitle text.
            width (int): Desired width.
            align (str): Alignment.
            character (str): Character for alignment.
            style (Style): Border style

        Returns:
            Text: New text instance
        """
        text = text.copy()
        text.truncate(width)
        excess_space = width - cell_len(text.plain)
        if text.style:
            text.stylize(console.get_style(text.style))

        if excess_space:
            if align == "left":
                return Text.assemble(
                    text,
                    (character * excess_space, style),
                    no_wrap=True,
                    end="",
                )
            elif align == "center":
                left = excess_space // 2
                return Text.assemble(
                    (character * left, style),
                    text,
                    (character * (excess_space - left), style),
                    no_wrap=True,
                    end="",
                )
            else:
                return Text.assemble(
                    (character * excess_space, style),
                    text,
                    no_wrap=True,
                    end="",
                )
        return text

    title_text = self._title
    if title_text is not None:
        title_text.stylize_before(partial_border_style)

    child_width = (
        width - 2
        if self.expand
        else console.measure(
            renderable, options=options.update_width(width - 2)
        ).maximum
    )
    child_height = self.height or options.height or None
    if child_height:
        child_height -= 2
    if title_text is not None:
        child_width = min(
            options.max_width - 2, max(child_width, title_text.cell_len + 2)
        )

    width = child_width + 2
    child_options = options.update(
        width=child_width, height=child_height, highlight=self.highlight
    )
    lines = console.render_lines(renderable, child_options, style=style)

    line_start = Segment(box.mid_left, border_style)
    line_end = Segment(f"{box.mid_right}", border_style)
    new_line = Segment.line()
    if title_text is None or width <= 4:
        yield Segment(box.get_top([width - 2]), border_style)
    else:
        title_text = align_text(
            title_text,
            width - 4,
            self.title_align,
            box.top,
            border_style,
        )
        yield Segment(box.top_left + box.top, border_style)
        yield from console.render(title_text, child_options.update_width(width - 4))
        yield Segment(box.top + box.top_right, border_style)

    yield new_line
    for line in lines:
        yield line_start
        yield from line
        yield line_end
        yield new_line

    subtitle_text = self._subtitle
    if subtitle_text is not None:
        subtitle_text.stylize_before(partial_border_style)

    if subtitle_text is None or width <= 4:
        yield Segment(box.get_bottom([width - 2]), border_style)
    else:
        subtitle_text = align_text(
            subtitle_text,
            width - 4,
            self.subtitle_align,
            box.bottom,
            border_style,
        )
        yield Segment(box.bottom_left + box.bottom, border_style)
        yield from console.render(
            subtitle_text, child_options.update_width(width - 4)
        )
        yield Segment(box.bottom + box.bottom_right, border_style)

    yield new_line

def align_text(
    text: Text, width: int, align: str, character: str, style: Style
) -> Text:
    """Gets new aligned text.

    Args:
        text (Text): Title or subtitle text.
        width (int): Desired width.
        align (str): Alignment.
        character (str): Character for alignment.
        style (Style): Border style

    Returns:
        Text: New text instance
    """
    text = text.copy()
    text.truncate(width)
    excess_space = width - cell_len(text.plain)
    if text.style:
        text.stylize(console.get_style(text.style))

    if excess_space:
        if align == "left":
            return Text.assemble(
                text,
                (character * excess_space, style),
                no_wrap=True,
                end="",
            )
        elif align == "center":
            left = excess_space // 2
            return Text.assemble(
                (character * left, style),
                text,
                (character * (excess_space - left), style),
                no_wrap=True,
                end="",
            )
        else:
            return Text.assemble(
                (character * excess_space, style),
                text,
                no_wrap=True,
                end="",
            )
    return text

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> "Measurement":
    _title = self._title
    _, right, _, left = Padding.unpack(self.padding)
    padding = left + right
    renderables = [self.renderable, _title] if _title else [self.renderable]

    if self.width is None:
        width = (
            measure_renderables(
                console,
                options.update_width(options.max_width - padding - 2),
                renderables,
            ).maximum
            + padding
            + 2
        )
    else:
        width = self.width
    return Measurement(width, width)

def _is_attr_object(obj: Any) -> bool:
    """Check if an object was created with attrs module."""
    return _has_attrs and _attr_module.has(type(obj))

def _get_attr_fields(obj: Any) -> Sequence["_attr_module.Attribute[Any]"]:
    """Get fields for an attrs object."""
    return _attr_module.fields(type(obj)) if _has_attrs else []

def _safe_isinstance(
    obj: object, class_or_tuple: Union[type, Tuple[type, ...]]
) -> bool:
    """isinstance can fail in rare cases, for example types with no __class__"""
    try:
        return isinstance(obj, class_or_tuple)
    except Exception:
        return False

def display_hook(value: Any) -> None:
    """Replacement sys.displayhook which prettifies objects with Rich."""
    if value is not None:
        assert console is not None
        builtins._ = None  # type: ignore[attr-defined]
        console.print(
            (
                value
                if _safe_isinstance(value, RichRenderable)
                else Pretty(
                    value,
                    overflow=overflow,
                    indent_guides=indent_guides,
                    max_length=max_length,
                    max_string=max_string,
                    max_depth=max_depth,
                    expand_all=expand_all,
                )
            ),
            crop=crop,
        )
        builtins._ = value  # type: ignore[attr-defined]

def __call__(self, value: Any) -> Any:
    if self.pprint:
        return _ipy_display_hook(
            value,
            console=get_console(),
            overflow=overflow,
            indent_guides=indent_guides,
            max_length=max_length,
            max_string=max_string,
            max_depth=max_depth,
            expand_all=expand_all,
        )
    else:
        return repr(value)

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> "Measurement":
    pretty_str = pretty_repr(
        self._object,
        max_width=options.max_width,
        indent_size=self.indent_size,
        max_length=self.max_length,
        max_string=self.max_string,
        max_depth=self.max_depth,
        expand_all=self.expand_all,
    )
    text_width = (
        max(cell_len(line) for line in pretty_str.splitlines()) if pretty_str else 0
    )
    return Measurement(text_width, text_width)

def _get_braces_for_defaultdict(_object: DefaultDict[Any, Any]) -> Tuple[str, str, str]:
    return (
        f"defaultdict({_object.default_factory!r}, {{",
        "})",
        f"defaultdict({_object.default_factory!r}, {{}})",
    )

def _get_braces_for_deque(_object: Deque[Any]) -> Tuple[str, str, str]:
    if _object.maxlen is None:
        return ("deque([", "])", "deque()")
    return (
        "deque([",
        f"], maxlen={_object.maxlen})",
        f"deque(maxlen={_object.maxlen})",
    )

def is_expandable(obj: Any) -> bool:
    """Check if an object may be expanded by pretty print."""
    return (
        _safe_isinstance(obj, _CONTAINERS)
        or (is_dataclass(obj))
        or (hasattr(obj, "__rich_repr__"))
        or _is_attr_object(obj)
