    return self.__class__, (None, self.url, self.reason)

def __init__(
    self, pool: ConnectionPool, url: str, retries: Retry | int = 3
) -> None:
    message = f"Tried to open a foreign host with url: {url}"
    super().__init__(pool, url, message)
    self.retries = retries

def __reduce__(self) -> _TYPE_REDUCE_RESULT:
    # For pickling purposes.
    return self.__class__, (None, self._message)

@property
def pool(self) -> HTTPConnection:
    warnings.warn(
        "The 'pool' property is deprecated and will be removed "
        "in urllib3 v2.1.0. Use 'conn' instead.",
        DeprecationWarning,
        stacklevel=2,
    )

    return self.conn

def __reduce__(self) -> _TYPE_REDUCE_RESULT:
    # For pickling purposes.
    return self.__class__, (self._host, None, self._reason)

def __init__(self, partial: int, expected: int) -> None:
    self.partial = partial
    self.expected = expected

def __repr__(self) -> str:
    return "IncompleteRead(%i bytes read, %i more expected)" % (
        self.partial,
        self.expected,
    )

def __repr__(self) -> str:
    return "InvalidChunkLength(got length %r, %i bytes read)" % (
        self.length,
        self.partial,
    )

def __init__(self, scheme: str | None) -> None:
    # 'localhost' is here because our URL parser parses
    # localhost:8080 -> scheme=localhost, remove if we fix this.
    if scheme == "localhost":
        scheme = None
    if scheme is None:
        message = "Proxy URL had no scheme, should start with http:// or https://"
    else:
        message = f"Proxy URL had unsupported scheme {scheme}, should use http:// or https://"
    super().__init__(message)

def __init__(
    self, defects: list[MessageDefect], unparsed_data: bytes | str | None
) -> None:
    message = f"{defects or 'Unknown'}, unparsed data: {unparsed_data!r}"
    super().__init__(message)

def _render_parts(
    self,
    header_parts: (
        dict[str, _TYPE_FIELD_VALUE | None]
        | typing.Sequence[tuple[str, _TYPE_FIELD_VALUE | None]]
    ),
) -> str:
    """
    Helper function to format and quote a single header.

    Useful for single headers that are composed of multiple items. E.g.,
    'Content-Disposition' fields.

    :param header_parts:
        A sequence of (k, v) tuples or a :class:`dict` of (k, v) to format
        as `k1="v1"; k2="v2"; ...`.
    """
    iterable: typing.Iterable[tuple[str, _TYPE_FIELD_VALUE | None]]

    parts = []
    if isinstance(header_parts, dict):
        iterable = header_parts.items()
    else:
        iterable = header_parts

    for name, value in iterable:
        if value is not None:
            parts.append(self._render_part(name, value))

    return "; ".join(parts)

def render_headers(self) -> str:
    """
    Renders the headers for this request field.
    """
    lines = []

    sort_keys = ["Content-Disposition", "Content-Type", "Content-Location"]
    for sort_key in sort_keys:
        if self.headers.get(sort_key, False):
            lines.append(f"{sort_key}: {self.headers[sort_key]}")

    for header_name, header_value in self.headers.items():
        if header_name not in sort_keys:
            if header_value:
                lines.append(f"{header_name}: {header_value}")

    lines.append("\r\n")
    return "\r\n".join(lines)

def choose_boundary() -> str:
    """
    Our embarrassingly-simple replacement for mimetools.choose_boundary.
    """
    return binascii.hexlify(os.urandom(16)).decode()

def iter_field_objects(fields: _TYPE_FIELDS) -> typing.Iterable[RequestField]:
    """
    Iterate over fields.

    Supports list of (k, v) tuples and dicts, and lists of
    :class:`~urllib3.fields.RequestField`.

    """
    iterable: typing.Iterable[RequestField | tuple[str, _TYPE_FIELD_VALUE_TUPLE]]

    if isinstance(fields, typing.Mapping):
        iterable = fields.items()
    else:
        iterable = fields

    for field in iterable:
        if isinstance(field, RequestField):
            yield field
        else:
            yield RequestField.from_tuples(*field)

def __init__(self, obj: T):
    self.lock = threading.RLock()
    self._obj = obj

def __enter__(self) -> T:
    self.lock.acquire()
    return self._obj

def __init__(
    self, host: str, port: int | None = None, **kwargs: typing.Any
) -> None:
    self._h2_conn = self._new_h2_conn()
    self._h2_stream: int | None = None
    self._headers: list[tuple[bytes, bytes]] = []

    if "proxy" in kwargs or "proxy_config" in kwargs:  # Defensive:
        raise NotImplementedError("Proxies aren't supported with HTTP/2")

    super().__init__(host, port, **kwargs)

    if self._tunnel_host is not None:
        raise NotImplementedError("Tunneling isn't supported with HTTP/2")

def _new_h2_conn(self) -> _LockedObject[h2.connection.H2Connection]:
    config = h2.config.H2Configuration(client_side=True)
    return _LockedObject(h2.connection.H2Connection(config=config))

def connect(self) -> None:
    super().connect()
    with self._h2_conn as conn:
        conn.initiate_connection()
        if data_to_send := conn.data_to_send():
            self.sock.sendall(data_to_send)

def send(self, data: typing.Any) -> None:
    """Send data to the server.
    `data` can be: `str`, `bytes`, an iterable, or file-like objects
    that support a .read() method.
    """
    if self._h2_stream is None:
        raise ConnectionError("Must call `putrequest` first.")

    with self._h2_conn as conn:
        if data_to_send := conn.data_to_send():
            self.sock.sendall(data_to_send)

        if hasattr(data, "read"):  # file-like objects
            while True:
                chunk = data.read(self.blocksize)
                if not chunk:
                    break
                if isinstance(chunk, str):
                    chunk = chunk.encode()  # pragma: no cover
                conn.send_data(self._h2_stream, chunk, end_stream=False)
                if data_to_send := conn.data_to_send():
                    self.sock.sendall(data_to_send)
            conn.end_stream(self._h2_stream)
            return

        if isinstance(data, str):  # str -> bytes
            data = data.encode()

        try:
            if isinstance(data, bytes):
                conn.send_data(self._h2_stream, data, end_stream=True)
                if data_to_send := conn.data_to_send():
                    self.sock.sendall(data_to_send)
            else:
                for chunk in data:
                    conn.send_data(self._h2_stream, chunk, end_stream=False)
                    if data_to_send := conn.data_to_send():
                        self.sock.sendall(data_to_send)
                conn.end_stream(self._h2_stream)
        except TypeError:
            raise TypeError(
                "`data` should be str, bytes, iterable, or file. got %r"
                % type(data)
            )

def getresponse(  # type: ignore[override]
    self,
) -> HTTP2Response:
    status = None
    data = bytearray()
    with self._h2_conn as conn:
        end_stream = False
        while not end_stream:
            # TODO: Arbitrary read value.
            if received_data := self.sock.recv(65535):
                events = conn.receive_data(received_data)
                for event in events:
                    if isinstance(event, h2.events.ResponseReceived):
                        headers = HTTPHeaderDict()
                        for header, value in event.headers:
                            if header == b":status":
                                status = int(value.decode())
                            else:
                                headers.add(
                                    header.decode("ascii"), value.decode("ascii")
                                )

                    elif isinstance(event, h2.events.DataReceived):
                        data += event.data
                        conn.acknowledge_received_data(
                            event.flow_controlled_length, event.stream_id
                        )

                    elif isinstance(event, h2.events.StreamEnded):
                        end_stream = True

            if data_to_send := conn.data_to_send():
                self.sock.sendall(data_to_send)

    assert status is not None
    return HTTP2Response(
        status=status,
        headers=headers,
        request_url=self._request_url,
        data=bytes(data),
    )

def request(  # type: ignore[override]
    self,
    method: str,
    url: str,
    body: _TYPE_BODY | None = None,
    headers: typing.Mapping[str, str] | None = None,
    *,
    preload_content: bool = True,
    decode_content: bool = True,
    enforce_content_length: bool = True,
    **kwargs: typing.Any,
) -> None:
    """Send an HTTP/2 request"""
    if "chunked" in kwargs:
        # TODO this is often present from upstream.
        # raise NotImplementedError("`chunked` isn't supported with HTTP/2")
        pass

    if self.sock is not None:
        self.sock.settimeout(self.timeout)

    self.putrequest(method, url)

    headers = headers or {}
    for k, v in headers.items():
        if k.lower() == "transfer-encoding" and v == "chunked":
            continue
        else:
            self.putheader(k, v)

    if b"user-agent" not in dict(self._headers):
        self.putheader(b"user-agent", _get_default_user_agent())

    if body:
        self.endheaders(message_body=body)
        self.send(body)
    else:
        self.endheaders()

def close(self) -> None:
    with self._h2_conn as conn:
        try:
            conn.close_connection()
            if data := conn.data_to_send():
                self.sock.sendall(data)
        except Exception:
            pass

    # Reset all our HTTP/2 connection state.
    self._h2_conn = self._new_h2_conn()
    self._h2_stream = None
    self._headers = []

    super().close()

@property
def data(self) -> bytes:
    return self._data

def __init__(self) -> None:
    self._lock = threading.Lock()
    self._cache_locks: dict[tuple[str, int], threading.RLock] = {}
    self._cache_values: dict[tuple[str, int], bool | None] = {}

def set_and_release(
    self, host: str, port: int, supports_http2: bool | None
) -> None:
    key = (host, port)
    key_lock = self._cache_locks[key]
    with key_lock:  # Uses an RLock, so can be locked again from same thread.
        if supports_http2 is None and self._cache_values[key] is not None:
            raise ValueError(
                "Cannot reset HTTP/2 support for origin after value has been set."
            )  # Defensive: not expected in normal usage

    self._cache_values[key] = supports_http2
    key_lock.release()

def _values(self) -> dict[tuple[str, int], bool | None]:
    """This function is for testing purposes only. Gets the current state of the probe cache"""
    with self._lock:
        return {k: v for k, v in self._cache_values.items()}

def _reset(self) -> None:
    """This function is for testing purposes only. Reset the cache values"""
    with self._lock:
        self._cache_locks = {}
        self._cache_values = {}

def _merge_pool_kwargs(
    self, override: dict[str, typing.Any] | None
) -> dict[str, typing.Any]:
    """
    Merge a dictionary of override values for self.connection_pool_kw.

    This does not modify self.connection_pool_kw and returns a new dict.
    Any keys in the override dictionary with a value of ``None`` are
    removed from the merged dictionary.
    """
    base_pool_kwargs = self.connection_pool_kw.copy()
    if override:
        for key, value in override.items():
            if value is None:
                try:
                    del base_pool_kwargs[key]
                except KeyError:
                    pass
            else:
                base_pool_kwargs[key] = value
    return base_pool_kwargs

def _proxy_requires_url_absolute_form(self, parsed_url: Url) -> bool:
    """
    Indicates if the proxy requires the complete destination URL in the
    request.  Normally this is only needed when not using an HTTP CONNECT
    tunnel.
    """
    if self.proxy is None:
        return False

    return not connection_requires_http_tunnel(
        self.proxy, self.proxy_config, parsed_url.scheme
    )

def connection_from_host(
    self,
    host: str | None,
    port: int | None = None,
    scheme: str | None = "http",
    pool_kwargs: dict[str, typing.Any] | None = None,
) -> HTTPConnectionPool:
    if scheme == "https":
        return super().connection_from_host(
            host, port, scheme, pool_kwargs=pool_kwargs
        )

    return super().connection_from_host(
        self.proxy.host, self.proxy.port, self.proxy.scheme, pool_kwargs=pool_kwargs  # type: ignore[union-attr]
    )

def _set_proxy_headers(
    self, url: str, headers: typing.Mapping[str, str] | None = None
) -> typing.Mapping[str, str]:
    """
    Sets headers needed by proxies: specifically, the Accept and Host
    headers. Only sets headers not provided by the user.
    """
    headers_ = {"Accept": "*/*"}

    netloc = parse_url(url).netloc
    if netloc:
        headers_["Host"] = netloc

    if headers:
        headers_.update(headers)
    return headers_

def decompress(self, data: bytes) -> bytes:
    if not data:
        return data

    if not self._first_try:
        return self._obj.decompress(data)

    self._data += data
    try:
        decompressed = self._obj.decompress(data)
        if decompressed:
            self._first_try = False
            self._data = None  # type: ignore[assignment]
        return decompressed
    except zlib.error:
        self._first_try = False
        self._obj = zlib.decompressobj(-zlib.MAX_WBITS)
        try:
            return self.decompress(self._data)
        finally:
            self._data = None  # type: ignore[assignment]

def __init__(self) -> None:
    self._obj = zlib.decompressobj(16 + zlib.MAX_WBITS)
    self._state = GzipDecoderState.FIRST_MEMBER

def decompress(self, data: bytes) -> bytes:
    ret = bytearray()
    if self._state == GzipDecoderState.SWALLOW_DATA or not data:
        return bytes(ret)
    while True:
        try:
            ret += self._obj.decompress(data)
        except zlib.error:
            previous_state = self._state
            # Ignore data after the first error
            self._state = GzipDecoderState.SWALLOW_DATA
            if previous_state == GzipDecoderState.OTHER_MEMBERS:
                # Allow trailing garbage acceptable in other gzip clients
                return bytes(ret)
            raise
        data = self._obj.unused_data
        if not data:
            return bytes(ret)
        self._state = GzipDecoderState.OTHER_MEMBERS
        self._obj = zlib.decompressobj(16 + zlib.MAX_WBITS)

def __init__(self) -> None:
    self._obj = brotli.Decompressor()
    if hasattr(self._obj, "decompress"):
        setattr(self, "decompress", self._obj.decompress)
    else:
        setattr(self, "decompress", self._obj.process)

def flush(self) -> bytes:
    if hasattr(self._obj, "flush"):
        return self._obj.flush()  # type: ignore[no-any-return]
    return b""

def decompress(self, data: bytes) -> bytes:
    if not data:
        return b""
    data_parts = [self._obj.decompress(data)]
    while self._obj.eof and self._obj.unused_data:
        unused_data = self._obj.unused_data
        self._obj = zstd.ZstdDecompressor()
        data_parts.append(self._obj.decompress(unused_data))
    return b"".join(data_parts)

def flush(self) -> bytes:
    if not self._obj.eof:
        raise DecodeError("Zstandard data is incomplete")
    return b""

def decompress(self, data: bytes) -> bytes:
    if not data:
        return b""
    data_parts = [self._obj.decompress(data)]
    while self._obj.eof and self._obj.unused_data:
        unused_data = self._obj.unused_data
        self._obj = zstd.ZstdDecompressor().decompressobj()
        data_parts.append(self._obj.decompress(unused_data))
    return b"".join(data_parts)

def flush(self) -> bytes:
    ret = self._obj.flush()  # note: this is a no-op
    if not self._obj.eof:
        raise DecodeError("Zstandard data is incomplete")
    return ret  # type: ignore[no-any-return]

def decompress(self, data: bytes) -> bytes:
    for d in reversed(self._decoders):
        data = d.decompress(data)
    return data

def _get_decoder(mode: str) -> ContentDecoder:
    if "," in mode:
        return MultiDecoder(mode)

    # According to RFC 9110 section 8.4.1.3, recipients should
    # consider x-gzip equivalent to gzip
    if mode in ("gzip", "x-gzip"):
        return GzipDecoder()

    if brotli is not None and mode == "br":
        return BrotliDecoder()

    if HAS_ZSTD and mode == "zstd":
        return ZstdDecoder()

    return DeflateDecoder()

def __init__(self) -> None:
    self.buffer: typing.Deque[bytes] = collections.deque()
    self._size: int = 0

def put(self, data: bytes) -> None:
    self.buffer.append(data)
    self._size += len(data)

def get(self, n: int) -> bytes:
    if n == 0:
        return b""
    elif not self.buffer:
        raise RuntimeError("buffer is empty")
    elif n < 0:
        raise ValueError("n should be > 0")

    fetched = 0
    ret = io.BytesIO()
    while fetched < n:
        remaining = n - fetched
        chunk = self.buffer.popleft()
        chunk_length = len(chunk)
        if remaining < chunk_length:
            left_chunk, right_chunk = chunk[:remaining], chunk[remaining:]
            ret.write(left_chunk)
            self.buffer.appendleft(right_chunk)
            self._size -= remaining
            break
        else:
            ret.write(chunk)
            self._size -= chunk_length
        fetched += chunk_length

        if not self.buffer:
            break

    return ret.getvalue()

def get_all(self) -> bytes:
    buffer = self.buffer
    if not buffer:
        assert self._size == 0
        return b""
    if len(buffer) == 1:
        result = buffer.pop()
    else:
        ret = io.BytesIO()
        ret.writelines(buffer.popleft() for _ in range(len(buffer)))
        result = ret.getvalue()
    self._size = 0
    return result

def get_redirect_location(self) -> str | None | typing.Literal[False]:
    """
    Should we redirect and where to?

    :returns: Truthy redirect location string if we got a redirect status
        code and valid location. ``None`` if redirect status and no
        location. ``False`` if not a redirect status code.
    """
    if self.status in self.REDIRECT_STATUSES:
        return self.headers.get("location")
    return False

@property
def retries(self) -> Retry | None:
    return self._retries

@retries.setter
def retries(self, retries: Retry | None) -> None:
    # Override the request_url if retries has a redirect location.
    if retries is not None and retries.history:
        self.url = retries.history[-1].redirect_location
    self._retries = retries

def _init_decoder(self) -> None:
    """
    Set-up the _decoder attribute if necessary.
    """
    # Note: content-encoding value should be case-insensitive, per RFC 7230
    # Section 3.2
    content_encoding = self.headers.get("content-encoding", "").lower()
    if self._decoder is None:
        if content_encoding in self.CONTENT_DECODERS:
            self._decoder = _get_decoder(content_encoding)
        elif "," in content_encoding:
            encodings = [
                e.strip()
                for e in content_encoding.split(",")
                if e.strip() in self.CONTENT_DECODERS
            ]
            if encodings:
                self._decoder = _get_decoder(content_encoding)

def _decode(
    self, data: bytes, decode_content: bool | None, flush_decoder: bool
) -> bytes:
    """
    Decode the data passed in and potentially flush the decoder.
    """
    if not decode_content:
        if self._has_decoded_content:
            raise RuntimeError(
                "Calling read(decode_content=False) is not supported after "
                "read(decode_content=True) was called."
            )
        return data

    try:
        if self._decoder:
            data = self._decoder.decompress(data)
            self._has_decoded_content = True
    except self.DECODER_ERROR_CLASSES as e:
        content_encoding = self.headers.get("content-encoding", "").lower()
        raise DecodeError(
            "Received response with content-encoding: %s, but "
            "failed to decode it." % content_encoding,
            e,
        ) from e
    if flush_decoder:
        data += self._flush_decoder()

    return data

def _flush_decoder(self) -> bytes:
    """
    Flushes the decoder. Should only be called if the decoder is actually
    being used.
    """
    if self._decoder:
        return self._decoder.decompress(b"") + self._decoder.flush()
    return b""

def readinto(self, b: bytearray) -> int:
    temp = self.read(len(b))
    if len(temp) == 0:
        return 0
    else:
        b[: len(temp)] = temp
        return len(temp)

def getheader(self, name: str, default: str | None = None) -> str | None:
    warnings.warn(
        "HTTPResponse.getheader() is deprecated and will be removed "
        "in urllib3 v2.6.0. Instead use HTTPResponse.headers.get(name, default).",
        category=DeprecationWarning,
        stacklevel=2,
    )
    return self.headers.get(name, default)

def release_conn(self) -> None:
    if not self._pool or not self._connection:
        return None

    self._pool._put_conn(self._connection)
    self._connection = None

def drain_conn(self) -> None:
    """
    Read and discard any remaining HTTP response data in the response connection.

    Unread data in the HTTPResponse connection blocks the connection from being released back to the pool.
    """
    try:
        self.read()
    except (HTTPError, OSError, BaseSSLError, HTTPException):
        pass

@property
def data(self) -> bytes:
    # For backwards-compat with earlier urllib3 0.4 and earlier.
    if self._body:
        return self._body  # type: ignore[return-value]

    if self._fp:
        return self.read(cache_content=True)

    return None  # type: ignore[return-value]

@property
def connection(self) -> HTTPConnection | None:
    return self._connection

def read1(
    self,
    amt: int | None = None,
    decode_content: bool | None = None,
) -> bytes:
    """
    Similar to ``http.client.HTTPResponse.read1`` and documented
    in :meth:`io.BufferedReader.read1`, but with an additional parameter:
    ``decode_content``.

    :param amt:
        How much of the content to read.

    :param decode_content:
        If True, will attempt to decode the body based on the
        'content-encoding' header.
    """
    if decode_content is None:
        decode_content = self.decode_content
    if amt and amt < 0:
        # Negative numbers and `None` should be treated the same.
        amt = None
    # try and respond without going to the network
    if self._has_decoded_content:
        if not decode_content:
            raise RuntimeError(
                "Calling read1(decode_content=False) is not supported after "
                "read1(decode_content=True) was called."
            )
        if len(self._decoded_buffer) > 0:
            if amt is None:
                return self._decoded_buffer.get_all()
            return self._decoded_buffer.get(amt)
    if amt == 0:
        return b""

    # FIXME, this method's type doesn't say returning None is possible
    data = self._raw_read(amt, read1=True)
    if not decode_content or data is None:
        return data

    self._init_decoder()
    while True:
        flush_decoder = not data
        decoded_data = self._decode(data, decode_content, flush_decoder)
        self._decoded_buffer.put(decoded_data)
        if decoded_data or flush_decoder:
            break
        data = self._raw_read(8192, read1=True)

    if amt is None:
        return self._decoded_buffer.get_all()
    return self._decoded_buffer.get(amt)

def shutdown(self) -> None:
    if not self._sock_shutdown:
        raise ValueError("Cannot shutdown socket as self._sock_shutdown is not set")
    if self._connection is None:
        raise RuntimeError(
            "Cannot shutdown as connection has already been released to the pool"
        )
    self._sock_shutdown(socket.SHUT_RD)

def close(self) -> None:
    self._sock_shutdown = None

    if not self.closed and self._fp:
        self._fp.close()

    if self._connection:
        self._connection.close()

    if not self.auto_close:
        io.IOBase.close(self)

@property
def closed(self) -> bool:
    if not self.auto_close:
        return io.IOBase.closed.__get__(self)  # type: ignore[no-any-return]
    elif self._fp is None:
        return True
    elif hasattr(self._fp, "isclosed"):
        return self._fp.isclosed()
    elif hasattr(self._fp, "closed"):
        return self._fp.closed
    else:
        return True

def fileno(self) -> int:
    if self._fp is None:
        raise OSError("HTTPResponse has no file to get a fileno from")
    elif hasattr(self._fp, "fileno"):
        return self._fp.fileno()
    else:
        raise OSError(
            "The file-like object this HTTPResponse is wrapped "
            "around has no file descriptor"
        )

def flush(self) -> None:
    if (
        self._fp is not None
        and hasattr(self._fp, "flush")
        and not getattr(self._fp, "closed", False)
    ):
        return self._fp.flush()

def _update_chunk_length(self) -> None:
    # First, we'll figure out length of a chunk and then
    # we'll try to read it from socket.
    if self.chunk_left is not None:
        return None
    line = self._fp.fp.readline()  # type: ignore[union-attr]
    line = line.split(b";", 1)[0]
    try:
        self.chunk_left = int(line, 16)
    except ValueError:
        self.close()
        if line:
            # Invalid chunked protocol response, abort.
            raise InvalidChunkLength(self, line) from None
        else:
            # Truncated at start of next chunk
            raise ProtocolError("Response ended prematurely") from None

@url.setter
def url(self, url: str) -> None:
    self._request_url = url

def __iter__(self) -> typing.Iterator[bytes]:
    buffer: list[bytes] = []
    for chunk in self.stream(decode_content=True):
        if b"\n" in chunk:
            chunks = chunk.split(b"\n")
            yield b"".join(buffer) + chunks[0] + b"\n"
            for x in chunks[1:-1]:
                yield x + b"\n"
            if chunks[-1]:
                buffer = [chunks[-1]]
            else:
                buffer = []
        else:
            buffer.append(chunk)
    if buffer:
        yield b"".join(buffer)

def _set_socket_options(
    sock: socket.socket, options: _TYPE_SOCKET_OPTIONS | None
) -> None:
    if options is None:
        return

    for opt in options:
        sock.setsockopt(*opt)

def set_file_position(
    body: typing.Any, pos: _TYPE_BODY_POSITION | None
) -> _TYPE_BODY_POSITION | None:
    """
    If a position is provided, move file to that point.
    Otherwise, we'll attempt to record a position for future use.
    """
    if pos is not None:
        rewind_body(body, pos)
    elif getattr(body, "tell", None) is not None:
        try:
            pos = body.tell()
        except OSError:
            # This differentiates from None, allowing us to catch
            # a failed `tell()` later when trying to rewind the body.
            pos = _FAILEDTELL

    return pos

def rewind_body(body: typing.IO[typing.AnyStr], body_pos: _TYPE_BODY_POSITION) -> None:
    """
    Attempt to rewind body to a certain position.
    Primarily used for request redirects and retries.

    :param body:
        File-like object that supports seek.

    :param int pos:
        Position to seek to in file.
    """
    body_seek = getattr(body, "seek", None)
    if body_seek is not None and isinstance(body_pos, int):
        try:
            body_seek(body_pos)
        except OSError as e:
            raise UnrewindableBodyError(
                "An error occurred when rewinding request body for redirect/retry."
            ) from e
    elif body_pos is _FAILEDTELL:
        raise UnrewindableBodyError(
            "Unable to record file position for rewinding "
            "request body during a redirect/retry."
        )
    else:
        raise ValueError(
            f"body_pos must be of type integer, instead it was {type(body_pos)}."
        )

def body_to_chunks(
    body: typing.Any | None, method: str, blocksize: int
) -> ChunksAndContentLength:
    """Takes the HTTP request method, body, and blocksize and
    transforms them into an iterable of chunks to pass to
    socket.sendall() and an optional 'Content-Length' header.

    A 'Content-Length' of 'None' indicates the length of the body
    can't be determined so should use 'Transfer-Encoding: chunked'
    for framing instead.
    """

    chunks: typing.Iterable[bytes] | None
    content_length: int | None

    # No body, we need to make a recommendation on 'Content-Length'
    # based on whether that request method is expected to have
    # a body or not.
    if body is None:
        chunks = None
        if method.upper() not in _METHODS_NOT_EXPECTING_BODY:
            content_length = 0
        else:
            content_length = None

    # Bytes or strings become bytes
    elif isinstance(body, (str, bytes)):
        chunks = (to_bytes(body),)
        content_length = len(chunks[0])

    # File-like object, TODO: use seek() and tell() for length?
    elif hasattr(body, "read"):

        def chunk_readable() -> typing.Iterable[bytes]:
            nonlocal body, blocksize
            encode = isinstance(body, io.TextIOBase)
            while True:
                datablock = body.read(blocksize)
                if not datablock:
                    break
                if encode:
                    datablock = datablock.encode("utf-8")
                yield datablock

        chunks = chunk_readable()
        content_length = None

    # Otherwise we need to start checking via duck-typing.
    else:
        try:
            # Check if the body implements the buffer API.
            mv = memoryview(body)
        except TypeError:
            try:
                # Check if the body is an iterable
                chunks = iter(body)
                content_length = None
            except TypeError:
                raise TypeError(
                    f"'body' must be a bytes-like object, file-like "
                    f"object, or iterable. Instead was {body!r}"
                ) from None
        else:
            # Since it implements the buffer API can be passed directly to socket.sendall()
            chunks = (body,)
            content_length = mv.nbytes

    return ChunksAndContentLength(chunks=chunks, content_length=content_length)

def chunk_readable() -> typing.Iterable[bytes]:
    nonlocal body, blocksize
    encode = isinstance(body, io.TextIOBase)
    while True:
        datablock = body.read(blocksize)
        if not datablock:
            break
        if encode:
            datablock = datablock.encode("utf-8")
        yield datablock

@classmethod
def from_int(
    cls,
    retries: Retry | bool | int | None,
    redirect: bool | int | None = True,
    default: Retry | bool | int | None = None,
) -> Retry:
    """Backwards-compatibility for the old retries format."""
    if retries is None:
        retries = default if default is not None else cls.DEFAULT

    if isinstance(retries, Retry):
        return retries

    redirect = bool(redirect) and None
    new_retries = cls(retries, redirect=redirect)
    log.debug("Converted retries value: %r -> %r", retries, new_retries)
    return new_retries

def get_backoff_time(self) -> float:
    """Formula for computing the current backoff

    :rtype: float
    """
    # We want to consider only the last consecutive errors sequence (Ignore redirects).
    consecutive_errors_len = len(
        list(
            takewhile(lambda x: x.redirect_location is None, reversed(self.history))
        )
    )
    if consecutive_errors_len <= 1:
        return 0

    backoff_value = self.backoff_factor * (2 ** (consecutive_errors_len - 1))
    if self.backoff_jitter != 0.0:
        backoff_value += random.random() * self.backoff_jitter
    return float(max(0, min(self.backoff_max, backoff_value)))

def parse_retry_after(self, retry_after: str) -> float:
    seconds: float
    # Whitespace: https://tools.ietf.org/html/rfc7230#section-3.2.4
    if re.match(r"^\s*[0-9]+\s*$", retry_after):
        seconds = int(retry_after)
    else:
        retry_date_tuple = email.utils.parsedate_tz(retry_after)
        if retry_date_tuple is None:
            raise InvalidHeader(f"Invalid Retry-After header: {retry_after}")

        retry_date = email.utils.mktime_tz(retry_date_tuple)
        seconds = retry_date - time.time()

    seconds = max(seconds, 0)

    return seconds

def get_retry_after(self, response: BaseHTTPResponse) -> float | None:
    """Get the value of Retry-After in seconds."""

    retry_after = response.headers.get("Retry-After")

    if retry_after is None:
        return None

    return self.parse_retry_after(retry_after)

def sleep_for_retry(self, response: BaseHTTPResponse) -> bool:
    retry_after = self.get_retry_after(response)
    if retry_after:
        time.sleep(retry_after)
        return True

    return False

def _sleep_backoff(self) -> None:
    backoff = self.get_backoff_time()
    if backoff <= 0:
        return
    time.sleep(backoff)

def _is_connection_error(self, err: Exception) -> bool:
    """Errors when we're fairly sure that the server did not receive the
    request, so it should be safe to retry.
    """
    if isinstance(err, ProxyError):
        err = err.original_error
    return isinstance(err, ConnectTimeoutError)

def _is_read_error(self, err: Exception) -> bool:
    """Errors that occur after the request has been started, so we should
    assume that the server began processing it.
    """
    return isinstance(err, (ReadTimeoutError, ProtocolError))

def is_retry(
    self, method: str, status_code: int, has_retry_after: bool = False
) -> bool:
    """Is this method/status code retryable? (Based on allowlists and control
    variables such as the number of total retries to allow, whether to
    respect the Retry-After header, whether this header is present, and
    whether the returned status code is on the list of status codes to
    be retried upon on the presence of the aforementioned header)
    """
    if not self._is_method_retryable(method):
        return False

    if self.status_forcelist and status_code in self.status_forcelist:
        return True

    return bool(
        self.total
        and self.respect_retry_after_header
        and has_retry_after
        and (status_code in self.RETRY_AFTER_STATUS_CODES)
    )

def __repr__(self) -> str:
    return (
        f"{type(self).__name__}(total={self.total}, connect={self.connect}, "
        f"read={self.read}, redirect={self.redirect}, status={self.status})"
    )

def resolve_ssl_version(candidate: None | int | str) -> int:
    """
    like resolve_cert_reqs
    """
    if candidate is None:
        return PROTOCOL_TLS

    if isinstance(candidate, str):
        res = getattr(ssl, candidate, None)
        if res is None:
            res = getattr(ssl, "PROTOCOL_" + candidate)
        return typing.cast(int, res)

    return candidate

def is_ipaddress(hostname: str | bytes) -> bool:
    """Detects whether the hostname given is an IPv4 or IPv6 address.
    Also detects IPv6 addresses with Zone IDs.

    :param str hostname: Hostname to examine.
    :return: True if the hostname is an IP address, False otherwise.
    """
    if isinstance(hostname, bytes):
        # IDN A-label bytes are ASCII compatible.
        hostname = hostname.decode("ascii")
    return bool(_IPV4_RE.match(hostname) or _BRACELESS_IPV6_ADDRZ_RE.match(hostname))

def _is_key_file_encrypted(key_file: str) -> bool:
    """Detects if a key file is encrypted or not."""
    with open(key_file) as f:
        for line in f:
            # Look for Proc-Type: 4,ENCRYPTED
            if "ENCRYPTED" in line:
                return True

    return False

def _ssl_wrap_socket_impl(
    sock: socket.socket,
    ssl_context: ssl.SSLContext,
    tls_in_tls: bool,
    server_hostname: str | None = None,
) -> ssl.SSLSocket | SSLTransportType:
    if tls_in_tls:
        if not SSLTransport:
            # Import error, ssl is not available.
            raise ProxySchemeUnsupported(
                "TLS in TLS requires support for the 'ssl' module"
            )

        SSLTransport._validate_ssl_context_for_tls_in_tls(ssl_context)
        return SSLTransport(sock, ssl_context, server_hostname)

    return ssl_context.wrap_socket(sock, server_hostname=server_hostname)

def match_hostname(
    cert: _TYPE_PEER_CERT_RET_DICT | None,
    hostname: str,
    hostname_checks_common_name: bool = False,
) -> None:
    """Verify that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125
    rules are followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing.
    """
    if not cert:
        raise ValueError(
            "empty or no certificate, match_hostname needs a "
            "SSL socket or SSL context with either "
            "CERT_OPTIONAL or CERT_REQUIRED"
        )
    try:
        # Divergence from upstream: ipaddress can't handle byte str
        #
        # The ipaddress module shipped with Python < 3.9 does not support
        # scoped IPv6 addresses so we unconditionally strip the Zone IDs for
        # now. Once we drop support for Python 3.9 we can remove this branch.
        if "%" in hostname:
            host_ip = ipaddress.ip_address(hostname[: hostname.rfind("%")])
        else:
            host_ip = ipaddress.ip_address(hostname)

    except ValueError:
        # Not an IP address (common case)
        host_ip = None
    dnsnames = []
    san: tuple[tuple[str, str], ...] = cert.get("subjectAltName", ())
    key: str
    value: str
    for key, value in san:
        if key == "DNS":
            if host_ip is None and _dnsname_match(value, hostname):
                return
            dnsnames.append(value)
        elif key == "IP Address":
            if host_ip is not None and _ipaddress_match(value, host_ip):
                return
            dnsnames.append(value)

    # We only check 'commonName' if it's enabled and we're not verifying
    # an IP address. IP addresses aren't valid within 'commonName'.
    if hostname_checks_common_name and host_ip is None and not dnsnames:
        for sub in cert.get("subject", ()):
            for key, value in sub:
                if key == "commonName":
                    if _dnsname_match(value, hostname):
                        return
                    dnsnames.append(value)  # Defensive: for Python < 3.9.3

    if len(dnsnames) > 1:
        raise CertificateError(
            "hostname %r "
            "doesn't match either of %s" % (hostname, ", ".join(map(repr, dnsnames)))
        )
    elif len(dnsnames) == 1:
        raise CertificateError(f"hostname {hostname!r} doesn't match {dnsnames[0]!r}")
    else:
        raise CertificateError("no appropriate subjectAltName fields were found")

@staticmethod
def _validate_ssl_context_for_tls_in_tls(ssl_context: ssl.SSLContext) -> None:
    """
    Raises a ProxySchemeUnsupported if the provided ssl_context can't be used
    for TLS in TLS.

    The only requirement is that the ssl_context provides the 'wrap_bio'
    methods.
    """

    if not hasattr(ssl_context, "wrap_bio"):
        raise ProxySchemeUnsupported(
            "TLS in TLS requires SSLContext.wrap_bio() which isn't "
            "available on non-native SSLContext"
        )

def recv(self, buflen: int = 1024, flags: int = 0) -> int | bytes:
    if flags != 0:
        raise ValueError("non-zero flags not allowed in calls to recv")
    return self._wrap_ssl_read(buflen)

def recv_into(
    self,
    buffer: _WriteBuffer,
    nbytes: int | None = None,
    flags: int = 0,
) -> None | int | bytes:
    if flags != 0:
        raise ValueError("non-zero flags not allowed in calls to recv_into")
    if nbytes is None:
        nbytes = len(buffer)
    return self.read(nbytes, buffer)

def sendall(self, data: bytes, flags: int = 0) -> None:
    if flags != 0:
        raise ValueError("non-zero flags not allowed in calls to sendall")
    count = 0
    with memoryview(data) as view, view.cast("B") as byte_view:
        amount = len(byte_view)
        while count < amount:
            v = self.send(byte_view[count:])
            count += v

def send(self, data: bytes, flags: int = 0) -> int:
    if flags != 0:
        raise ValueError("non-zero flags not allowed in calls to send")
    return self._ssl_io_loop(self.sslobj.write, data)

def _wrap_ssl_read(self, len: int, buffer: bytearray | None = None) -> int | bytes:
    try:
        return self._ssl_io_loop(self.sslobj.read, len, buffer)
    except ssl.SSLError as e:
        if e.errno == ssl.SSL_ERROR_EOF and self.suppress_ragged_eofs:
            return 0  # eof, return 0.
        else:
            raise

def _ssl_io_loop(
    self,
    func: typing.Callable[..., _ReturnValue],
    arg1: None | bytes | int = None,
    arg2: bytearray | None = None,
) -> _ReturnValue:
    """Performs an I/O loop between incoming/outgoing and the socket."""
    should_loop = True
    ret = None

    while should_loop:
        errno = None
        try:
            if arg1 is None and arg2 is None:
                ret = func()
            elif arg2 is None:
                ret = func(arg1)
            else:
                ret = func(arg1, arg2)
        except ssl.SSLError as e:
            if e.errno not in (ssl.SSL_ERROR_WANT_READ, ssl.SSL_ERROR_WANT_WRITE):
                # WANT_READ, and WANT_WRITE are expected, others are not.
                raise e
            errno = e.errno

        buf = self.outgoing.read()
        self.socket.sendall(buf)

        if errno is None:
            should_loop = False
        elif errno == ssl.SSL_ERROR_WANT_READ:
            buf = self.socket.recv(SSL_BLOCKSIZE)
            if buf:
                self.incoming.write(buf)
            else:
                self.incoming.write_eof()
    return typing.cast(_ReturnValue, ret)

@staticmethod
def resolve_default_timeout(timeout: _TYPE_TIMEOUT) -> float | None:
    return getdefaulttimeout() if timeout is _DEFAULT_TIMEOUT else timeout

@classmethod
def _validate_timeout(cls, value: _TYPE_TIMEOUT, name: str) -> _TYPE_TIMEOUT:
    """Check that a timeout attribute is valid.

    :param value: The timeout value to validate
    :param name: The name of the timeout attribute to validate. This is
        used to specify in error messages.
    :return: The validated and casted version of the given value.
    :raises ValueError: If it is a numeric value less than or equal to
        zero, or the type is not an integer, float, or None.
    """
    if value is None or value is _DEFAULT_TIMEOUT:
        return value

    if isinstance(value, bool):
        raise ValueError(
            "Timeout cannot be a boolean value. It must "
            "be an int, float or None."
        )
    try:
        float(value)
    except (TypeError, ValueError):
        raise ValueError(
            "Timeout value %s was %s, but it must be an "
            "int, float or None." % (name, value)
        ) from None

    try:
        if value <= 0:
            raise ValueError(
                "Attempted to set %s timeout to %s, but the "
                "timeout cannot be set to a value less "
                "than or equal to 0." % (name, value)
            )
    except TypeError:
        raise ValueError(
            "Timeout value %s was %s, but it must be an "
            "int, float or None." % (name, value)
        ) from None

    return value

@property
def connect_timeout(self) -> _TYPE_TIMEOUT:
    """Get the value to use when setting a connection timeout.

    This will be a positive float or integer, the value None
    (never timeout), or the default system timeout.

    :return: Connect timeout.
    :rtype: int, float, :attr:`Timeout.DEFAULT_TIMEOUT` or None
    """
    if self.total is None:
        return self._connect

    if self._connect is None or self._connect is _DEFAULT_TIMEOUT:
        return self.total

    return min(self._connect, self.total)  # type: ignore[type-var]

@property
def read_timeout(self) -> float | None:
    """Get the value for the read timeout.

    This assumes some time has elapsed in the connection timeout and
    computes the read timeout appropriately.

    If self.total is set, the read timeout is dependent on the amount of
    time taken by the connect timeout. If the connection time has not been
    established, a :exc:`~urllib3.exceptions.TimeoutStateError` will be
    raised.

    :return: Value to use for the read timeout.
    :rtype: int, float or None
    :raises urllib3.exceptions.TimeoutStateError: If :meth:`start_connect`
        has not yet been called on this object.
    """
    if (
        self.total is not None
        and self.total is not _DEFAULT_TIMEOUT
        and self._read is not None
        and self._read is not _DEFAULT_TIMEOUT
    ):
        # In case the connect timeout has not yet been established.
        if self._start_connect is None:
            return self._read
        return max(0, min(self.total - self.get_connect_duration(), self._read))
    elif self.total is not None and self.total is not _DEFAULT_TIMEOUT:
        return max(0, self.total - self.get_connect_duration())
    else:
        return self.resolve_default_timeout(self._read)

@property
def hostname(self) -> str | None:
    """For backwards-compatibility with urlparse. We're nice like that."""
    return self.host

@property
def request_uri(self) -> str:
    """Absolute path including the query string."""
    uri = self.path or "/"

    if self.query is not None:
        uri += "?" + self.query

    return uri

@property
def netloc(self) -> str | None:
    """
    Network location including host and port.

    If you need the equivalent of urllib.parse's ``netloc``,
    use the ``authority`` property instead.
    """
    if self.host is None:
        return None
    if self.port:
        return f"{self.host}:{self.port}"
    return self.host

def _remove_path_dot_segments(path: str) -> str:
    # See http://tools.ietf.org/html/rfc3986#section-5.2.4 for pseudo-code
    segments = path.split("/")  # Turn the path into a list of segments
    output = []  # Initialize the variable to use to store output

    for segment in segments:
        # '.' is the current directory, so ignore it, it is superfluous
        if segment == ".":
            continue
        # Anything other than '..', should be appended to the output
        if segment != "..":
            output.append(segment)
        # In this case segment == '..', if we can, we should pop the last
        # element
        elif output:
            output.pop()

    # If the path starts with '/' and the output is empty or the first string
    # is non-empty
    if path.startswith("/") and (not output or output[0]):
        output.insert(0, "")

    # If the path starts with '/.' or '/..' ensure we add one more empty
    # string to add a trailing '/'
    if path.endswith(("/.", "/..")):
        output.append("")

    return "/".join(output)

def _normalize_host(host: str | None, scheme: str | None) -> str | None:
    if host:
        if scheme in _NORMALIZABLE_SCHEMES:
            is_ipv6 = _IPV6_ADDRZ_RE.match(host)
            if is_ipv6:
                # IPv6 hosts of the form 'a::b%zone' are encoded in a URL as
                # such per RFC 6874: 'a::b%25zone'. Unquote the ZoneID
                # separator as necessary to return a valid RFC 4007 scoped IP.
                match = _ZONE_ID_RE.search(host)
                if match:
                    start, end = match.span(1)
                    zone_id = host[start:end]

                    if zone_id.startswith("%25") and zone_id != "%25":
                        zone_id = zone_id[3:]
                    else:
                        zone_id = zone_id[1:]
                    zone_id = _encode_invalid_chars(zone_id, _UNRESERVED_CHARS)
                    return f"{host[:start].lower()}%{zone_id}{host[end:]}"
                else:
                    return host.lower()
            elif not _IPV4_RE.match(host):
                return to_str(
                    b".".join([_idna_encode(label) for label in host.split(".")]),
                    "ascii",
                )
    return host

def _idna_encode(name: str) -> bytes:
    if not name.isascii():
        try:
            import idna
        except ImportError:
            raise LocationParseError(
                "Unable to parse URL without the 'idna' module"
            ) from None

        try:
            return idna.encode(name.lower(), strict=True, std3_rules=True)
        except idna.IDNAError:
            raise LocationParseError(
                f"Name '{name}' is not a valid IDNA label"
            ) from None

    return name.lower().encode("ascii")

def to_bytes(
    x: str | bytes, encoding: str | None = None, errors: str | None = None
) -> bytes:
    if isinstance(x, bytes):
        return x
    elif not isinstance(x, str):
        raise TypeError(f"not expecting type {type(x).__name__}")
    if encoding or errors:
        return x.encode(encoding or "utf-8", errors=errors or "strict")
    return x.encode()

def to_str(
    x: str | bytes, encoding: str | None = None, errors: str | None = None
) -> str:
    if isinstance(x, str):
        return x
    elif not isinstance(x, bytes):
        raise TypeError(f"not expecting type {type(x).__name__}")
    if encoding or errors:
        return x.decode(encoding or "utf-8", errors=errors or "strict")
    return x.decode()

def reraise(
    tp: type[BaseException] | None,
    value: BaseException,
    tb: TracebackType | None = None,
) -> typing.NoReturn:
    try:
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value
    finally:
        value = None  # type: ignore[assignment]
        tb = None

def select_wait_for_socket(
    sock: socket.socket,
    read: bool = False,
    write: bool = False,
    timeout: float | None = None,
) -> bool:
    if not read and not write:
        raise RuntimeError("must specify at least one of read=True, write=True")
    rcheck = []
    wcheck = []
    if read:
        rcheck.append(sock)
    if write:
        wcheck.append(sock)
    # When doing a non-blocking connect, most systems signal success by
    # marking the socket writable. Windows, though, signals success by marked
    # it as "exceptional". We paper over the difference by checking the write
    # sockets for both conditions. (The stdlib selectors module does the same
    # thing.)
    fn = partial(select.select, rcheck, wcheck, wcheck)
    rready, wready, xready = fn(timeout)
    return bool(rready or wready or xready)

def poll_wait_for_socket(
    sock: socket.socket,
    read: bool = False,
    write: bool = False,
    timeout: float | None = None,
) -> bool:
    if not read and not write:
        raise RuntimeError("must specify at least one of read=True, write=True")
    mask = 0
    if read:
        mask |= select.POLLIN
    if write:
        mask |= select.POLLOUT
    poll_obj = select.poll()
    poll_obj.register(sock, mask)

    # For some reason, poll() takes timeout in milliseconds
    def do_poll(t: float | None) -> list[tuple[int, int]]:
        if t is not None:
            t *= 1000
        return poll_obj.poll(t)

    return bool(do_poll(timeout))

def do_poll(t: float | None) -> list[tuple[int, int]]:
    if t is not None:
        t *= 1000
    return poll_obj.poll(t)

def _have_working_poll() -> bool:
    # Apparently some systems have a select.poll that fails as soon as you try
    # to use it, either due to strange configuration or broken monkeypatching
    # from libraries like eventlet/greenlet.
    try:
        poll_obj = select.poll()
        poll_obj.poll(0)
    except (AttributeError, OSError):
        return False
    else:
        return True

def wait_for_socket(
    sock: socket.socket,
    read: bool = False,
    write: bool = False,
    timeout: float | None = None,
) -> bool:
    # We delay choosing which implementation to use until the first time we're
    # called. We could do it at import time, but then we might make the wrong
    # decision if someone goes wild with monkeypatching select.poll after
    # we're imported.
    global wait_for_socket
    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, "select"):
        wait_for_socket = select_wait_for_socket
    return wait_for_socket(sock, read, write, timeout)

def wait_for_read(sock: socket.socket, timeout: float | None = None) -> bool:
    """Waits for reading to be available on a given socket.
    Returns True if the socket is readable, or False if the timeout expired.
    """
    return wait_for_socket(sock, read=True, timeout=timeout)

def wait_for_write(sock: socket.socket, timeout: float | None = None) -> bool:
    """Waits for writing to be available on a given socket.
    Returns True if the socket is readable, or False if the timeout expired.
    """
    return wait_for_socket(sock, write=True, timeout=timeout)
